/* Source transcription from uploaded JVVNL-JA-IncomeTax-QuestionBank-437Q PDF. Original wording/keys preserved except audit flags are metadata only. */
window.INCOME_TAX_DEEP_BANK = [{"id":1,"stem":"For income-tax purposes in India, the financial year in which income is EARNED is called the:","options":[{"key":"A","text":"Previous year"},{"key":"B","text":"Accounting year"},{"key":"C","text":"Tax deduction year"},{"key":"D","text":"Assessment year"}],"answer":"A","explanation":"Income is earned in the previous year and assessed to tax in the immediately following assessment year. Residential status is also tested with reference to the previous year.","source":"Source label not detected","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":2,"stem":"The assessment year is the period of 12 months:","options":[{"key":"A","text":"Starting from 1 January"},{"key":"B","text":"In which income is earned"},{"key":"C","text":"Immediately FOLLOWING the previous year, in which the income of the previous year is assessed and taxed"},{"key":"D","text":"Ending on 31 March of the earning year"}],"answer":"C","explanation":"AY 2026-27 (1-4-2026 to 31-3-2027) assesses the income of the previous year 2025-26 (1-4-2025 to 31-3-2026).","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":3,"stem":"A \"person\" under Section 2(31) of the Income-tax Act, 1961 includes all EXCEPT:","options":[{"key":"A","text":"A DECEASED person estate after probate is complete"},{"key":"B","text":"An individual and a Hindu Undivided Family"},{"key":"C","text":"A local authority and every artificial juridical person"},{"key":"D","text":"A company, a firm and an association of persons"}],"answer":"A","explanation":"Section 2(31) lists seven categories: individual, HUF, company, firm, AOP/BOI, local authority and every artificial juridical person. An estate is taxed through the legal representative/executor, not as a separate \"person\" category.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":4,"stem":"\"Assessee\" under Section 2(7) means a person:","options":[{"key":"A","text":"By whom any tax or any other sum of money is payable under the Act - and includes every person in respect of whom any proceeding has been taken"},{"key":"B","text":"Only salaried individuals"},{"key":"C","text":"Only a person whose income exceeds the exemption limit"},{"key":"D","text":"Who has filed his return"}],"answer":"A","explanation":"Every assessee is a person, but every person is not an assessee - a person becomes an assessee only when a liability or a proceeding under the Act attaches to him.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":5,"stem":"\"Income\" under Section 2(24) is:","options":[{"key":"A","text":"An INCLUSIVE definition - covering profits and gains, dividends, perquisites, capital gains, winnings and the other listed receipts"},{"key":"B","text":"Only income earned in India"},{"key":"C","text":"Limited to revenue receipts"},{"key":"D","text":"Only money received in cash"}],"answer":"A","explanation":"Section 2(24) begins \"income includes\" - an inclusive (not exhaustive) definition covering both cash and kind, legal and illegal, recurring and one-time receipts.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":6,"stem":"Income earned in previous year 2025-26 is taxable in assessment year:","options":[{"key":"A","text":"2025-26"},{"key":"B","text":"2027-28"},{"key":"C","text":"2026-27"},{"key":"D","text":"2024-25"}],"answer":"C","explanation":"AY = PY + 1. Income of PY 2025-26 is assessed in AY 2026-27.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":7,"stem":"The rates of income tax for an assessment year are fixed by:","options":[{"key":"A","text":"The CBDT circulars"},{"key":"B","text":"The Income-tax Act, 1961 itself"},{"key":"C","text":"The annual FINANCE ACT passed by Parliament"},{"key":"D","text":"The President of India"}],"answer":"C","explanation":"The Finance Act of the year prescribes the rates; the Income-tax Act lays down the machinery for levy, computation and collection.","source":"Source label not detected","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":8,"stem":"The Central Board of Direct Taxes (CBDT) functions under the:","options":[{"key":"A","text":"Ministry of Finance (Department of Revenue)"},{"key":"B","text":"Reserve Bank of India"},{"key":"C","text":"Ministry of Corporate Affairs"},{"key":"D","text":"NITI Aayog"}],"answer":"A","explanation":"The CBDT administers direct taxes under the Department of Revenue, Ministry of Finance, and issues rules, notifications and circulars.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":9,"stem":"Which of the following is NOT a source for understanding income-tax law and procedure?","options":[{"key":"A","text":"The Income-tax Act, 1961 and Income-tax Rules, 1962"},{"key":"B","text":"Judicial decisions of courts"},{"key":"C","text":"SEBI listing regulations"},{"key":"D","text":"Notifications and circulars of the CBDT"}],"answer":"C","explanation":"Tax law rests on the Act, the Rules, CBDT subordinate legislation and case law; SEBI regulations govern securities markets, not income tax.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":10,"stem":"Gross total income means:","options":[{"key":"A","text":"Income exempt under Section 10"},{"key":"B","text":"Only salary income"},{"key":"C","text":"Income after all Chapter VI-A deductions"},{"key":"D","text":"The aggregate of income computed under the FIVE heads, BEFORE Chapter VI-A deductions"}],"answer":"D","explanation":"Section 80B(5): gross total income = total income computed under the five heads after clubbing and set-off, before deductions under Chapter VI-A (80C to 80U).","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":11,"stem":"The five heads of income under Section 14 do NOT include:","options":[{"key":"A","text":"Income from salaries"},{"key":"B","text":"Income from house property"},{"key":"C","text":"Income from LOTTERY and speculation as a separate head"},{"key":"D","text":"Profits and gains of business or profession"}],"answer":"C","explanation":"The five heads are: salaries, house property, business/profession, capital gains, and other sources. Lottery winnings fall under income from other sources - they are not a separate head.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":12,"stem":"Total income is arrived at by:","options":[{"key":"A","text":"Adding all receipts of the year"},{"key":"B","text":"Multiplying gross income by the slab rate"},{"key":"C","text":"Deducting Chapter VI-A deductions (80C-80U) from gross total income and rounding off under s.288A"},{"key":"D","text":"Deducting TDS from gross total income"}],"answer":"C","explanation":"GTI minus VI-A deductions = total income, rounded off to the nearest ten rupees (s.288A); tax is then computed on it.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":13,"stem":"Agricultural income in India is:","options":[{"key":"A","text":"EXEMPT under Section 10(1), but used for rate purposes (partial integration) for non-corporate assessees"},{"key":"B","text":"Taxable as business income"},{"key":"C","text":"Fully taxable at 30%"},{"key":"D","text":"Exempt only for companies"}],"answer":"A","explanation":"Agricultural income is exempt, but where it exceeds Rs.5,000 it is added to non-agricultural income to fix the slab RATE on the non-agricultural income (partial integration).","source":"Source label not detected","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":14,"stem":"Which of the following is AGRICULTURAL income?","options":[{"key":"A","text":"Rent or revenue derived from land situated in India and used for agricultural purposes"},{"key":"B","text":"Income from a dairy farm as such"},{"key":"C","text":"Salary received by a farm manager"},{"key":"D","text":"Income from selling wild grass of spontaneous growth without cultivation"}],"answer":"A","explanation":"Section 2(1A): rent/revenue from agricultural land, income from agricultural operations, and income from farm buildings are agricultural. Dairy/poultry income and spontaneous growth are not.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":15,"stem":"Income from growing and manufacturing TEA in India is split between agricultural and business income in the ratio:","options":[{"key":"A","text":"60% agricultural : 40% business"},{"key":"B","text":"40% agricultural : 60% business"},{"key":"C","text":"75% agricultural : 25% business"},{"key":"D","text":"50% : 50%"}],"answer":"A","explanation":"Rule 8 of the Income-tax Rules: 60% of tea-growing-cum-manufacturing income is agricultural and 40% is business income taxable under the Act.","source":"Source label not detected","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":16,"stem":"Coffee grown and cured by the assessee in India is split as (agricultural : business):","options":[{"key":"A","text":"50% : 50%"},{"key":"B","text":"60% : 40%"},{"key":"C","text":"65% : 35%"},{"key":"D","text":"75% : 25%"}],"answer":"D","explanation":"Rule 7B: coffee grown and cured = 75% agricultural, 25% business; coffee also roasted and ground = 60% agricultural, 40% business.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":17,"stem":"Rubber grown and manufactured by the assessee in India is treated as business income to the extent of:","options":[{"key":"A","text":"40%"},{"key":"B","text":"25%"},{"key":"C","text":"35%"},{"key":"D","text":"60%"}],"answer":"C","explanation":"Rule 7A: 35% of rubber income is business income and 65% is agricultural income.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":18,"stem":"Residential status of an assessee is determined with reference to the:","options":[{"key":"A","text":"Assessment year"},{"key":"B","text":"PREVIOUS YEAR (the year of earning)"},{"key":"C","text":"Calendar year"},{"key":"D","text":"Year of assessment completion"}],"answer":"B","explanation":"Section 6 applies the stay tests for each previous year separately; status can change from year to year.","source":"Source label not detected","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":19,"stem":"An individual is RESIDENT in India in a previous year if he is in India for:","options":[{"key":"A","text":"365 days in the previous year only"},{"key":"B","text":"Exactly 90 days"},{"key":"C","text":"At least 182 days during that year, OR 60 days in that year plus 365 days in the 4 preceding years"},{"key":"D","text":"At least 30 days"}],"answer":"C","explanation":"Section 6(1) has the two alternative tests: 182 days, or 60 days + 365 days in four preceding years (60 becomes 182 for citizens leaving for employment/crew and certain visitors).","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":20,"stem":"The \"60 days\" in the second residential test is extended to 182 days for:","options":[{"key":"A","text":"All foreign tourists"},{"key":"B","text":"All companies"},{"key":"C","text":"No one"},{"key":"D","text":"Indian citizens who leave India for employment abroad or as crew of an Indian ship, and Indian citizens/PIOs visiting India (subject to the 120-day rule for high-income visitors)"}],"answer":"D","explanation":"Explanation 1 to s.6(1) relaxes the 60-day condition to 182 days for these categories; for citizens/PIOs with Indian income above Rs.15 lakh, the 60 days becomes 120 days (from AY 2021-22).","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":21,"stem":"An Indian citizen having total income (other than foreign sources) exceeding Rs.15 lakh, who is NOT liable to tax in any other country by reason of domicile or residence, is:","options":[{"key":"A","text":"Always non-resident"},{"key":"B","text":"DEEMED to be RESIDENT in India under Section 6(1A) - and taxed as RNOR"},{"key":"C","text":"Exempt from Indian tax"},{"key":"D","text":"A person of Indian origin"}],"answer":"B","explanation":"Section 6(1A) (from AY 2021-22) targets stateless-income individuals; such deemed residents are treated as not ordinarily resident.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":22,"stem":"A resident individual is \"not ordinarily resident\" (RNOR) if he:","options":[{"key":"A","text":"Is above 60 years of age"},{"key":"B","text":"Owns no property in India"},{"key":"C","text":"Is a non-resident in 9 out of the 10 preceding years OR has been in India for 729 days or less during the 7 preceding years"},{"key":"D","text":"Has never been outside India"}],"answer":"C","explanation":"Section 6(6): either of the two conditions makes a resident \"not ordinarily resident\"; deemed residents under s.6(1A) are always RNOR.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":23,"stem":"A Hindu Undivided Family (HUF) is resident in India unless:","options":[{"key":"A","text":"It owns property abroad"},{"key":"B","text":"Its karta is a foreign citizen"},{"key":"C","text":"The control and management of its affairs is situated WHOLLY OUTSIDE India during the year"},{"key":"D","text":"It has foreign income"}],"answer":"C","explanation":"For HUF, firm, AOP and companies (turnover test aside), the control-and-management test applies: wholly outside India means non-resident.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Review note: company residency test is POEM, not control-and-management."},{"id":24,"stem":"A COMPANY is resident in India if:","options":[{"key":"A","text":"It pays dividend in India"},{"key":"B","text":"All its directors are Indians"},{"key":"C","text":"It is an Indian company, OR its place of effective management (POEM) is in India during the year"},{"key":"D","text":"It is listed on the NSE"}],"answer":"C","explanation":"Section 6(3): Indian companies are always resident; other companies are resident if their POEM is in India (POEM = where key management and commercial decisions are made in substance).","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":25,"stem":"The total income of a RESIDENT AND ORDINARILY RESIDENT (ROR) individual includes:","options":[{"key":"A","text":"Only salary income"},{"key":"B","text":"Only income received in India"},{"key":"C","text":"Income received/deemed received in India + income accruing or arising in India + income accruing OUTSIDE India (world income)"},{"key":"D","text":"Only Indian-source income"}],"answer":"C","explanation":"Section 5(1): a ROR is taxed on world income. RNOR and NR are taxed on Indian income plus foreign income only if from a business controlled or profession set up in India.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":26,"stem":"A NON-RESIDENT is taxable in India on:","options":[{"key":"A","text":"Foreign salary credited abroad"},{"key":"B","text":"Income received or deemed received in India and income accruing or arising or deemed to accrue or arise in India"},{"key":"C","text":"Income from a foreign business controlled abroad"},{"key":"D","text":"His world income"}],"answer":"B","explanation":"Section 5(2): non-residents pay Indian tax only on India-linked income - received in India or deemed to accrue or arise here (s.9).","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":27,"stem":"Which of the following incomes is DEEMED TO ACCRUE OR ARISE IN INDIA under Section 9(1)?","options":[{"key":"A","text":"Income from a property situated abroad"},{"key":"B","text":"Income from any business connection in India, and salary earned in India"},{"key":"C","text":"Salary of a non-resident earned wholly for services outside India"},{"key":"D","text":"Agricultural income from land in Sri Lanka"}],"answer":"B","explanation":"Section 9(1) deems Indian accrual for business-connection income, Indian property income, asset transfers in India and salary EARNED in India (services rendered here).","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":28,"stem":"Salary payable by the Government of India to an Indian citizen for services rendered OUTSIDE India is:","options":[{"key":"A","text":"Taxed only in the foreign country"},{"key":"B","text":"Exempt from Indian tax"},{"key":"C","text":"DEEMED to accrue in India and taxable in India (though allowances/perquisites for foreign service are exempt u/s 10(7))"},{"key":"D","text":"Treated as agricultural income"}],"answer":"C","explanation":"Section 9(1)(iii): Government salary for services abroad is deemed to accrue in India; the foreign allowances of such government servants are exempt under s.10(7).","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":29,"stem":"Income RECEIVED in India is taxable:","options":[{"key":"A","text":"Only for companies"},{"key":"B","text":"Never"},{"key":"C","text":"Only for residents"},{"key":"D","text":"In the hands of ALL assessees - resident or non-resident"}],"answer":"D","explanation":"Receipt basis applies to everyone: income first received in India is chargeable for every status category.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Review note: clarify that income is first received in India; later remittance alone is not receipt."},{"id":30,"stem":"Which of the following receipts is CAPITAL in nature and generally NOT taxable as income?","options":[{"key":"A","text":"Compensation for cancellation of a contract resulting in termination of the whole source of income"},{"key":"B","text":"Monthly rent"},{"key":"C","text":"Interest on bank deposits"},{"key":"D","text":"Monthly salary"}],"answer":"A","explanation":"A receipt replacing the very source of income (sterilising the profit-making apparatus) is capital; recurring receipts for services or use of assets are revenue.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":31,"stem":"Income earned by a minor child is generally:","options":[{"key":"A","text":"CLUBBED with the income of the parent having the higher income (s.64(1A)), except income from the child own skill/manual work"},{"key":"B","text":"Taxed separately as the child own income in all cases"},{"key":"C","text":"Taxed at 30% flat"},{"key":"D","text":"Always exempt"}],"answer":"A","explanation":"Clubbing applies except where the income arises from the child own manual work or specialised skill; the parent gets a s.10(32) exemption of Rs.1,500 per child.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":32,"stem":"Which of the following is EXEMPT from income tax?","options":[{"key":"A","text":"Salary arrears"},{"key":"B","text":"Interest on fixed deposits"},{"key":"C","text":"Agricultural income (s.10(1)) and receipts covered by Section 10 exemptions"},{"key":"D","text":"Lottery winnings"}],"answer":"C","explanation":"Section 10 lists exempt incomes - agricultural income, HUF member share, certain allowances, gratuity within limits, etc. Interest and lottery are fully taxable.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":33,"stem":"The share of profit received by a partner from his partnership firm is:","options":[{"key":"A","text":"Taxable as business income at 30%"},{"key":"B","text":"Taxable as salary"},{"key":"C","text":"Partly exempt at 50%"},{"key":"D","text":"EXEMPT in the partner hands under Section 10(2A) (the firm pays tax on it)"}],"answer":"D","explanation":"The firm is taxed as a separate entity; the partner share of post-tax profit is exempt to avoid double taxation. Partner salary and interest from the firm are taxable as PGBP.","source":"Source label not detected","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":34,"stem":"Income-tax in India is levied by the:","options":[{"key":"A","text":"State Governments"},{"key":"B","text":"Reserve Bank of India"},{"key":"C","text":"Local municipalities"},{"key":"D","text":"UNION (Central) Government under Entry 82 of the Union List"}],"answer":"D","explanation":"Taxes on income other than agricultural income fall in the Union List; agricultural income tax is a State subject.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":35,"stem":"A \"domestic company\" for income-tax purposes means:","options":[{"key":"A","text":"Any company operating in India"},{"key":"B","text":"A multinational corporation"},{"key":"C","text":"A listed company only"},{"key":"D","text":"An INDIAN company, or any other company which has made prescribed arrangements for declaration and payment of dividends in India"}],"answer":"D","explanation":"Section 2(22A): Indian companies plus companies with prescribed dividend-payment arrangements in India are domestic companies.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":36,"stem":"Which of the following BEST describes \"gross total income\" minus \"total income\"?","options":[{"key":"A","text":"Exempt income under Section 10"},{"key":"B","text":"Deductions under Chapter VI-A (Sections 80C to 80U)"},{"key":"C","text":"TDS deducted at source"},{"key":"D","text":"Advance tax paid"}],"answer":"B","explanation":"GTI - Chapter VI-A deductions = total income on which slab rates are applied.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":37,"stem":"\"Marginal relief\" in income-tax ensures that:","options":[{"key":"A","text":"Surcharge is abolished"},{"key":"B","text":"The increase in tax payable when income crosses a threshold does NOT exceed the excess income over that threshold"},{"key":"C","text":"No one pays any tax"},{"key":"D","text":"Agricultural income is taxed"}],"answer":"B","explanation":"Marginal relief caps the tax (or tax-plus-surcharge) jump at the amount by which income exceeds the rebate/surcharge threshold - preventing a small income rise from causing a large tax rise.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":38,"stem":"Rounding off of total income under Section 288A is done to the nearest multiple of:","options":[{"key":"A","text":"One rupee"},{"key":"B","text":"Ten rupees"},{"key":"C","text":"Hundred rupees"},{"key":"D","text":"Thousand rupees"}],"answer":"B","explanation":"Total income is rounded to the nearest Rs.10; tax, interest and refunds are similarly rounded (s.288B).","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":39,"stem":"Which of the following statements is TRUE about the previous year for a NEW business?","options":[{"key":"A","text":"It begins on the date the business is set up and ends on the following 31 March - it can be shorter than 12 months"},{"key":"B","text":"It can exceed 12 months"},{"key":"C","text":"It is fixed by the Assessing Officer"},{"key":"D","text":"It must always be a full 12 months"}],"answer":"A","explanation":"For a newly set up business or a new source of income, the first previous year runs from the start date to the next 31 March.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":40,"stem":"Income of which person is TAXABLE even if it is received or accrued to another person (clubbing principle)?","options":[{"key":"A","text":"Salary of an independent spouse earned by her skill"},{"key":"B","text":"Income transferred without transferring the ASSET (s.60) - taxed in the transferor hands"},{"key":"C","text":"Income of a major married daughter"},{"key":"D","text":"A major son-in-law income from his own business"}],"answer":"B","explanation":"Section 60 revives tax in the transferor where income is diverted without transferring the asset itself; independent earnings of major family members are not clubbed.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":41,"stem":"The Income-tax Act, 1961 came into force with effect from:","options":[{"key":"A","text":"1 April 2001"},{"key":"B","text":"1 April 1956"},{"key":"C","text":"15 August 1947"},{"key":"D","text":"1 April 1962"}],"answer":"D","explanation":"The 1961 Act replaced the Indian Income-tax Act, 1922 with effect from 1 April 1962.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":42,"stem":"Which of the following is an example of an artificial juridical person included in \"person\"?","options":[{"key":"A","text":"A minor child"},{"key":"B","text":"A partnership firm"},{"key":"C","text":"A deity of a temple (e.g. an idol assessed through its shebait)"},{"key":"D","text":"A chartered accountant"}],"answer":"C","explanation":"Idols/deities, universities and statutory corporations are artificial juridical persons - a residual s.2(31)(vii) category.","source":"Original","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":43,"stem":"Where an assessee has agricultural income of Rs.6,000 and non-agricultural total income of Rs.4,00,000 (old regime), the final tax is:","options":[{"key":"A","text":"Tax on Rs.4,06,000 at slab rates"},{"key":"B","text":"Nil - because partial integration only fixes the RATE; on these facts tax works out to nil after rebate/limits"},{"key":"C","text":"Tax only on agricultural income"},{"key":"D","text":"30% flat on Rs.6,000"}],"answer":"B","explanation":"Partial integration (old regime): tax on (4,00,000 + 6,000) = 7,800 (5% of 1,56,000); tax on (6,000 + 2,50,000) = 300; difference = 7,500 - fully wiped out by the 87A rebate (total income Rs.4 lakh is within Rs.5 lakh), so the final tax is NIL.","source":"Source label not detected","module":"T0","topic":"Basics, Agricultural Income & Residential Status","reviewStatus":"Source key not independently verified"},{"id":44,"stem":"Income is taxable under the head \"Salaries\" (Section 15) only when there exists a:","options":[{"key":"A","text":"Dealer-customer relationship"},{"key":"B","text":"Buyer-seller relationship"},{"key":"C","text":"Creditor-debtor relationship"},{"key":"D","text":"MASTER-SERVANT (employer-employee) relationship between the payer and the payee"}],"answer":"D","explanation":"The master-servant relationship is the essence of salary; without it the receipt falls under other heads (e.g. PGBP or other sources).","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":45,"stem":"Under Section 15, salary is chargeable to tax on:","options":[{"key":"A","text":"Receipt basis only"},{"key":"B","text":"DUE or RECEIPT basis, WHICHEVER IS EARLIER"},{"key":"C","text":"Due basis only"},{"key":"D","text":"Cash basis after retirement"}],"answer":"B","explanation":"Salary is taxed when it becomes due or is received, whichever happens first - arrears are taxed in the year of receipt if not taxed earlier, with relief u/s 89.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":46,"stem":"Relief on arrears or advance salary is claimed under:","options":[{"key":"A","text":"Section 80C"},{"key":"B","text":"Section 89, by filing Form 10E"},{"key":"C","text":"Section 87A"},{"key":"D","text":"Section 10(5)"}],"answer":"B","explanation":"Section 89 spreads arrears/advance salary over the years to which they relate; Form 10E must be filed to claim the relief.","source":"Source label not detected","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":47,"stem":"\"Profits in lieu of salary\" under Section 17(3) includes:","options":[{"key":"A","text":"Agricultural income"},{"key":"B","text":"Compensation received on termination of employment, and payments from an employer-employee provident/other fund (to the extent of employer contributions and interest thereon)"},{"key":"C","text":"Only cash salary"},{"key":"D","text":"Bank interest"}],"answer":"B","explanation":"Section 17(3) sweeps in retrenchment/termination compensation and similar payments connected with employment.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":48,"stem":"\"Salary\" for tax purposes includes:","options":[{"key":"A","text":"Only basic pay"},{"key":"B","text":"Basic wages, dearness allowance, bonus, commission, fees, perquisites and profits in lieu of salary"},{"key":"C","text":"Only pension"},{"key":"D","text":"Only cash received"}],"answer":"B","explanation":"Section 17(1) gives an inclusive definition - wages, annuity/pension, gratuity, fees/commission/perquisites/profits in lieu, advance salary, leave encashment and employer fund contributions.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":49,"stem":"Pension received regularly by a retired employee is:","options":[{"key":"A","text":"A capital receipt - exempt"},{"key":"B","text":"Taxable as business income"},{"key":"C","text":"Fully exempt u/s 10"},{"key":"D","text":"Taxable under the head SALARIES as income from the former employer"}],"answer":"D","explanation":"Uncommuted (periodic) pension is salary income; only commuted pension gets partial/full exemption under s.10(10A).","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":50,"stem":"Commuted (lump-sum) pension received by a GOVERNMENT employee is:","options":[{"key":"A","text":"Taxable at 30%"},{"key":"B","text":"Fully taxable"},{"key":"C","text":"Taxable at half rate"},{"key":"D","text":"Fully EXEMPT under Section 10(10A)(i)"}],"answer":"D","explanation":"Government employees (Centre/State/local authority) enjoy full exemption on commuted pension.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":51,"stem":"For a NON-government employee who also receives GRATUITY, the exempt portion of commuted pension is:","options":[{"key":"A","text":"One-THIRD of the commuted value"},{"key":"B","text":"Nil"},{"key":"C","text":"Full amount"},{"key":"D","text":"One-half of the commuted value"}],"answer":"A","explanation":"Non-government employees: 1/3 of commuted value exempt if gratuity is also received; 1/2 if no gratuity is received (s.10(10A)(ii)).","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":52,"stem":"Gratuity received by a CENTRAL/STATE Government employee on retirement is:","options":[{"key":"A","text":"FULLY EXEMPT under Section 10(10)(i)"},{"key":"B","text":"Fully taxable"},{"key":"C","text":"Exempt up to Rs.10 lakh"},{"key":"D","text":"Exempt up to Rs.3 lakh"}],"answer":"A","explanation":"Government and local-authority employees get full gratuity exemption; the Rs.20 lakh ceiling applies to private-sector employees.","source":"Source label not detected","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":53,"stem":"For a private-sector employee COVERED by the Payment of Gratuity Act, exempt gratuity is the LEAST of: (i) actual gratuity received, (ii) Rs.20 lakh, (iii):","options":[{"key":"A","text":"15 days salary (last drawn) for every completed year of service (or part over 6 months)"},{"key":"B","text":"One month salary for every year of service"},{"key":"C","text":"Average salary of 10 months"},{"key":"D","text":"Basic salary x 5"}],"answer":"A","explanation":"The three limits: actual, Rs.20,00,000 (notified limit), and 15/26 x last drawn salary x completed years (part > 6 months rounded up).","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":54,"stem":"The current notified exemption limit for gratuity of private-sector employees under Section 10(10) is:","options":[{"key":"A","text":"Rs.25 lakh"},{"key":"B","text":"Rs.10 lakh"},{"key":"C","text":"Rs.3.5 lakh"},{"key":"D","text":"Rs.20 lakh"}],"answer":"D","explanation":"The limit was raised from Rs.10 lakh to Rs.20 lakh w.e.f. 29-3-2018 and remains Rs.20 lakh for AY 2026-27.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":55,"stem":"Leave encashment received by a GOVERNMENT employee at retirement is:","options":[{"key":"A","text":"Exempt up to Rs.3 lakh"},{"key":"B","text":"Fully EXEMPT under Section 10(10AA)(i)"},{"key":"C","text":"Taxable fully"},{"key":"D","text":"Taxable as other sources"}],"answer":"B","explanation":"Government employees pay no tax on leave encashment at retirement; during service it is taxable for everyone.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":56,"stem":"For NON-government employees, leave encashment at retirement is exempt up to the least of several limits, the monetary ceiling being:","options":[{"key":"A","text":"Rs.25 lakh"},{"key":"B","text":"Rs.10 lakh"},{"key":"C","text":"Rs.50 lakh"},{"key":"D","text":"Rs.3 lakh"}],"answer":"A","explanation":"The Rs.3,00,000 ceiling was raised to Rs.25,00,000 by notification in 2023 (effective FY 2023-24) and holds for AY 2026-27.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":57,"stem":"Voluntary retirement compensation under Section 10(10C) is exempt up to:","options":[{"key":"A","text":"Rs.10 lakh"},{"key":"B","text":"Rs.20 lakh"},{"key":"C","text":"Rs.1 lakh"},{"key":"D","text":"Rs.5 lakh"}],"answer":"D","explanation":"VRS compensation is exempt up to Rs.5 lakh, subject to the scheme conditions; relief u/s 89 can alternatively be claimed, not both.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":58,"stem":"Retrenchment compensation under Section 10(10B) is exempt up to the least of actual amount, Rs.5 lakh, and:","options":[{"key":"A","text":"15 days average pay for every completed year of service (and part over 6 months)"},{"key":"B","text":"10 days average pay per year of service"},{"key":"C","text":"Three months salary"},{"key":"D","text":"One year salary"}],"answer":"A","explanation":"Retrenchment compensation exemption mirrors the Industrial Disputes Act formula: 15 days average pay per completed year, capped at Rs.5 lakh.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":59,"stem":"House Rent Allowance (HRA) exemption under Section 10(13A) is the LEAST of: actual HRA received, rent paid minus 10% of salary, and:","options":[{"key":"A","text":"20% of salary"},{"key":"B","text":"50% of salary (metro) or 40% (other cities)"},{"key":"C","text":"100% of salary"},{"key":"D","text":"25% of salary"}],"answer":"B","explanation":"Rule 2A: the three-limb test; the 50%/40% limb depends on whether the rented house is in Mumbai/Kolkata/Delhi/Chennai or elsewhere.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":60,"stem":"A salaried person living in DELHI receives HRA Rs.1,20,000 p.a., pays rent Rs.1,00,000 p.a.; basic salary Rs.3,00,000 p.a. HRA exemption is:","options":[{"key":"A","text":"Rs.1,20,000"},{"key":"B","text":"Rs.70,000"},{"key":"C","text":"Rs.50,000"},{"key":"D","text":"Rs.90,000"}],"answer":"B","explanation":"Least of: (i) 1,20,000, (ii) rent - 10% of salary = 1,00,000 - 30,000 = 70,000, (iii) 50% of salary = 1,50,000. Exemption = Rs.70,000.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":61,"stem":"Dearness allowance is counted as part of \"salary\" for HRA and retirement-benefit purposes only when:","options":[{"key":"A","text":"It exceeds Rs.5,000 p.m."},{"key":"B","text":"It forms part of salary under the terms of employment (e.g. counts for retirement benefits)"},{"key":"C","text":"Never"},{"key":"D","text":"The employee requests it"}],"answer":"B","explanation":"Only DA entering into pay for retirement-benefit purposes counts as salary for HRA exemption and gratuity computations.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":62,"stem":"Transport allowance exemption for commuting between home and office is now available to:","options":[{"key":"A","text":"All salaried employees"},{"key":"B","text":"Pensioners only"},{"key":"C","text":"NO general exemption - it is taxable (exemption survives only for blind/deaf-dumb/orthopaedically handicapped employees at Rs.3,200 p.m.)"},{"key":"D","text":"Government employees only"}],"answer":"C","explanation":"The general Rs.1,600 p.m. transport allowance exemption was withdrawn from AY 2019-20 when standard deduction was introduced; the handicapped-employee exemption (Rs.3,200 p.m.) continues.","source":"Source label not detected","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":63,"stem":"Children education allowance is exempt up to:","options":[{"key":"A","text":"Rs.1,000 per month per child"},{"key":"B","text":"Rs.200 per month per child (max 2 children)"},{"key":"C","text":"Rs.300 per month per child"},{"key":"D","text":"Rs.100 per month per child, up to two children"}],"answer":"D","explanation":"Section 10(14) read with Rule 2BB: Rs.100 p.m. per child (max two children); hostel expenditure allowance Rs.300 p.m. per child (max two).","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":64,"stem":"Tribal area allowance exemption (for specified tribal/agency areas) is:","options":[{"key":"A","text":"Fully exempt"},{"key":"B","text":"Rs.1,000 per month"},{"key":"C","text":"Rs.200 per month"},{"key":"D","text":"Rs.3,200 per month"}],"answer":"C","explanation":"Rule 2BB: tribal area allowance is exempt up to Rs.200 per month for employees posted in specified tribal areas of listed States (MP, UP, Karnataka, Tripura, Assam, WB, Bihar, Odisha, Tamil Nadu).","source":"Source label not detected","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":65,"stem":"Entertainment allowance deduction under Section 16(ii) is available to:","options":[{"key":"A","text":"All private-sector employees"},{"key":"B","text":"Bank employees only"},{"key":"C","text":"All employees up to Rs.10,000"},{"key":"D","text":"GOVERNMENT employees only - least of actual allowance, Rs.5,000, or 1/5 of basic salary"}],"answer":"D","explanation":"Entertainment allowance is first included in salary for all; only government employees get the s.16(ii) deduction capped at Rs.5,000. Private employees get NIL deduction.","source":"Source label not detected","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":66,"stem":"A private-sector employee gets Rs.30,000 p.m. basic salary and Rs.1,500 p.m. entertainment allowance. Deduction u/s 16(ii) is:","options":[{"key":"A","text":"Rs.18,000"},{"key":"B","text":"Rs.5,000"},{"key":"C","text":"NIL"},{"key":"D","text":"Rs.72,000"}],"answer":"C","explanation":"Section 16(ii) applies only to Government employees; a private employee gets no deduction for entertainment allowance.","source":"Source label not detected","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":67,"stem":"Standard deduction under Section 16(ia) for AY 2026-27 is:","options":[{"key":"A","text":"Rs.40,000 for all"},{"key":"B","text":"Rs.1,00,000 for all"},{"key":"C","text":"Rs.75,000 under the NEW regime and Rs.50,000 under the OLD regime"},{"key":"D","text":"Rs.50,000 under the NEW regime and Rs.75,000 under the OLD regime"}],"answer":"C","explanation":"Standard deduction is Rs.75,000 in the new regime (from FY 2024-25) and Rs.50,000 in the old regime.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":68,"stem":"Deduction for professional tax paid under Section 16(iii) is:","options":[{"key":"A","text":"Allowed up to Rs.5,000 in new regime"},{"key":"B","text":"Available only in the OLD regime (not allowed under the new regime 115BAC)"},{"key":"C","text":"Available in both regimes"},{"key":"D","text":"Never allowed"}],"answer":"B","explanation":"Professional tax (max Rs.2,500 levied by States) is deductible u/s 16(iii) only in the old regime; the new regime permits only s.16(ia) standard deduction.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":69,"stem":"A \"specified employee\" for perquisite valuation under Section 17(2)(iii) includes all EXCEPT:","options":[{"key":"A","text":"A GAZETTED Government officer"},{"key":"B","text":"An employee whose salary income (net of certain deductions) exceeds Rs.50,000"},{"key":"C","text":"A director of the company"},{"key":"D","text":"An employee having substantial interest (20%+ voting power) in the employer company"}],"answer":"A","explanation":"The three specified-employee tests: director, substantial interest holder, or monetary limit of Rs.50,000. Government officers are employees; \"gazetted\" status is irrelevant.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":70,"stem":"Which of the following is a PERQUISITE taxable under Section 17(2)?","options":[{"key":"A","text":"Free or concessional residential accommodation, interest-free/concessional loans above Rs.20,000, and employer-provided car facility"},{"key":"B","text":"Agricultural land inherited"},{"key":"C","text":"Monthly railway pass bought by the employee himself"},{"key":"D","text":"A cash gift of Rs.500 from a friend"}],"answer":"A","explanation":"Rent-free accommodation, concessional loans above Rs.20,000, car facility, ESOP, free domestic servants etc. are perquisites taxed in the hands of the employee (specified employees for s.17(2)(iii) items).","source":"Source label not detected","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":71,"stem":"Medical facilities in employer-maintained hospitals and the annual health insurance premium paid by the employer (u/s 17(2) proviso/Rule 3A) are:","options":[{"key":"A","text":"Taxable at 30%"},{"key":"B","text":"EXEMPT - employer-paid medical insurance premium and treatment in employer/government/approved hospitals are not taxable perquisites"},{"key":"C","text":"Fully taxable perquisites"},{"key":"D","text":"Taxable above Rs.15,000 only"}],"answer":"B","explanation":"Employer-paid group medical premium and treatment in specified hospitals are exempt; the Rs.15,000 cap was removed long ago.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":72,"stem":"Employer contribution to an employee NPS account is deductible in the employee hands under Section 80CCD(2) up to:","options":[{"key":"A","text":"No deduction available"},{"key":"B","text":"10% of basic + DA (old regime); 14% of basic + DA (new regime)"},{"key":"C","text":"20% of gross salary in both regimes"},{"key":"D","text":"Rs.50,000 flat"}],"answer":"B","explanation":"From FY 2024-25, the new-regime cap on employer NPS contribution (private sector too) is 14% of basic+DA; the old regime keeps 10%. This is over and above the 80CCE limit.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Review note: old-regime employer NPS limit depends on employer/category; question needs a qualifier."},{"id":73,"stem":"Employer contribution to recognised provident fund is EXEMPT up to:","options":[{"key":"A","text":"Rs.1.5 lakh only"},{"key":"B","text":"No limit"},{"key":"C","text":"12% of salary; interest credited up to 9.5% p.a. is exempt"},{"key":"D","text":"15% of salary"}],"answer":"C","explanation":"RPF: employer contribution beyond 12% of salary is taxable, and interest above 9.5% p.a. is taxable; additionally, interest on employee contributions above Rs.2.5 lakh a year is taxable (2021 change).","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":74,"stem":"A lump-sum payment received from a RECOGNISED provident fund on retirement after 5 years of continuous service is:","options":[{"key":"A","text":"Taxable at 20%"},{"key":"B","text":"Fully taxable"},{"key":"C","text":"EXEMPT under Section 10(12)"},{"key":"D","text":"Half taxable"}],"answer":"C","explanation":"Accumulated RPF balance is exempt after 5 years of continuous service (with exceptions for permitted early withdrawals).","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":75,"stem":"Approved superannuation fund - employer contribution is taxable as perquisite if it exceeds:","options":[{"key":"A","text":"Rs.7.5 lakh per year"},{"key":"B","text":"Rs.1.5 lakh per year"},{"key":"C","text":"Rs.1 lakh per year"},{"key":"D","text":"Rs.2 lakh per year"}],"answer":"B","explanation":"Employer contribution to an approved superannuation fund above Rs.1,50,000 a year is a taxable perquisite.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":76,"stem":"Death-cum-retirement gratuity received by the LEGAL HEIR of a deceased government employee is:","options":[{"key":"A","text":"Fully exempt under s.10(10)"},{"key":"B","text":"Taxable as capital gains"},{"key":"C","text":"Taxable at slab rates"},{"key":"D","text":"Taxable as income from other sources"}],"answer":"A","explanation":"Gratuity received on death is exempt in the hands of the family/legal heirs, same as retirement gratuity of government employees.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":77,"stem":"Salary in lieu of notice period received on termination is:","options":[{"key":"A","text":"Agricultural income"},{"key":"B","text":"Tax-free up to Rs.1 lakh"},{"key":"C","text":"A capital receipt - exempt"},{"key":"D","text":"Taxable under the head SALARIES"}],"answer":"D","explanation":"Payments connected with the employment relationship, including notice-pay, are salary income.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":78,"stem":"Bonus or commission received by an employee from the employer is taxable under the head:","options":[{"key":"A","text":"Capital gains"},{"key":"B","text":"Profits and gains of business"},{"key":"C","text":"Income from other sources"},{"key":"D","text":"Salaries"}],"answer":"D","explanation":"All receipts flowing from the employer-employee relationship - bonus, commission, overtime pay - are salary income.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":79,"stem":"Advance salary received is taxed:","options":[{"key":"A","text":"In the year to which it relates"},{"key":"B","text":"In the year of RECEIPT (due or receipt, whichever earlier), with s.89 relief where applicable"},{"key":"C","text":"Never"},{"key":"D","text":"Only after retirement"}],"answer":"B","explanation":"Section 15 brings advance salary to tax on receipt; s.89(1) relief mitigates bunching.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":80,"stem":"An employee stock option plan (ESOP) is taxed as a perquisite:","options":[{"key":"A","text":"On the date of grant"},{"key":"B","text":"On the date of ALLOTMENT of shares - the difference between fair market value on exercise date and the amount paid by the employee"},{"key":"C","text":"On the date of vesting"},{"key":"D","text":"Never"}],"answer":"B","explanation":"Perquisite value = FMV on the exercise date minus the exercise price, taxed in the year of allotment; later sale attracts capital gains.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":81,"stem":"Free education of the employee children provided by the employer is:","options":[{"key":"A","text":"A taxable perquisite - except where the institution is maintained by the employer, in which case cost up to Rs.1,000 per month per child is exempt"},{"key":"B","text":"Always fully exempt"},{"key":"C","text":"Fully exempt for all employees"},{"key":"D","text":"Taxed at flat 30%"}],"answer":"A","explanation":"Rule 3: if the employer runs the school, value above Rs.1,000 p.m. per child is a perquisite; elsewhere the employer-borne cost is taxable.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":82,"stem":"The exemption for interest-free or concessional loans applies only when the loan to the employee exceeds:","options":[{"key":"A","text":"Rs.50,000"},{"key":"B","text":"Rs.1,00,000"},{"key":"C","text":"Rs.20,000"},{"key":"D","text":"Rs.5,000"}],"answer":"C","explanation":"Loans up to Rs.20,000 in aggregate (and loans for treatment of specified diseases) are not taxed as perquisites.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":83,"stem":"Salary received by a PARTNER from his partnership firm is assessed under the head:","options":[{"key":"A","text":"Income from other sources"},{"key":"B","text":"Profits and gains of business or profession"},{"key":"C","text":"Exempt income"},{"key":"D","text":"Salaries"}],"answer":"B","explanation":"A partner is not an employee of the firm; partner salary/interest is business income (the firm gets a s.40(b) deduction within limits).","source":"Source label not detected","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":84,"stem":"HRA exemption is NOT available to an employee who:","options":[{"key":"A","text":"Pays rent to his parents"},{"key":"B","text":"Lives in a rented house"},{"key":"C","text":"Lives in a metro city"},{"key":"D","text":"Lives in his own house / pays no rent"}],"answer":"D","explanation":"Exemption needs actual rent paid above 10% of salary; an owner-occupier gets no HRA exemption.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":85,"stem":"Which of the following allowances is FULLY taxable for all employees?","options":[{"key":"A","text":"Tribal area allowance within limits"},{"key":"B","text":"HRA"},{"key":"C","text":"Dearness allowance (non-retirement portion), city compensatory allowance, overtime allowance"},{"key":"D","text":"Children education allowance within limits"}],"answer":"C","explanation":"DA, CCA and overtime are fully taxable; only the specifically exempt allowances (HRA, education, tribal area etc.) get limited exemptions.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":86,"stem":"Leave encashment received DURING the period of service is:","options":[{"key":"A","text":"Fully TAXABLE for all employees (government and private)"},{"key":"B","text":"Taxable at 10%"},{"key":"C","text":"Fully exempt"},{"key":"D","text":"Exempt up to Rs.25 lakh"}],"answer":"A","explanation":"The s.10(10AA) exemption applies only to encashment at retirement (or on resignation/termination), not to in-service encashment.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":87,"stem":"Annuity (annual payment) received from a present employer under an employment contract is taxed as:","options":[{"key":"A","text":"Salary"},{"key":"B","text":"Capital gains"},{"key":"C","text":"Exempt income"},{"key":"D","text":"Casual income"}],"answer":"A","explanation":"Annuity from an employer is salary; annuity from other sources (e.g. an insurance policy) goes to income from other sources.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":88,"stem":"The taxability of \"profits in lieu of salary\" and termination compensation is dealt with in:","options":[{"key":"A","text":"Section 17(3)"},{"key":"B","text":"Section 10"},{"key":"C","text":"Section 24"},{"key":"D","text":"Section 80C"}],"answer":"A","explanation":"Section 17(3) specifically taxes compensation for termination or modification of employment terms as profits in lieu of salary.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":89,"stem":"For HRA exemption, \"salary\" means:","options":[{"key":"A","text":"Gross salary including all allowances"},{"key":"B","text":"Only basic pay always"},{"key":"C","text":"Take-home pay"},{"key":"D","text":"Basic + DA (if part of retirement-benefit terms) + commission as a fixed percentage of turnover"}],"answer":"D","explanation":"Rule 2A uses the narrow salary definition: basic plus qualifying DA plus fixed-percentage commission on turnover.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":90,"stem":"Compensation received by an employee under a voluntary retirement scheme (VRS) is exempt under s.10(10C) subject to all EXCEPT:","options":[{"key":"A","text":"The recipient must not be re-employed in the same/another company of the same management"},{"key":"B","text":"The scheme applies to all employees (except directors)"},{"key":"C","text":"The exemption is capped at Rs.5 lakh"},{"key":"D","text":"The employee can claim BOTH s.10(10C) exemption AND s.89 relief in the same year"}],"answer":"D","explanation":"Section 10(10C) and s.89 relief cannot be claimed together for the same compensation; the employee must choose one.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":91,"stem":"A lump sum received from an UNRECOGNISED provident fund on retirement is taxed as:","options":[{"key":"A","text":"Only interest is taxable"},{"key":"B","text":"Fully taxable at 30%"},{"key":"C","text":"Employee own contributions exempt; employer contributions plus interest thereon taxed as salary; interest on employee contributions taxed as other sources"},{"key":"D","text":"Fully exempt"}],"answer":"C","explanation":"URPF: the employee contributions are tax-free (no deduction was claimed); employer contributions and interest on employer share are salary, and interest on the employee share is other-sources income.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":92,"stem":"Which of the following is DEDUCTIBLE from gross salary under Section 16 (old regime)?","options":[{"key":"A","text":"Home loan principal"},{"key":"B","text":"Standard deduction, entertainment allowance (government employees) and professional tax"},{"key":"C","text":"Income tax paid"},{"key":"D","text":"Entertainment allowance to a private employee"}],"answer":"B","explanation":"Section 16 permits only three deductions: 16(ia) standard deduction, 16(ii) entertainment allowance (government), and 16(iii) professional/employment tax.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":93,"stem":"Rent-free accommodation provided by the employer is valued (non-government employees, per Rule 3 as revised) at:","options":[{"key":"A","text":"The municipal tax paid"},{"key":"B","text":"A flat 30% of salary"},{"key":"C","text":"15%/10%/7.5% of salary depending on city population (cities above 40 lakh, 15-40 lakh, below 15 lakh respectively)"},{"key":"D","text":"Nil always"}],"answer":"C","explanation":"The 2023 CBDT revision set 15% (population above 40 lakh), 10% (15-40 lakh) and 7.5% (below 15 lakh) of salary as the value of unfurnished rent-free accommodation for non-government employees.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":94,"stem":"Surrender of salary to the Central Government under s.2 of the Voluntary Surrender of Salaries (Exemption from Taxation) Act, 1961 is:","options":[{"key":"A","text":"EXEMPT - genuinely surrendered salary is not included in income"},{"key":"B","text":"Taxed at 20%"},{"key":"C","text":"Clubbed with spouse income"},{"key":"D","text":"Taxable nevertheless"}],"answer":"A","explanation":"A true voluntary surrender to the Government is exempt under that specific 1961 statute; a mere application of salary after accrual would still be taxed.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":95,"stem":"Arrears of pension received by the family of a deceased employee (family pension) are taxable under the head:","options":[{"key":"A","text":"Capital gains"},{"key":"B","text":"Income from OTHER SOURCES"},{"key":"C","text":"Exempt fully"},{"key":"D","text":"Salaries"}],"answer":"B","explanation":"Family pension is taxed under other sources, with a deduction of 1/3rd or Rs.15,000 (old regime) / Rs.25,000 (new regime), whichever is lower.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":96,"stem":"Which receipt is NOT part of salary income?","options":[{"key":"A","text":"Bonus"},{"key":"B","text":"Advance salary"},{"key":"C","text":"Scholarship received by the employee child from an independent trust on merit"},{"key":"D","text":"Gratuity in excess of exemption limits"}],"answer":"C","explanation":"A merit scholarship to the child from an independent body has no employer-employee nexus; it is exempt under s.10(16) in the child hands.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":97,"stem":"\"Perquisite\" under Section 17(2) is charged:","options":[{"key":"A","text":"For all employees in respect of s.17(2)(i)/(ii) items (rent-free accommodation, employer obligations paid), and for SPECIFIED employees in respect of s.17(2)(iii) fringe benefits"},{"key":"B","text":"Only for government employees"},{"key":"C","text":"Never"},{"key":"D","text":"Only for directors"}],"answer":"A","explanation":"Sections 17(2)(i) and (ii) apply to every employee; 17(2)(iii) benefits (car, servants, utilities etc.) are taxed only for specified employees.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":98,"stem":"Salary due from a foreign employer for services rendered in India, received outside India, is taxable in India in the hands of a resident because:","options":[{"key":"A","text":"Only NRIs pay tax on it"},{"key":"B","text":"It is received abroad"},{"key":"C","text":"It is exempt"},{"key":"D","text":"It is income ACCRUING in India - the place of accrual of salary is where the services are RENDERED"}],"answer":"D","explanation":"Salary accrues where services are performed; for a resident, world income is taxable in any case (s.5(1)).","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":99,"stem":"The maximum deduction for entertainment allowance of a government employee under s.16(ii) per annum is:","options":[{"key":"A","text":"Rs.18,000"},{"key":"B","text":"1/4 of gross salary"},{"key":"C","text":"Rs.10,000"},{"key":"D","text":"Rs.5,000"}],"answer":"D","explanation":"Least of actual allowance, Rs.5,000, or one-fifth of basic salary - the Rs.5,000 statutory cap usually binds.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":100,"stem":"Which of the following items is NOT taxed as salary?","options":[{"key":"A","text":"Remuneration received by a partner from his firm"},{"key":"B","text":"Overtime payments"},{"key":"C","text":"Monthly pension"},{"key":"D","text":"Fees and commission from the employer"}],"answer":"A","explanation":"Partner remuneration lacks the master-servant relationship and is taxed as business income, not salary.","source":"Source label not detected","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":101,"stem":"Under the NEW tax regime (115BAC), which salary-related deduction/exemption IS still available?","options":[{"key":"A","text":"HRA exemption"},{"key":"B","text":"Entertainment allowance deduction"},{"key":"C","text":"Standard deduction u/s 16(ia) and employer NPS contribution u/s 80CCD(2)"},{"key":"D","text":"Professional tax deduction"}],"answer":"C","explanation":"The new regime bars HRA, LTC, 16(ii)/(iii) and most Chapter VI-A deductions, but allows the standard deduction (Rs.75,000), employer NPS 80CCD(2), family pension deduction (Rs.25,000) and 80JJAA.","source":"Original","module":"T1","topic":"Income from Salaries","reviewStatus":"Source key not independently verified"},{"id":102,"stem":"Income is chargeable under \"Income from house property\" only when the assessee is the ________ of a building or land appurtenant thereto:","options":[{"key":"A","text":"OWNER"},{"key":"B","text":"Mortgagee"},{"key":"C","text":"Tenant"},{"key":"D","text":"Caretaker"}],"answer":"A","explanation":"Ownership of the building (with land appurtenant) is the basis of charge; a sub-letting tenant income goes to other sources, not house property.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified"},{"id":103,"stem":"The annual value of a LET-OUT house property is:","options":[{"key":"A","text":"Nil for rented property"},{"key":"B","text":"Actual rent always"},{"key":"C","text":"The higher of municipal value or fair rent, restricted to standard rent (if rent control applies), and compared with ACTUAL RENT received/receivable - whichever of these (expected rent vs actual rent) is HIGHER"},{"key":"D","text":"Municipal value only"}],"answer":"C","explanation":"Section 23(1): expected rent = higher of municipal value and fair rent (capped at standard rent); annual value = higher of expected rent and actual rent received/receivable.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified"},{"id":104,"stem":"Municipal taxes are deductible from gross annual value only when they are:","options":[{"key":"A","text":"Actually PAID by the OWNER during the previous year (any year payment allowed)"},{"key":"B","text":"Merely due"},{"key":"C","text":"Paid by the TENANT"},{"key":"D","text":"Paid in advance for 10 years only"}],"answer":"A","explanation":"Municipal taxes (including service taxes to local bodies) are deductible on payment basis if borne and paid by the owner; tenant-paid taxes are ignored.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified"},{"id":105,"stem":"From the net annual value, a STANDARD DEDUCTION is allowed under Section 24(a) at:","options":[{"key":"A","text":"30% of net annual value (no proof of expense needed)"},{"key":"B","text":"Rs.30,000 flat"},{"key":"C","text":"10% of NAV"},{"key":"D","text":"Actual repairs incurred"}],"answer":"A","explanation":"A flat 30% of NAV covers repairs and all other expenses - allowed even if actual expenditure is less, for let-out as well as deemed let-out property.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified"},{"id":106,"stem":"Interest on borrowed capital for acquisition/construction of a LET-OUT property is deductible under s.24(b):","options":[{"key":"A","text":"Up to Rs.2 lakh only"},{"key":"B","text":"Up to Rs.30,000"},{"key":"C","text":"In FULL, without any monetary limit (though the house-property loss set-off against other heads is capped at Rs.2 lakh)"},{"key":"D","text":"Not deductible"}],"answer":"C","explanation":"For let-out property the whole interest is deductible; the Rs.2 lakh cap applies to set-off of the resulting loss against other heads (s.71(3A)).","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified"},{"id":107,"stem":"For a SELF-OCCUPIED property, the deduction for interest on borrowed capital (loan taken on/after 1-4-1999 for acquisition/construction completed within 5 years) is capped at:","options":[{"key":"A","text":"Rs.30,000"},{"key":"B","text":"Nil in all regimes"},{"key":"C","text":"Rs.2,00,000 per year (old regime)"},{"key":"D","text":"Rs.5,00,000"}],"answer":"C","explanation":"Old regime: Rs.2 lakh for self-occupied (Rs.30,000 if the loan is pre-1-4-1999 or for repair/renovation). Under the NEW regime, self-occupied interest is NOT deductible at all.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified"},{"id":108,"stem":"From AY 2025-26, the number of houses an individual/HUF can treat as SELF-OCCUPIED (annual value nil) is:","options":[{"key":"A","text":"TWO"},{"key":"B","text":"Three"},{"key":"C","text":"One"},{"key":"D","text":"Unlimited"}],"answer":"A","explanation":"The Finance Act 2025 removed the s.23(2) conditionalities - up to two houses can have nil annual value; additional houses are deemed let out.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified"},{"id":109,"stem":"Pre-construction period interest is deductible:","options":[{"key":"A","text":"Fully in the year of completion"},{"key":"B","text":"Never"},{"key":"C","text":"Over 10 years"},{"key":"D","text":"In FIVE equal annual instalments beginning from the year of acquisition/completion, within the overall s.24(b) limits"}],"answer":"D","explanation":"Interest for the period before the year of completion is aggregated and allowed in five equal instalments from the completion year.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified"},{"id":110,"stem":"Under the NEW tax regime (s.115BAC), interest on borrowed capital for a LET-OUT house property is:","options":[{"key":"A","text":"Deductible up to Rs.2 lakh"},{"key":"B","text":"Allowed only for one house"},{"key":"C","text":"Fully disallowed"},{"key":"D","text":"Deductible, but the resulting house-property loss CANNOT be set off against other heads nor carried forward"}],"answer":"D","explanation":"The new regime permits let-out interest deduction, but any house-property loss cannot be set off against other heads and cannot be carried forward.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified"},{"id":111,"stem":"Under the NEW tax regime, interest on borrowed capital for a SELF-OCCUPIED house is:","options":[{"key":"A","text":"Fully deductible"},{"key":"B","text":"NOT deductible at all"},{"key":"C","text":"Deductible up to Rs.30,000"},{"key":"D","text":"Deductible up to Rs.2 lakh"}],"answer":"B","explanation":"Section 115BAC(2) bars the s.24(b) deduction for self-occupied property; let-out interest remains deductible.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified"},{"id":112,"stem":"A owns a house: municipal value Rs.1,80,000, fair rent Rs.2,00,000, standard rent Rs.1,92,000, actual rent Rs.17,000 p.m. Gross annual value is:","options":[{"key":"A","text":"Rs.1,92,000"},{"key":"B","text":"Rs.2,00,000"},{"key":"C","text":"Rs.2,04,000"},{"key":"D","text":"Rs.1,80,000"}],"answer":"C","explanation":"Expected rent = higher of MV (1,80,000) and FR (2,00,000), capped at SR = 1,92,000. Actual rent = 17,000 x 12 = 2,04,000. GAV = higher of the two = Rs.2,04,000.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified"},{"id":113,"stem":"Net annual value of the above house (municipal taxes paid by owner Rs.12,000) is:","options":[{"key":"A","text":"Rs.1,80,000"},{"key":"B","text":"Rs.1,92,000"},{"key":"C","text":"Rs.2,00,000"},{"key":"D","text":"Rs.2,04,000"}],"answer":"B","explanation":"NAV = GAV 2,04,000 - municipal taxes paid by owner 12,000 = Rs.1,92,000.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified"},{"id":114,"stem":"Income from the above house (interest on loan for the year Rs.1,50,000) is:","options":[{"key":"A","text":"Rs.1,92,000"},{"key":"B","text":"(-) Rs.15,600"},{"key":"C","text":"Rs.42,000"},{"key":"D","text":"Rs.57,600"}],"answer":"B","explanation":"NAV 1,92,000 - 30% standard deduction 57,600 - interest 1,50,000 = (-) Rs.15,600 (a loss).","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified"},{"id":115,"stem":"A house property remains UNOCCUPIED for the whole year because of the owner employment/business at another place - its annual value is taken as:","options":[{"key":"A","text":"Municipal value"},{"key":"B","text":"Fair rent"},{"key":"C","text":"Standard rent"},{"key":"D","text":"NIL - treated as self-occupied (one of the two permitted houses)"}],"answer":"D","explanation":"Section 23(2): a house that cannot be occupied owing to employment/business elsewhere is treated as self-occupied with nil annual value.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified"},{"id":116,"stem":"Deemed ownership for house property tax does NOT arise for:","options":[{"key":"A","text":"A holder of an impartible estate"},{"key":"B","text":"A member of a co-operative society to whom the building is allotted"},{"key":"C","text":"Transfer to a spouse (otherwise than for adequate consideration) or to a minor child (not being a married daughter)"},{"key":"D","text":"A LANDLORD who lets out his own building"}],"answer":"D","explanation":"Section 27 deems certain non-owners to be owners (transfers to spouse/minor child, impartible estate holder, co-op members, s.53A part-performance possessors). An ordinary owner-landlord is the actual, not deemed, owner.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified"},{"id":117,"stem":"Property used by the assessee for his OWN business or profession is:","options":[{"key":"A","text":"Taxed as capital gains"},{"key":"B","text":"Taxed under house property"},{"key":"C","text":"Taxed at 30% flat"},{"key":"D","text":"EXCLUDED from house-property tax - its value is not taxed under this head (the business gets no notional rent deduction either)"}],"answer":"D","explanation":"Section 22 excludes property occupied for the assessee own business/profession from the house-property head.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified"},{"id":118,"stem":"Unrealised rent is deducted from actual rent while computing GAV only if:","options":[{"key":"A","text":"Prescribed Rule 4 conditions are met - tenancy bona fide, defaulting tenant vacated/steps taken to compel vacation, not occupying any other property of the assessee, and legal recovery steps taken or proof that they are futile"},{"key":"B","text":"The tenant is poor"},{"key":"C","text":"The owner waives it informally"},{"key":"D","text":"Never deductible"}],"answer":"A","explanation":"Rule 4 lists strict conditions for excluding unrealised rent; later recovery is taxed in the year of receipt (s.25A) after a flat 30% deduction.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified"},{"id":119,"stem":"Arrears of rent and unrealised rent RECOVERED subsequently are taxed (s.25A/25AA):","options":[{"key":"A","text":"Never taxed"},{"key":"B","text":"As capital gains"},{"key":"C","text":"In the year of RECEIPT, as income from house property, after a flat 30% deduction - even if the assessee no longer owns the property"},{"key":"D","text":"In the year to which they relate"}],"answer":"C","explanation":"Subsequent recovery is taxed on receipt under house property (s.25A) or other sources for non-owners, with a 30% flat deduction.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified"},{"id":120,"stem":"Composite rent (rent for building PLUS services like lift, security, electricity) is split and taxed as:","options":[{"key":"A","text":"Entirely house property"},{"key":"B","text":"Entirely salary"},{"key":"C","text":"Entirely exempt"},{"key":"D","text":"House property for the building portion; the SERVICES portion under other sources or business income"}],"answer":"D","explanation":"Composite letting is severable: rent attributable to the building is house property; charges for amenities/services are taxed separately.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified"},{"id":121,"stem":"The annual value of one SELF-OCCUPIED house is taken as:","options":[{"key":"A","text":"Fair rent"},{"key":"B","text":"Standard rent"},{"key":"C","text":"Municipal value"},{"key":"D","text":"NIL"}],"answer":"D","explanation":"Section 23(2): the annual value of a self-occupied house (up to two houses) is nil; only the interest deduction (old regime) can produce a loss.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified"},{"id":122,"stem":"A house owned by a person is let out for part of the year and self-occupied for part - the annual value is computed:","options":[{"key":"A","text":"As two separate houses"},{"key":"B","text":"At double rent"},{"key":"C","text":"As fully self-occupied"},{"key":"D","text":"As if let out for the WHOLE year, but considering only the actual rent for the let period (benefit of self-occupation preserved)"}],"answer":"D","explanation":"Section 23(3): where a single house is let for part and self-occupied for part, the expected rent for the whole year is compared with actual rent for the let period.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified"},{"id":123,"stem":"Which of the following losses can be set off against SALARY income in the same year?","options":[{"key":"A","text":"House property loss up to Rs.2,00,000"},{"key":"B","text":"Business loss of a discontinued business"},{"key":"C","text":"Capital loss"},{"key":"D","text":"Speculation loss"}],"answer":"A","explanation":"Inter-head set-off of house-property loss against any other head is capped at Rs.2 lakh per year (s.71(3A)); the excess carries forward for 8 years.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified"},{"id":124,"stem":"Loss from house property can be carried forward for:","options":[{"key":"A","text":"Indefinitely"},{"key":"B","text":"4 years"},{"key":"C","text":"8 assessment years, to be set off only against house-property income"},{"key":"D","text":"Cannot be carried forward"}],"answer":"C","explanation":"Section 71B: unabsorbed house-property loss (mainly interest) carries forward for 8 AYs and sets off only against house-property income.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified"},{"id":125,"stem":"Rent received for a plot of LAND (no building) is taxed under:","options":[{"key":"A","text":"Income from OTHER SOURCES (house property tax needs a building)"},{"key":"B","text":"Income from house property"},{"key":"C","text":"Agricultural income always"},{"key":"D","text":"Capital gains"}],"answer":"A","explanation":"Section 22 requires a building or land APPURTENANT to a building; bare land rent falls under other sources.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified"},{"id":126,"stem":"Income of a farm house used as a dwelling by the receiver of agricultural income is:","options":[{"key":"A","text":"Taxed at 30%"},{"key":"B","text":"Treated as AGRICULTURAL income (s.2(1A)(c)), subject to conditions"},{"key":"C","text":"Clubbed with spouse"},{"key":"D","text":"Taxed as house property"}],"answer":"B","explanation":"A farm building used as a dwelling/store by a cultivator or rent-receiver, near the land, qualifies as agricultural income.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified"},{"id":127,"stem":"Municipal value of a property is determined by:","options":[{"key":"A","text":"The seller"},{"key":"B","text":"The bank"},{"key":"C","text":"The Income Tax Officer"},{"key":"D","text":"The MUNICIPAL/local authority for levying municipal taxes"}],"answer":"D","explanation":"Municipal valuation for local-body taxes is the starting figure for expected rent.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified"},{"id":128,"stem":"Interest on a FRESH loan taken to repay an earlier home loan is:","options":[{"key":"A","text":"Not deductible"},{"key":"B","text":"Treated as principal"},{"key":"C","text":"DEDUCTIBLE under s.24(b) as interest on borrowed capital"},{"key":"D","text":"Deductible only for self-occupied"}],"answer":"C","explanation":"Interest on a loan raised to repay the original acquisition/construction loan qualifies for deduction.","source":"Original","module":"T2","topic":"Income from House Property","reviewStatus":"Source key not independently verified"},{"id":129,"stem":"Income under \"Profits and gains of business or profession\" is charged under Section:","options":[{"key":"A","text":"28"},{"key":"B","text":"14"},{"key":"C","text":"45"},{"key":"D","text":"56"}],"answer":"A","explanation":"Section 28 is the charging section for business/profession income; ss.30-44D allow/deny deductions in computing it.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":130,"stem":"Which of the following is an essential feature of \"business\" income?","options":[{"key":"A","text":"It must involve manufacturing only"},{"key":"B","text":"A continuous, organised activity carried on with a PROFIT MOTIVE (though profit is not necessary in every year)"},{"key":"C","text":"It must be illegal"},{"key":"D","text":"It must be carried on from an office"}],"answer":"B","explanation":"Business implies a course of dealings with a profit motive; even a single adventure in the nature of trade can be business income.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":131,"stem":"Depreciation under Section 32 is allowed on:","options":[{"key":"A","text":"Replacement cost"},{"key":"B","text":"The straight line method for all assets"},{"key":"C","text":"The WRITTEN DOWN VALUE (WDV) method on a BLOCK OF ASSETS (SLM only for power-generating undertakings)"},{"key":"D","text":"Market value of each asset"}],"answer":"C","explanation":"Section 32 mandates WDV on blocks of assets; power generation/distribution undertakings may opt for SLM. Units-of-production and sum-of-digits methods are NOT prescribed.","source":"Source label not detected","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":132,"stem":"\"Block of assets\" means:","options":[{"key":"A","text":"A group of assets of the same class (tangible or intangible) in respect of which the SAME RATE of depreciation is prescribed"},{"key":"B","text":"A group of buildings in one city"},{"key":"C","text":"Only plant and machinery"},{"key":"D","text":"All assets of the company"}],"answer":"A","explanation":"Section 2(11): assets of the same class carrying the same rate form one block; depreciation is computed block-wise, not asset-wise.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":133,"stem":"The general rate of depreciation on PLANT AND MACHINERY (WDV) is:","options":[{"key":"A","text":"40%"},{"key":"B","text":"10%"},{"key":"C","text":"25%"},{"key":"D","text":"15%"}],"answer":"D","explanation":"The general P&M block carries 15%; computers and computer software carry 40%.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":134,"stem":"Depreciation rate on COMPUTERS including computer software (WDV) is:","options":[{"key":"A","text":"15%"},{"key":"B","text":"40%"},{"key":"C","text":"25%"},{"key":"D","text":"60%"}],"answer":"B","explanation":"Computers, peripherals and software are depreciated at 40% WDV.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":135,"stem":"Depreciation rate on FURNITURE and FITTINGS (WDV) is:","options":[{"key":"A","text":"15%"},{"key":"B","text":"10%"},{"key":"C","text":"20%"},{"key":"D","text":"5%"}],"answer":"B","explanation":"Furniture and fittings (including electrical fittings) are depreciated at 10% WDV.","source":"Source label not detected","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":136,"stem":"Depreciation on buildings (other than purely temporary erections) is allowed at:","options":[{"key":"A","text":"5% for residential buildings and 10% for other buildings (WDV)"},{"key":"B","text":"15% for all"},{"key":"C","text":"Nil"},{"key":"D","text":"20% for all"}],"answer":"A","explanation":"Residential buildings 5%, non-residential buildings 10%, purely temporary structures 40%.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":137,"stem":"INTANGIBLE assets like patents, trademarks, licences, know-how, franchises and goodwill (acquired) are depreciated at:","options":[{"key":"A","text":"25%"},{"key":"B","text":"10%"},{"key":"C","text":"40%"},{"key":"D","text":"Nil"}],"answer":"A","explanation":"Section 32(1)(ii) allows 25% WDV depreciation on specified intangible assets; self-generated goodwill gets none. (Post Finance Act 2021, goodwill of a business is NOT a depreciable asset and is removed from the block.)","source":"Source label not detected","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":138,"stem":"An asset purchased and put to use for LESS THAN 180 days in the year of acquisition gets depreciation of:","options":[{"key":"A","text":"Nil"},{"key":"B","text":"HALF of the normal rate"},{"key":"C","text":"Full year rate"},{"key":"D","text":"Double rate"}],"answer":"B","explanation":"The 180-day rule: assets used for less than 180 days in the year of acquisition earn only half the normal depreciation.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":139,"stem":"If all assets of a block are sold and the sale proceeds are LESS than the WDV of the block, the difference is:","options":[{"key":"A","text":"A short-term CAPITAL LOSS (terminal loss) - the block ceases to exist"},{"key":"B","text":"Treated as deemed profit u/s 41"},{"key":"C","text":"Treated as revenue loss"},{"key":"D","text":"Ignored"}],"answer":"A","explanation":"When the block ceases to exist with a deficit, the shortfall is a capital loss; if proceeds exceed WDV, the excess is short-term capital gain u/s 50.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":140,"stem":"Unabsorbed depreciation is carried forward:","options":[{"key":"A","text":"Never"},{"key":"B","text":"For 4 years"},{"key":"C","text":"For 8 years"},{"key":"D","text":"INDEFINITELY, and can be set off against any head (except salary) in later years"}],"answer":"D","explanation":"Section 32(2): unabsorbed depreciation carries forward without time limit; it is deemed part of current depreciation. In set-off priority, current depreciation comes before brought-forward business loss.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":141,"stem":"ADDITIONAL DEPRECIATION under Section 32(1)(iia) for new plant and machinery installed by a manufacturing concern is:","options":[{"key":"A","text":"10%"},{"key":"B","text":"Nil"},{"key":"C","text":"50%"},{"key":"D","text":"20% of actual cost (35% in notified backward areas of specified States)"}],"answer":"D","explanation":"Additional depreciation of 20% (35% for notified backward areas) applies to new P&M for manufacturing/production undertakings; half rate if used less than 180 days, balance next year.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":142,"stem":"Section 35 allows a 100% deduction (weighted deduction withdrawn) for:","options":[{"key":"A","text":"Capital expenditure on office decoration"},{"key":"B","text":"Personal medical expenses"},{"key":"C","text":"Revenue and capital expenditure on SCIENTIFIC RESEARCH related to the business (in-house research for approved companies)"},{"key":"D","text":"All donations"}],"answer":"C","explanation":"In-house scientific research expenditure (revenue and capital, except land) related to the business is deductible at 100%; approved-Institution weighted deductions have been withdrawn.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":143,"stem":"Deduction under Section 40(a)(ia) is DENIED to the extent of ________ where TDS is not deducted/deposited on payments to residents:","options":[{"key":"A","text":"100% of the expense"},{"key":"B","text":"30% of the expense (allowed in the year the TDS is deducted and paid)"},{"key":"C","text":"Nil"},{"key":"D","text":"50%"}],"answer":"B","explanation":"Resident payments: 30% of the expense is disallowed in the year of default and allowed in the year TDS compliance happens; non-resident TDS default disallows 100%.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":144,"stem":"Salary and interest paid by a firm to its PARTNERS are deductible under Section 40(b) subject to:","options":[{"key":"A","text":"Any amount the deed fixes"},{"key":"B","text":"10% interest and unlimited salary"},{"key":"C","text":"No limits"},{"key":"D","text":"Interest up to 12% p.a. simple, and salary limited to: first Rs.3,00,000 of book profit - Rs.1,50,000 or 90% whichever is more; on the balance - 60%"}],"answer":"D","explanation":"Section 40(b): interest on partner capital capped at 12% p.a. simple; working-partner remuneration within the book-profit slabs (first Rs.3L: Rs.1.5L or 90%, balance 60%).","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":145,"stem":"Book profit for Section 40(b) means:","options":[{"key":"A","text":"Net profit as per P&L increased by partner remuneration debited (if already deducted) and adjusted as per s.28-44D"},{"key":"B","text":"Tax paid profit"},{"key":"C","text":"Gross turnover"},{"key":"D","text":"Capital employed"}],"answer":"A","explanation":"Book profit is the s.28-44D computed profit before partner remuneration; the salary limits apply to that figure.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":146,"stem":"A firm has book profit of Rs.4,00,000 (before partner remuneration). The maximum deductible remuneration to working partners under s.40(b) is:","options":[{"key":"A","text":"Rs.3,60,000"},{"key":"B","text":"Rs.2,40,000"},{"key":"C","text":"Rs.2,70,000"},{"key":"D","text":"Rs.3,30,000"}],"answer":"D","explanation":"First Rs.3,00,000 of book profit: 90% = Rs.2,70,000 (more than the Rs.1,50,000 floor); balance Rs.1,00,000 at 60% = Rs.60,000. Total = 2,70,000 + 60,000 = Rs.3,30,000.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":147,"stem":"Which of the following is DEDUCTIBLE only on ACTUAL PAYMENT under Section 43B?","options":[{"key":"A","text":"Rent paid in cash"},{"key":"B","text":"Tax/duty/cess, PF/ESI contributions, bonus to employees, interest on bank loans - allowed only in the year of ACTUAL payment (or before the due date of filing the return)"},{"key":"C","text":"Salaries to staff"},{"key":"D","text":"Depreciation"}],"answer":"B","explanation":"Section 43B enforces payment-basis deduction for statutory dues and specified items, regardless of the mercantile system followed.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":148,"stem":"Section 43B(h) (Finance Act 2023) disallows amounts payable to MICRO and SMALL enterprises unless paid within the time limit in Section 15 of the MSMED Act, which is:","options":[{"key":"A","text":"180 days"},{"key":"B","text":"90 days"},{"key":"C","text":"One year"},{"key":"D","text":"15 or 45 days as agreed (no agreed date: 15 days)"}],"answer":"D","explanation":"MSMED s.15: payment within the agreed date, which cannot exceed 45 days; without a written agreement, within 15 days. Delay means the deduction moves to the year of actual payment (no return-due-date relief).","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":149,"stem":"Cash payments exceeding Rs.________ to a single person in a day are disallowed as expenditure under Section 40A(3):","options":[{"key":"A","text":"2,000"},{"key":"B","text":"10,000 (Rs.35,000 for payments to transport contractors for plying/hiring goods carriages)"},{"key":"C","text":"1,00,000"},{"key":"D","text":"20,000"}],"answer":"B","explanation":"Section 40A(3) disallows cash payments above Rs.10,000 (Rs.35,000 for goods-carriage contractors); payment must be by account-payee cheque/draft or electronic mode.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":150,"stem":"Expenditure of a PERSONAL nature is dealt with under Section:","options":[{"key":"A","text":"44 - partial"},{"key":"B","text":"37 - allowed fully"},{"key":"C","text":"37(1) - NOT allowable, since only expenses wholly and exclusively for business are deductible"},{"key":"D","text":"28 - taxable"}],"answer":"C","explanation":"Section 37(1) is the residuary deduction provision: any revenue expense laid out wholly and exclusively for business (not personal, not capital, not specifically covered) is allowed.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":151,"stem":"Which of the following is NOT deductible under Section 37(1)?","options":[{"key":"A","text":"Fines and penalties for BREACH OF LAW (Explanation 1 - expenses for an offence or prohibited by law, and Explanation 3 - penalties for violation of foreign law)"},{"key":"B","text":"Legal expenses for business litigation"},{"key":"C","text":"Staff welfare expense"},{"key":"D","text":"Advertisement expense"}],"answer":"A","explanation":"Fines/penalties for infraction of law and expenditure for a purpose that is an offence or prohibited by law are expressly non-deductible.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":152,"stem":"Corporate social responsibility (CSR) expenditure under s.135 of the Companies Act is:","options":[{"key":"A","text":"NOT deductible under Explanation 2 to Section 37(1)"},{"key":"B","text":"Deductible at 150%"},{"key":"C","text":"Fully exempt income"},{"key":"D","text":"Deductible u/s 37(1)"}],"answer":"A","explanation":"Explanation 2 to s.37(1) bars deduction for CSR spend; it is an application of income, not a business expense.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":153,"stem":"Section 44AD presumptive taxation applies to eligible RESIDENT assessees (individuals, HUF, firms other than LLP) with turnover up to:","options":[{"key":"A","text":"Rs.2 crore (Rs.3 crore where cash receipts do not exceed 5% of total receipts)"},{"key":"B","text":"Rs.5 crore"},{"key":"C","text":"Rs.50 lakh"},{"key":"D","text":"Rs.1 crore"}],"answer":"A","explanation":"The Finance Act 2023 raised the 44AD ceiling to Rs.3 crore where cash receipts are within 5%; otherwise Rs.2 crore.","source":"Source label not detected","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":154,"stem":"Under Section 44AD, the presumptive income of an eligible business is:","options":[{"key":"A","text":"5% of turnover"},{"key":"B","text":"8% of turnover - 6% for receipts by account-payee cheque/draft/electronic clearing received during the year"},{"key":"C","text":"50% of turnover"},{"key":"D","text":"10% of turnover"}],"answer":"B","explanation":"8% of turnover/gross receipts is deemed profit, reduced to 6% for digital/banking-channel receipts (digital receipts up to the return due date count).","source":"Source label not detected","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":155,"stem":"Professionals covered by Section 44ADA declare presumptive income of:","options":[{"key":"A","text":"50% of gross receipts, for gross receipts up to Rs.50 lakh (Rs.75 lakh where cash receipts are within 5%)"},{"key":"B","text":"Rs.50 lakh flat"},{"key":"C","text":"8% of receipts"},{"key":"D","text":"25% of receipts"}],"answer":"A","explanation":"Section 44ADA: 50% of gross receipts deemed profit for specified professionals (legal, medical, engineering, architectural, accountancy, technical consultancy, interior decoration etc.).","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":156,"stem":"Section 44AE (goods carriage business) deems income at:","options":[{"key":"A","text":"Rs.5,000 per vehicle"},{"key":"B","text":"Rs.7,500 per month per vehicle (heavy goods vehicle: Rs.1,000 per ton of gross vehicle weight per month), for up to 10 vehicles"},{"key":"C","text":"8% of freight"},{"key":"D","text":"1% of receipts"}],"answer":"B","explanation":"44AE: light vehicles Rs.7,500/vehicle/month; heavy vehicles Rs.1,000 per ton per month; limited to assessees owning not more than 10 goods carriages.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":157,"stem":"Tax audit under Section 44AB is compulsory for a BUSINESS when turnover exceeds:","options":[{"key":"A","text":"Rs.5 crore always"},{"key":"B","text":"Rs.20 lakh"},{"key":"C","text":"Rs.40 lakh"},{"key":"D","text":"Rs.1 crore (Rs.10 crore where cash receipts AND cash payments are each within 5% of total)"}],"answer":"D","explanation":"Business audit threshold Rs.1 crore, raised to Rs.10 crore for low-cash businesses (5% test on both receipts and payments); professions: Rs.50 lakh.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":158,"stem":"A person opting for presumptive taxation under 44AD is:","options":[{"key":"A","text":"Required to get accounts audited"},{"key":"B","text":"Relieved from maintaining books (s.44AA) and tax audit (s.44AB) if income is declared at 8%/6% and advance tax paid in ONE instalment by 15 March"},{"key":"C","text":"Always required to maintain books"},{"key":"D","text":"Exempt from advance tax entirely"}],"answer":"B","explanation":"Presumptive taxpayers skip books and audit; their advance tax is payable in a single 15-March instalment.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":159,"stem":"Speculation business loss can be set off only against:","options":[{"key":"A","text":"House property income"},{"key":"B","text":"Any business income"},{"key":"C","text":"Speculation business PROFIT (carried forward 4 years)"},{"key":"D","text":"Salary income"}],"answer":"C","explanation":"Section 73: speculation losses are ring-fenced - set off only against speculation profits, with a 4-year carry forward.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":160,"stem":"Income from letting out PLANT, MACHINERY or FURNITURE (not as a business) is taxed under:","options":[{"key":"A","text":"Capital gains"},{"key":"B","text":"House property"},{"key":"C","text":"Income from OTHER SOURCES (s.56(2)(iii)) with depreciation deduction"},{"key":"D","text":"Salaries"}],"answer":"C","explanation":"Casual letting of machinery/furniture goes to other sources with depreciation and repair deductions; systematic letting as a business activity goes to PGBP.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":161,"stem":"Deemed profit under Section 41(1) arises when:","options":[{"key":"A","text":"A new asset is purchased"},{"key":"B","text":"Property is sold"},{"key":"C","text":"Dividend is received"},{"key":"D","text":"An allowance/deduction earlier granted is RECOVERED in a later year (e.g. a trading liability is remitted)"}],"answer":"D","explanation":"Section 41(1) claws back earlier deductions when the corresponding liability/expense is recovered or remitted.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":162,"stem":"Bad debts written off are deductible under Section 36(1)(vii) when:","options":[{"key":"A","text":"Any debt is written off"},{"key":"B","text":"The debt was taken into income earlier (or lent in money-lending business) and is actually WRITTEN OFF as irrecoverable in the accounts"},{"key":"C","text":"Only if a court decree is obtained"},{"key":"D","text":"Only for banks"}],"answer":"B","explanation":"The debt must have been included in income (or be a money-lending advance) and must be written off in the books; a mere provision is not enough (except banks/NBFCs within limits).","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":163,"stem":"A general provision for doubtful debts created by a trader is:","options":[{"key":"A","text":"Deductible up to Rs.1 lakh"},{"key":"B","text":"NOT deductible - only debts actually written off qualify (provisions allowed only to scheduled banks/NBFCs within s.36(1)(viia) limits)"},{"key":"C","text":"Deductible at 50%"},{"key":"D","text":"Fully deductible"}],"answer":"B","explanation":"Section 36(1)(vii) requires actual write-off; general provisions are disallowed for ordinary assessees.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":164,"stem":"Which of the following is expressly ALLOWED under Section 36(1)?","options":[{"key":"A","text":"Personal drawings of proprietor"},{"key":"B","text":"Income tax paid"},{"key":"C","text":"Insurance premium on stocks/stores (36(1)(i)), bonus/commission to employees (36(1)(ii)), interest on borrowed capital (36(1)(iii)), employer contribution to RPF/approved funds (36(1)(iv)/(va))"},{"key":"D","text":"Wealth tax paid"}],"answer":"C","explanation":"Section 36(1) lists specific deductions: insurance of stocks/employees health, employee bonus/commission, borrowing interest, employer fund contributions, animal replacement, bad debts etc.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":165,"stem":"Interest on capital borrowed for business purposes is deductible under Section:","options":[{"key":"A","text":"43B only"},{"key":"B","text":"24(b)"},{"key":"C","text":"36(1)(iii) - on accrual basis, except interest for the period before the asset is first put to use (capitalised to the asset cost)"},{"key":"D","text":"80C"}],"answer":"C","explanation":"Section 36(1)(iii) allows borrowing interest for business; pre-commencement interest on asset loans is capitalised, not expensed.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":166,"stem":"Employer contributions to employee provident/ESI funds are deductible under s.36(1)(va) read with s.43B only if:","options":[{"key":"A","text":"Paid within the same assessment year"},{"key":"B","text":"Never deductible"},{"key":"C","text":"Credited to the employee account on or before the DUE DATE under the relevant welfare statute"},{"key":"D","text":"Paid at any time"}],"answer":"C","explanation":"Employee welfare fund contributions must reach the fund by the statutory due date; the s.43B return-filing-date relief does NOT apply to employee contributions (Supreme Court in Checkmate Services).","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":167,"stem":"Scientific research capital expenditure (other than on land) for the assessee own business is:","options":[{"key":"A","text":"Allowed at 50%"},{"key":"B","text":"Not deductible"},{"key":"C","text":"Depreciated over 10 years"},{"key":"D","text":"Fully deductible in the year incurred under s.35(1)(iv)/(2)"}],"answer":"D","explanation":"Capital expenditure on scientific research (except land) related to the business is allowed in full; revenue expenditure is allowed under s.35(1)(i).","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":168,"stem":"Which expense is DISALLOWED under Section 40(a)?","options":[{"key":"A","text":"Salary paid by account payee cheque"},{"key":"B","text":"Audit fees"},{"key":"C","text":"Telephone expenses"},{"key":"D","text":"Interest, royalty, fees for technical services payable outside India on which TDS was not deducted/deposited (100% disallowance, s.40(a)(i))"}],"answer":"D","explanation":"Non-deduction/deposit of TDS on non-resident payments disallows the entire expense; for resident payments, 30% is disallowed under s.40(a)(ia).","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":169,"stem":"Section 40A(2) empowers the Assessing Officer to disallow excessive/unreasonable payments made to:","options":[{"key":"A","text":"Banks"},{"key":"B","text":"RELATED PERSONS (specified relatives and concerns having substantial interest)"},{"key":"C","text":"Any vendor"},{"key":"D","text":"Government departments"}],"answer":"B","explanation":"Payments to specified related persons above fair market value are disallowed to the extent considered excessive or unreasonable.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":170,"stem":"The \"eligible business\" for Section 44AD does NOT include:","options":[{"key":"A","text":"Civil contractors (small)"},{"key":"B","text":"Persons carrying on agency business, persons earning commission/brokerage, and professions referred to in s.44AA(1)"},{"key":"C","text":"Small manufacturers"},{"key":"D","text":"Retail traders"}],"answer":"B","explanation":"Agency, commission/brokerage businesses and specified professions are excluded from 44AD; LLPs are also excluded from the eligible-assessee list.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":171,"stem":"Compensation received on termination of an agency contract is:","options":[{"key":"A","text":"Exempt up to Rs.5 lakh"},{"key":"B","text":"Agricultural income"},{"key":"C","text":"Always a capital receipt - exempt"},{"key":"D","text":"Taxable as business income (s.28(ii)) where it relates to the business structure"}],"answer":"D","explanation":"Section 28(ii) taxes compensation for terminating/modifying any managing agency or other business agreement as business income.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":172,"stem":"Export incentives like duty drawback and cash compensatory support are:","options":[{"key":"A","text":"Exempt under s.10"},{"key":"B","text":"Business income taxable under s.28 (duty drawback u/s 28(iiia), profit on sale of DEPB u/s 28(iiid))"},{"key":"C","text":"Capital receipts"},{"key":"D","text":"Other sources income"}],"answer":"B","explanation":"Export incentives are expressly taxed as business profits - duty drawback, DEPB sale profits and cash assistance are listed in s.28.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":173,"stem":"Fees, technical services and consultancy income of an individual practising a profession fall under:","options":[{"key":"A","text":"Profits and gains of business or profession"},{"key":"B","text":"Exempt income"},{"key":"C","text":"Salaries"},{"key":"D","text":"Income from other sources"}],"answer":"A","explanation":"Professional earnings are PGBP; \"profession\" includes vocation and notified professions under s.44AA(1).","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":174,"stem":"Maintenance of books of account under Section 44AA is compulsory for a specified profession when gross receipts exceed:","options":[{"key":"A","text":"Rs.1,50,000 in ANY of the three preceding years (and expected to exceed in a new profession)"},{"key":"B","text":"Rs.25 lakh"},{"key":"C","text":"Rs.1 lakh in any of the 3 preceding years"},{"key":"D","text":"Rs.10 lakh"}],"answer":"A","explanation":"Specified professions (medicine, law, engineering, architecture, accountancy, technical consultancy, interior decoration, film artists, authorised representatives) must keep books if receipts top Rs.1.5 lakh in any of the 3 preceding years.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":175,"stem":"Animal (used for business but not as stock) that dies or becomes permanently useless is dealt with under Section 36(1)(vi) as:","options":[{"key":"A","text":"Depreciation"},{"key":"B","text":"No treatment"},{"key":"C","text":"Deduction of the difference between the actual cost and the amount realised on sale/carcass"},{"key":"D","text":"Capital loss"}],"answer":"C","explanation":"Section 36(1)(vi) allows the shortfall (cost minus realisation) of permanently useless/dead working animals as a deduction.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":176,"stem":"Which of the following receipts is TAXABLE as business income of a trade/professional association?","options":[{"key":"A","text":"Specific services rendered to MEMBERS for a charge (s.28(iii))"},{"key":"B","text":"Pure mutual concern receipts"},{"key":"C","text":"Donations received"},{"key":"D","text":"Subscription from members (exempt by mutuality)"}],"answer":"A","explanation":"Section 28(iii) taxes income of trade/professional associations from specific services to members; pure mutuality receipts are not income.","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":177,"stem":"Where an assessee follows mercantile accounting, income is taxed on:","options":[{"key":"A","text":"Due date of return"},{"key":"B","text":"ACCRUAL basis - when the right to receive arises, regardless of actual receipt"},{"key":"C","text":"Cash basis"},{"key":"D","text":"Whichever is lower"}],"answer":"B","explanation":"Mercantile/accrual books tax income when it accrues; cash basis taxes on receipt - the assessee must follow one regularly (s.145).","source":"Original","module":"T3","topic":"Business/Profession, Depreciation & Presumptive Taxation","reviewStatus":"Source key not independently verified"},{"id":178,"stem":"Capital gains are charged under Section ________ of the Income-tax Act:","options":[{"key":"A","text":"45"},{"key":"B","text":"28"},{"key":"C","text":"56"},{"key":"D","text":"14"}],"answer":"A","explanation":"Section 45 is the charging section: profits or gains arising from the TRANSFER of a capital asset are taxable as capital gains in the year of transfer.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":179,"stem":"A \"capital asset\" under Section 2(14) does NOT include:","options":[{"key":"A","text":"Land and building"},{"key":"B","text":"Stock-in-trade, raw materials and consumables held for business; personal effects (movable wearing apparel, furniture); agricultural land in RURAL India; and specified Gold Bonds"},{"key":"C","text":"Shares and securities"},{"key":"D","text":"Jewellery"}],"answer":"B","explanation":"Stock-in-trade, personal effects (excluding jewellery, art, archaeological collections, drawings, paintings, sculptures), rural agricultural land and 6.5%/7% Gold Bonds are excluded from \"capital asset\".","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":180,"stem":"Jewellery, archaeological collections, drawings, paintings, sculptures and any work of art are treated as:","options":[{"key":"A","text":"Exempt assets"},{"key":"B","text":"CAPITAL ASSETS (specifically carved out of the personal-effects exclusion)"},{"key":"C","text":"Personal effects - not capital assets"},{"key":"D","text":"Stock-in-trade always"}],"answer":"B","explanation":"The personal-effects exclusion does NOT cover jewellery and art/collection items - their sale attracts capital gains tax.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":181,"stem":"For assets acquired on/after 23-7-2024, the holding period to qualify as LONG-TERM is:","options":[{"key":"A","text":"36 months for all assets"},{"key":"B","text":"12 months for all assets"},{"key":"C","text":"12 months for listed securities/units and 24 months for all OTHER assets (only two categories survive)"},{"key":"D","text":"48 months for property"}],"answer":"C","explanation":"The Finance Act 2024 collapsed the three-tier holding structure into two: 12 months (listed securities, equity/preference shares, units of equity-oriented funds/business trusts) and 24 months (all other assets).","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":182,"stem":"Listed equity shares sold after 15 months of holding give rise to:","options":[{"key":"A","text":"Short-term capital gain"},{"key":"B","text":"Exempt income"},{"key":"C","text":"Business income"},{"key":"D","text":"LONG-TERM capital gain (holding exceeds 12 months)"}],"answer":"D","explanation":"Listed securities held for more than 12 months are long-term; 12 months or less is short-term (s.2(42A)).","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":183,"stem":"An immovable property (land/building) held for 20 months and then sold yields:","options":[{"key":"A","text":"Long-term capital gain"},{"key":"B","text":"SHORT-TERM capital gain (the threshold is 24 months)"},{"key":"C","text":"No gain"},{"key":"D","text":"Deemed income"}],"answer":"B","explanation":"Immovable property (and other non-listed assets) needs more than 24 months of holding to be long-term.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":184,"stem":"Long-term capital gains on listed equity shares and equity-oriented mutual fund units (s.112A) are taxed at:","options":[{"key":"A","text":"Nil - fully exempt"},{"key":"B","text":"10% above Rs.1 lakh"},{"key":"C","text":"20% with indexation"},{"key":"D","text":"12.5% above Rs.1.25 lakh per year (from 23-7-2024), without indexation"}],"answer":"D","explanation":"Section 112A: LTCG above Rs.1,25,000 a year on listed equity/equity-oriented funds (STT paid) is taxed at 12.5%; the exemption threshold was raised from Rs.1 lakh to Rs.1.25 lakh by the Finance Act 2024.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":185,"stem":"Short-term capital gains on listed equity shares/equity-oriented funds (STT paid) under Section 111A are taxed at:","options":[{"key":"A","text":"30%"},{"key":"B","text":"10%"},{"key":"C","text":"20% (from 23-7-2024)"},{"key":"D","text":"15%"}],"answer":"C","explanation":"Section 111A rate rose from 15% to 20% for transfers on or after 23-7-2024.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":186,"stem":"The general LTCG rate (Section 112) for other assets (property, unlisted shares, gold) for transfers on/after 23-7-2024 is:","options":[{"key":"A","text":"20% WITH indexation"},{"key":"B","text":"10%"},{"key":"C","text":"30%"},{"key":"D","text":"12.5% WITHOUT indexation (resident individuals/HUF selling pre-23-7-2024-acquired land or building may opt for 20% with indexation)"}],"answer":"D","explanation":"The Finance Act 2024 replaced 20%-with-indexation by 12.5%-without-indexation; a grandfathering choice (20% with indexation) exists for resident individuals/HUF on land/building acquired before 23-7-2024.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":187,"stem":"The Cost Inflation Index (CII) base year under the fourth proviso to Section 48 is:","options":[{"key":"A","text":"1981-82 = 100"},{"key":"B","text":"2011-12 = 100"},{"key":"C","text":"2001-02 = 100"},{"key":"D","text":"1991-92 = 100"}],"answer":"C","explanation":"The base year shifted from 1981-82 to 2001-02 = 100; assets acquired before 1-4-2001 use FMV as on 1-4-2001 as cost option.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":188,"stem":"The \"full value of consideration\" in capital gains computation means:","options":[{"key":"A","text":"Indexed cost"},{"key":"B","text":"What the transferor RECEIVES or is entitled to receive in respect of the transfer (not necessarily the market value)"},{"key":"C","text":"Stamp duty value always"},{"key":"D","text":"The cost of the asset"}],"answer":"B","explanation":"Section 48 uses actual consideration received/receivable; ss.50C/50CA substitute stamp-duty/valuation figures for land-building/unlisted shares where consideration is understated.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":189,"stem":"If the stamp duty value of a land/building exceeds the stated sale consideration, capital gains are computed using the stamp duty value, provided it exceeds the consideration by more than:","options":[{"key":"A","text":"5% of consideration"},{"key":"B","text":"Any excess"},{"key":"C","text":"10% of consideration (and Rs.50,000... the tolerance band is 10% of the consideration under s.50C as amended in 2020)"},{"key":"D","text":"1%"}],"answer":"C","explanation":"Section 50C/56(2)(x) safe harbour: stamp duty value is adopted only where it exceeds 110% of the actual consideration.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":190,"stem":"Cost of acquisition for an asset acquired by INHERITANCE or gift is:","options":[{"key":"A","text":"The cost to the PREVIOUS OWNER (and indexation, where applicable, runs from the previous owner acquisition)"},{"key":"B","text":"Its FMV on the date of inheritance in all cases"},{"key":"C","text":"Its insured value"},{"key":"D","text":"Nil"}],"answer":"A","explanation":"Section 49(1): for inheritance/gift/devolution, the deemed cost is the cost to the previous owner; the holding period also includes the previous owner period.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":191,"stem":"Improvement cost incurred by the assessee or the previous owner is:","options":[{"key":"A","text":"Never deductible"},{"key":"B","text":"Added to cost of acquisition and indexed from the year of improvement (for pre-23-7-2024 computations where indexation applies)"},{"key":"C","text":"Treated as revenue expense"},{"key":"D","text":"Deducted from sale price"}],"answer":"B","explanation":"Section 48/55: cost of improvement enhances the cost base; indexed cost of improvement uses the CII of the improvement year (where indexation survives).","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":192,"stem":"Expenses wholly and exclusively in connection with the transfer (brokerage, legal fees, stamp duty by seller) are:","options":[{"key":"A","text":"Not allowed"},{"key":"B","text":"Capitalised"},{"key":"C","text":"DEDUCTED from full value of consideration under s.48(i)"},{"key":"D","text":"Added to cost"}],"answer":"C","explanation":"Transfer expenses reduce the sale consideration for capital gains computation (but STT is not deductible for share transactions).","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":193,"stem":"Section 54 exempts LTCG on sale of a RESIDENTIAL HOUSE if the gain is invested in:","options":[{"key":"A","text":"Shares"},{"key":"B","text":"Any commercial property"},{"key":"C","text":"ONE (or two, where gain is up to Rs.2 crore, once in a lifetime) residential house in India - purchased 1 year before/2 years after, or constructed within 3 years; exemption capped at Rs.10 CRORE (from FY 2023-24)"},{"key":"D","text":"Gold"}],"answer":"C","explanation":"Section 54: reinvest the capital gain (not the whole consideration) in residential house(s) within the timelines; the Rs.10 crore cap applies from FY 2023-24.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":194,"stem":"Section 54EC exempts LTCG on land/building invested in specified bonds (NHAI, REC, PFC, IRFC) within 6 months, up to:","options":[{"key":"A","text":"Rs.50 LAKH per financial year, with a 5-year lock-in"},{"key":"B","text":"Rs.10 lakh"},{"key":"C","text":"Rs.5 lakh"},{"key":"D","text":"Rs.1 crore"}],"answer":"A","explanation":"54EC bonds have a Rs.50 lakh annual investment cap, 6-month window and 5-year lock-in; premature redemption makes the exempted gain taxable.","source":"Source label not detected","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":195,"stem":"Section 54F exempts LTCG (from assets OTHER than a residential house) if:","options":[{"key":"A","text":"The CAPITAL GAIN is reinvested in bonds"},{"key":"B","text":"The gain is below Rs.1 lakh"},{"key":"C","text":"The assessee buys agricultural land"},{"key":"D","text":"The ENTIRE NET SALE CONSIDERATION is invested in one residential house in India within the 54F timelines (and the assessee does not own more than one other house); capped at Rs.10 crore"}],"answer":"D","explanation":"54F requires investing the net consideration (proportional exemption if partial), subject to the one-house condition and the Rs.10 crore cap from FY 2023-24.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":196,"stem":"Section 54B exempts capital gains on transfer of URBAN AGRICULTURAL LAND used for agriculture for 2 years preceding transfer, if:","options":[{"key":"A","text":"Another AGRICULTURAL LAND (urban or rural) is purchased within 2 years"},{"key":"B","text":"The proceeds are deposited in a bank"},{"key":"C","text":"The gain is below Rs.50 lakh"},{"key":"D","text":"A house is constructed"}],"answer":"A","explanation":"54B reinvestment into agricultural land within 2 years exempts the gain; the new land must not be sold within 3 years.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":197,"stem":"The Capital Gains Accounts Scheme (CGAS) is used when:","options":[{"key":"A","text":"The asset is inherited"},{"key":"B","text":"The reinvestment (u/s 54/54B/54F etc.) cannot be made before the DUE DATE OF FILING THE RETURN - the amount is deposited in a CGAS account to keep the exemption alive"},{"key":"C","text":"The assessee wants a refund"},{"key":"D","text":"Always"}],"answer":"B","explanation":"Unutilised gains meant for reinvestment must be parked in a CGAS deposit by the s.139(1) due date; unutilised deposits become taxable in the year the period expires.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":198,"stem":"Short-term capital losses can be set off against:","options":[{"key":"A","text":"Both STCG and LTCG (any capital gains head income)"},{"key":"B","text":"Only LTCG"},{"key":"C","text":"Only STCG"},{"key":"D","text":"Salary income"}],"answer":"A","explanation":"Capital losses (short or long) set off only against capital gains, but STCL can absorb both STCG and LTCG; carry forward is 8 years.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":199,"stem":"A long-term capital loss can be set off against:","options":[{"key":"A","text":"Short-term gains also"},{"key":"B","text":"LONG-TERM capital gains ONLY"},{"key":"C","text":"Other sources"},{"key":"D","text":"Any income"}],"answer":"B","explanation":"LTCL sets off only against LTCG (s.70/74); both types carry forward for 8 assessment years.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":200,"stem":"Capital loss can be carried forward for how many assessment years?","options":[{"key":"A","text":"4"},{"key":"B","text":"10"},{"key":"C","text":"8"},{"key":"D","text":"Indefinitely"}],"answer":"C","explanation":"Section 74: capital losses carry forward for 8 AYs following the year of loss, set off only against capital gains.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":201,"stem":"Transfer of a capital asset in a scheme of AMALGAMATION (Indian companies) is:","options":[{"key":"A","text":"NOT treated as a \"transfer\" for capital gains (s.47(vi)) - tax defers to the ultimate sale"},{"key":"B","text":"Taxed at 30%"},{"key":"C","text":"Taxed as other sources"},{"key":"D","text":"Fully taxable"}],"answer":"A","explanation":"Section 47 lists non-transfers: amalgamation/demerge between qualifying companies, gifts/inheritance (covered by s.47(iii) read with 49(1)), holding-subsidiary transfers, etc.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":202,"stem":"Distribution of capital assets on DISSOLUTION of a firm is:","options":[{"key":"A","text":"Never taxable"},{"key":"B","text":"Treated as a TRANSFER - capital gains arise in the hands of the FIRM (s.45(4))"},{"key":"C","text":"Exempt"},{"key":"D","text":"Taxed in partner hands directly as salary"}],"answer":"B","explanation":"Section 45(4) deems distribution of capital assets on dissolution/reconstitution to be a transfer by the firm; FMV is deemed full value of consideration.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":203,"stem":"The holding period of a SHARE received on DEMERGER includes:","options":[{"key":"A","text":"The period for which the shares were held in the DEMERGED company"},{"key":"B","text":"Only the post-demerger period"},{"key":"C","text":"Three years"},{"key":"D","text":"One year"}],"answer":"A","explanation":"Explanation 1 to s.2(42A): for shares received on demerger, the holding period includes the period of holding in the demerged company.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":204,"stem":"Capital gains on DEPRECIABLE assets (forming part of a block) are:","options":[{"key":"A","text":"Always treated as SHORT-TERM (s.50) - long/short distinction does not apply to block assets"},{"key":"B","text":"Exempt"},{"key":"C","text":"Taxed at 12.5%"},{"key":"D","text":"Long-term if held 24 months"}],"answer":"A","explanation":"Section 50: gains on block assets are always short-term, because WDV already reflects depreciation claims.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":205,"stem":"Securities Transaction Tax (STT) paid on sale of shares is:","options":[{"key":"A","text":"Refundable"},{"key":"B","text":"Added to cost"},{"key":"C","text":"NOT deductible while computing capital gains on shares"},{"key":"D","text":"Deductible as transfer expense in capital gains"}],"answer":"C","explanation":"STT is neither a transfer expense nor part of cost for capital-gain purposes (though STT payment is a condition for the 111A/112A concessional rates).","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":206,"stem":"Conversion of a capital asset into STOCK-IN-TRADE is:","options":[{"key":"A","text":"Taxed as salary"},{"key":"B","text":"Exempt"},{"key":"C","text":"Not taxable at all"},{"key":"D","text":"Taxed as a transfer in the year of conversion, with FMV on the date of conversion as full value of consideration (s.45(2))"}],"answer":"D","explanation":"Section 45(2): conversion into stock is a taxable transfer on conversion-date FMV; the later business sale taxes the FMV-to-sale difference as business income.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":207,"stem":"For BONUS shares allotted on/after 1-4-2001, the cost of acquisition is taken as:","options":[{"key":"A","text":"Face value"},{"key":"B","text":"FMV on allotment date"},{"key":"C","text":"Cost of original shares"},{"key":"D","text":"NIL"}],"answer":"D","explanation":"Section 55(2)(aa): bonus shares allotted on or after 1-4-2001 have nil cost; their holding period runs from allotment.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":208,"stem":"Compulsory acquisition of an asset by the Government - capital gains arise in:","options":[{"key":"A","text":"The year of RECEIPT of the compensation (or part of it)"},{"key":"B","text":"Never taxable"},{"key":"C","text":"The year of possession"},{"key":"D","text":"The year of the acquisition order"}],"answer":"A","explanation":"Section 45(5): compulsory-acquisition gains are taxed in the year the compensation (or part) is first received; enhanced compensation is taxed when received.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":209,"stem":"A depreciable block ceases to exist because all assets are destroyed by fire and insurance compensation EXCEEDS the block WDV. The excess is:","options":[{"key":"A","text":"Revenue income"},{"key":"B","text":"Exempt"},{"key":"C","text":"Casual income"},{"key":"D","text":"Short-term capital GAIN under Section 50"}],"answer":"D","explanation":"Where the block ceases to exist and money received exceeds WDV, the excess is short-term capital gain u/s 50 (the s.45(1A) insurance-compensation rule applies via the block mechanism).","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":210,"stem":"Exemption under Section 54/54F is withdrawn (the exempted gain becomes taxable) if the NEW residential house is sold within:","options":[{"key":"A","text":"5 years"},{"key":"B","text":"2 years"},{"key":"C","text":"3 YEARS of purchase/construction"},{"key":"D","text":"1 year"}],"answer":"C","explanation":"The new asset has a 3-year lock-in: selling it earlier makes the previously exempted gain taxable in the year of sale.","source":"Original","module":"T4","topic":"Capital Gains","reviewStatus":"Source key not independently verified"},{"id":211,"stem":"The residuary head \"Income from other sources\" is charged under Section:","options":[{"key":"A","text":"45"},{"key":"B","text":"56"},{"key":"C","text":"28"},{"key":"D","text":"24"}],"answer":"B","explanation":"Section 56 taxes every income that does not fall under the first four heads and is not exempt.","source":"Original","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified"},{"id":212,"stem":"DIVIDEND received from an Indian company is:","options":[{"key":"A","text":"Fully exempt (s.10(34))"},{"key":"B","text":"TAXABLE in the shareholder hands under other sources (DDT abolished from FY 2020-21), with TDS u/s 194 above Rs.10,000"},{"key":"C","text":"Exempt up to Rs.10 lakh"},{"key":"D","text":"Taxed as capital gains"}],"answer":"B","explanation":"Since AY 2021-22 dividends are taxable in the investor hands; the company deducts 10% TDS above the Rs.10,000 threshold (raised from Rs.5,000 w.e.f. 1-4-2025).","source":"Original","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified"},{"id":213,"stem":"Which of the following is NOT taxed under income from other sources?","options":[{"key":"A","text":"Family pension"},{"key":"B","text":"Winnings from lotteries and crossword puzzles"},{"key":"C","text":"RENT FROM A LET-OUT BUILDING"},{"key":"D","text":"Interest on securities/bank deposits"}],"answer":"C","explanation":"Building rent is house-property income (s.22); the other three are classic other-sources items.","source":"Original","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified"},{"id":214,"stem":"Winnings from lotteries, crossword puzzles, races, card games and online games are taxed at a flat rate of:","options":[{"key":"A","text":"30% (plus cess) under Section 115BB, with NO deduction or exemption allowed"},{"key":"B","text":"10%"},{"key":"C","text":"20%"},{"key":"D","text":"Slab rates"}],"answer":"A","explanation":"Casual income is taxed at a flat 30% u/s 115BB; no expenditure or allowance is deductible and losses cannot be set off.","source":"Original","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified"},{"id":215,"stem":"Family pension received by the widow/legal heir is taxed with a deduction of:","options":[{"key":"A","text":"Nil"},{"key":"B","text":"50% of pension"},{"key":"C","text":"1/3rd of the pension OR Rs.15,000 (old regime) / Rs.25,000 (new regime), whichever is LESS"},{"key":"D","text":"30% of NAV"}],"answer":"C","explanation":"Section 57(iia): the family-pension deduction is the lower of one-third or the monetary cap - Rs.15,000 old regime, raised to Rs.25,000 under the new regime (FY 2024-25 onward).","source":"Original","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified"},{"id":216,"stem":"Gifts of money exceeding Rs.________ in aggregate during the year from non-relatives are taxable under Section 56(2)(x):","options":[{"key":"A","text":"1,00,000"},{"key":"B","text":"50,000"},{"key":"C","text":"5,000"},{"key":"D","text":"25,000"}],"answer":"B","explanation":"Aggregate cash/kind gifts above Rs.50,000 from non-relatives are taxable; gifts from specified relatives, on marriage, by inheritance/will and from local authorities/trusts are exempt.","source":"Original","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified"},{"id":217,"stem":"Which of the following gifts is TAXABLE?","options":[{"key":"A","text":"Gift received on the occasion of marriage"},{"key":"B","text":"Gift under a will"},{"key":"C","text":"Gift from father"},{"key":"D","text":"Gift of Rs.60,000 from a FRIEND"}],"answer":"D","explanation":"Friends are not \"relatives\" for s.56(2)(x); marriage gifts, inheritances and relative gifts are exempt regardless of amount.","source":"Original","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified"},{"id":218,"stem":"Interest on compensation/enhanced compensation (land acquisition) is:","options":[{"key":"A","text":"Fully exempt"},{"key":"B","text":"Clubbed with spouse"},{"key":"C","text":"Taxable as other sources, with a 50% DEDUCTION under Section 57(iv)"},{"key":"D","text":"Taxed as capital gains"}],"answer":"C","explanation":"Interest on compensation is other-sources income in the year of receipt (s.145B), with a flat 50% deduction u/s 57(iv).","source":"Original","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified"},{"id":219,"stem":"Interest on FIXED DEPOSITS with a bank is:","options":[{"key":"A","text":"Exempt up to Rs.10,000"},{"key":"B","text":"Taxed at flat 30%"},{"key":"C","text":"Fully taxable under other sources (80TTA/80TTB deductions apply separately)"},{"key":"D","text":"Exempt for senior citizens"}],"answer":"C","explanation":"Deposit interest is fully taxable; s.80TTA (Rs.10,000, savings interest) and s.80TTB (Rs.50,000, senior citizens) give separate deductions - but only in the OLD regime.","source":"Original","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified"},{"id":220,"stem":"Interest on NSC (accrued annually) is:","options":[{"key":"A","text":"Taxed only at maturity in all cases"},{"key":"B","text":"Taxed on ACCRUAL basis as other sources - but eligible for 80C as reinvested (old regime), except in the final year"},{"key":"C","text":"Clubbed with minor"},{"key":"D","text":"Exempt"}],"answer":"B","explanation":"NSC interest accrues yearly and is deemed reinvested (80C-eligible) except in the year of maturity.","source":"Original","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified"},{"id":221,"stem":"Lease premium received for letting out premises on lease is split between:","options":[{"key":"A","text":"Fully exempt"},{"key":"B","text":"Fully capital gains"},{"key":"C","text":"Fully salary"},{"key":"D","text":"CAPITAL GAINS (the premium part, as a transfer of rights) and the RENT portion as house-property/other-sources income"}],"answer":"D","explanation":"The premium on a lease is a capital-gains event; periodic lease rent is house-property or other-sources income.","source":"Source label not detected","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified"},{"id":222,"stem":"Advance money received and FORFEITED in failed negotiations for transfer of a capital asset is:","options":[{"key":"A","text":"Exempt"},{"key":"B","text":"Reduced from the cost of acquisition"},{"key":"C","text":"A capital receipt"},{"key":"D","text":"Taxable as INCOME FROM OTHER SOURCES under s.56(2)(ix) (from AY 2015-16)"}],"answer":"D","explanation":"Forfeited advance money is now other-sources income; it no longer reduces the cost of the asset.","source":"Original","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified"},{"id":223,"stem":"Interest received by a NON-RESIDENT senior citizen on an NRO deposit is subject to TDS at:","options":[{"key":"A","text":"10% flat always"},{"key":"B","text":"5%"},{"key":"C","text":"Nil"},{"key":"D","text":"Rates under Section 195 (DTAA-modified) - higher TDS applies on non-resident payments than the resident 194A rates"}],"answer":"D","explanation":"Non-resident payments attract s.195 TDS at rates in force/DTAA relief; residents face the 194A rates. The exam recall hinges on the resident/non-resident distinction.","source":"Source label not detected","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified"},{"id":224,"stem":"Agricultural income from land situated in PAKISTAN received by a resident is:","options":[{"key":"A","text":"Clubbed with spouse"},{"key":"B","text":"TAXABLE in India as income from OTHER SOURCES (foreign agricultural income is not \"agricultural income\" under the Act)"},{"key":"C","text":"Agricultural income - exempt"},{"key":"D","text":"Exempt up to Rs.5,000"}],"answer":"B","explanation":"Only income from land in INDIA qualifies as agricultural income; foreign farm income of a resident is taxable as other sources.","source":"Original","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified"},{"id":225,"stem":"Amount received under a KEYMAN INSURANCE POLICY (including bonus) is:","options":[{"key":"A","text":"Exempt up to Rs.1 lakh"},{"key":"B","text":"Exempt under s.10(10D)"},{"key":"C","text":"Taxed as salary always"},{"key":"D","text":"TAXABLE - s.10(10D) exemption does not apply to keyman policies; taxed as business income or other sources"}],"answer":"D","explanation":"Keyman insurance policy proceeds are expressly excluded from s.10(10D) exemption.","source":"Original","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified"},{"id":226,"stem":"Shares received WITHOUT consideration or for inadequate consideration by a firm or closely-held company are taxed under:","options":[{"key":"A","text":"Section 56(2)(x) - fair value above Rs.50,000 taxed in the recipient hands"},{"key":"B","text":"Section 28"},{"key":"C","text":"Section 45"},{"key":"D","text":"Exempt"}],"answer":"A","explanation":"Section 56(2)(x) taxes any person (including firms and closely-held companies) receiving shares or other specified property for nil or inadequate consideration, where the fair-value shortfall exceeds Rs.50,000.","source":"Original","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified"},{"id":227,"stem":"A scholarship granted to meet the cost of education is:","options":[{"key":"A","text":"Taxable at 10%"},{"key":"B","text":"Clubbed with parent"},{"key":"C","text":"Fully EXEMPT under Section 10(16)"},{"key":"D","text":"Taxable as salary"}],"answer":"C","explanation":"Section 10(16) exempts scholarships entirely, regardless of amount or recipient.","source":"Original","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified"},{"id":228,"stem":"Interest on REFUND of income tax is:","options":[{"key":"A","text":"Taxed as capital gains"},{"key":"B","text":"Part of the refund"},{"key":"C","text":"Exempt"},{"key":"D","text":"Taxable as income from OTHER SOURCES in the year of receipt"}],"answer":"D","explanation":"Section 244A interest is taxable as other-sources income in the year the refund is received.","source":"Original","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified"},{"id":229,"stem":"The deduction for interest on compensation money u/s 57(iv) is:","options":[{"key":"A","text":"1/3rd"},{"key":"B","text":"50%"},{"key":"C","text":"100%"},{"key":"D","text":"30%"}],"answer":"B","explanation":"A flat 50% deduction is allowed against interest on compensation/enhanced compensation.","source":"Original","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified"},{"id":230,"stem":"Expenses deductible from other-sources income under Section 57 do NOT include:","options":[{"key":"A","text":"PERSONAL expenses of the assessee"},{"key":"B","text":"Collection charges for interest/dividends"},{"key":"C","text":"Repairs, insurance and depreciation on machinery/furniture let out"},{"key":"D","text":"Interest/commission paid to earn the income"}],"answer":"A","explanation":"Section 57 allows only expenses laid out wholly and exclusively for earning the income (and the specified items); personal expenses are barred (s.58(1)(a)(i)).","source":"Original","module":"T5","topic":"Income from Other Sources","reviewStatus":"Source key not independently verified"},{"id":231,"stem":"Clubbing of income (Sections 60-64) is designed to:","options":[{"key":"A","text":"Increase exemption limits"},{"key":"B","text":"Tax foreign income"},{"key":"C","text":"Prevent AVOIDANCE of tax by transferring income (without the asset) or assets to related persons while retaining benefit"},{"key":"D","text":"Double the tax"}],"answer":"C","explanation":"Clubbing provisions attribute diverted income back to the transferor to check tax avoidance through family arrangements.","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified"},{"id":232,"stem":"Where income is transferred WITHOUT transferring the asset, the income is taxed in the hands of:","options":[{"key":"A","text":"Neither"},{"key":"B","text":"Both equally"},{"key":"C","text":"The transferee"},{"key":"D","text":"The TRANSFEROR (Section 60)"}],"answer":"D","explanation":"Section 60: revocable or asset-less income transfers keep the income taxable in the transferor hands.","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified"},{"id":233,"stem":"A REVOCABLE transfer of assets is taxed in the hands of:","options":[{"key":"A","text":"The TRANSFEROR (Section 61) - the power to revoke keeps the income with him"},{"key":"B","text":"The trust"},{"key":"C","text":"The transferee"},{"key":"D","text":"The minor child"}],"answer":"A","explanation":"Sections 61-63: income from revocable transfers is taxed in the transferor hands; an irrevocable transfer (for life of the transferee or beyond) escapes this rule.","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified"},{"id":234,"stem":"Salary/commission received by a SPOUSE from a concern in which the other spouse has a SUBSTANTIAL INTEREST is clubbed with the income of:","options":[{"key":"A","text":"The minor child"},{"key":"B","text":"The employer"},{"key":"C","text":"The OTHER spouse - UNLESS the earning spouse possesses technical or professional qualification and the income is solely attributable to that qualification (s.64(1)(ii))"},{"key":"D","text":"The earning spouse always"}],"answer":"C","explanation":"Substantial interest = 20%+ voting power (company) or profit share (firm); the professional-qualification exception prevents clubbing of genuinely earned pay.","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified"},{"id":235,"stem":"Income from assets transferred to the SPOUSE without adequate consideration (not in connection with an agreement to live apart) is:","options":[{"key":"A","text":"Taxed in the transferee spouse hands"},{"key":"B","text":"Taxed at 30%"},{"key":"C","text":"CLUBBED with the transferor income under s.64(1)(iv)"},{"key":"D","text":"Exempt"}],"answer":"C","explanation":"Direct transfers to spouse (and to son wife, s.64(1)(vi)) without adequate consideration attract clubbing with the transferor.","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified"},{"id":236,"stem":"Income of a MINOR CHILD is clubbed with:","options":[{"key":"A","text":"The parent whose TOTAL INCOME (before clubbing) is GREATER (s.64(1A)); where the marriage does not subsist, with the parent who maintains the child"},{"key":"B","text":"Nobody - minors are separately assessed always"},{"key":"C","text":"The father income always"},{"key":"D","text":"The guardian appointed by court"}],"answer":"A","explanation":"Once the higher-income parent is fixed, the choice stays for subsequent years unless the income order changes; exemption of Rs.1,500 per child u/s 10(32).","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified"},{"id":237,"stem":"Clubbing does NOT apply to income earned by a minor child from:","options":[{"key":"A","text":"Fixed deposits gifted by parents"},{"key":"B","text":"Gifts from grandparents"},{"key":"C","text":"His OWN manual work or specialised talent/knowledge (e.g. a child artist)"},{"key":"D","text":"Savings account interest"}],"answer":"C","explanation":"Proviso to s.64(1A): income from the child personal skill, manual work or specialised knowledge is taxed in the child own assessment.","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified"},{"id":238,"stem":"The exemption for clubbed minor child income under Section 10(32) is:","options":[{"key":"A","text":"Rs.5,000 per child"},{"key":"B","text":"Rs.1,500 per child per year"},{"key":"C","text":"Rs.2,500 per child"},{"key":"D","text":"Rs.10,000 per child"}],"answer":"B","explanation":"Rs.1,500 per minor child (or the clubbed income, if less) is exempt to the parent in whose hands it is clubbed.","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified"},{"id":239,"stem":"Income from property transferred to a HINDU UNDIVIDED FAMILY by a member without consideration, before partition, is:","options":[{"key":"A","text":"CLUBBED with the member income; after partition it is clubbed with the spouse income in the hands of the transferor (s.64(2))"},{"key":"B","text":"Taxed in the HUF hands"},{"key":"C","text":"Taxed at 20%"},{"key":"D","text":"Exempt"}],"answer":"A","explanation":"Section 64(2): converted property income is deemed to be the individual income of the transferor; post-partition, the spouse share is clubbed.","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified"},{"id":240,"stem":"Loss from one SOURCE can be set off against income of another source under the SAME head - this is called:","options":[{"key":"A","text":"Carry forward"},{"key":"B","text":"Inter-head set-off"},{"key":"C","text":"Clubbing"},{"key":"D","text":"INTRA-HEAD set-off (s.70)"}],"answer":"D","explanation":"Section 70 permits intra-head (same-head) set-off; s.71 permits inter-head set-off, subject to exceptions.","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified"},{"id":241,"stem":"Which loss CANNOT be set off against income under any OTHER head in the same year?","options":[{"key":"A","text":"Non-speculation business loss"},{"key":"B","text":"House property loss (within Rs.2 lakh)"},{"key":"C","text":"Other sources loss"},{"key":"D","text":"SPECULATION loss (only against speculation profits) and CAPITAL loss (only against capital gains)"}],"answer":"D","explanation":"Speculation losses (s.73) and capital losses (s.70(2)/74) are ring-fenced to their own categories.","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified"},{"id":242,"stem":"Loss under the head \"Income from house property\" can be set off against other heads in the same year up to:","options":[{"key":"A","text":"Rs.1,50,000"},{"key":"B","text":"No limit"},{"key":"C","text":"Rs.50,000"},{"key":"D","text":"Rs.2,00,000"}],"answer":"D","explanation":"Section 71(3A) caps inter-head set-off of house-property loss at Rs.2 lakh; the balance carries forward 8 years (s.71B).","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified"},{"id":243,"stem":"Business loss (non-speculation) can be carried forward for ________ and set off against ________:","options":[{"key":"A","text":"Indefinitely; any head"},{"key":"B","text":"8 ASSESSMENT YEARS; profits of any business/profession only"},{"key":"C","text":"4 years; any income"},{"key":"D","text":"8 years; any head"}],"answer":"B","explanation":"Section 72: 8-year carry forward, set off only against business/profession profits; filing the loss return in time is a precondition (s.80).","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified"},{"id":244,"stem":"For carry forward of LOSSES (other than house-property loss), the return must be filed:","options":[{"key":"A","text":"Never required"},{"key":"B","text":"On or before the DUE DATE under Section 139(1) (Section 80)"},{"key":"C","text":"Any time before assessment"},{"key":"D","text":"Within 4 years"}],"answer":"B","explanation":"Section 80 bars carry forward unless the loss return is filed by the s.139(1) due date; belated filing forfeits carry forward (though current-year set-off survives).","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified"},{"id":245,"stem":"Unabsorbed depreciation, in the order of set-off, is treated as:","options":[{"key":"A","text":"A capital loss"},{"key":"B","text":"A business loss of the year"},{"key":"C","text":"A speculation loss"},{"key":"D","text":"CURRENT-YEAR depreciation - carried forward indefinitely, and claimed BEFORE brought-forward business loss"}],"answer":"D","explanation":"Section 32(2): unabsorbed depreciation is deemed depreciation of the following year, with indefinite carry forward and priority over brought-forward business losses.","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified"},{"id":246,"stem":"The correct order of set-off is: (1) current depreciation, (2) capital expenditure on scientific research, (3) ________, (4) unabsorbed depreciation:","options":[{"key":"A","text":"Capital losses"},{"key":"B","text":"Donations"},{"key":"C","text":"Current-year losses first, then brought-forward BUSINESS LOSS, then unabsorbed depreciation"},{"key":"D","text":"Brought-forward business loss"}],"answer":"C","explanation":"Priority: current depreciation and scientific-research capex, then brought-forward business loss, then unabsorbed depreciation (s.72(2) ordering read with s.35(4) and s.32(2)).","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified"},{"id":247,"stem":"Loss from the activity of owning and maintaining RACE HORSES can be set off against:","options":[{"key":"A","text":"House property"},{"key":"B","text":"Any business income"},{"key":"C","text":"Salary"},{"key":"D","text":"Income from the SAME activity only, carried forward 4 years"}],"answer":"D","explanation":"Section 74A: race-horse activity losses are ring-fenced to the same activity with a 4-year carry forward.","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified"},{"id":248,"stem":"Loss under \"Capital gains\" can be set off in the same year against:","options":[{"key":"A","text":"Other sources"},{"key":"B","text":"Salary income"},{"key":"C","text":"Business income"},{"key":"D","text":"Capital gains only (intra-head within the capital-gains head)"}],"answer":"D","explanation":"Capital losses cannot move to any other head; within the year they set off against capital gains, with LTCL restricted to LTCG.","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified"},{"id":249,"stem":"A HUF suffers a business loss which cannot be set off fully in the year. It can be carried forward by:","options":[{"key":"A","text":"The eldest member"},{"key":"B","text":"Nobody"},{"key":"C","text":"The HUF ITSELF for 8 years"},{"key":"D","text":"The karta personally"}],"answer":"C","explanation":"The same assessment entity carries the loss forward; on partition of the HUF, unabsorbed losses cannot be carried forward by members.","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified"},{"id":250,"stem":"Where an assessee dies leaving an unabsorbed business loss, the loss:","options":[{"key":"A","text":"Transfers to HUF"},{"key":"B","text":"LAPSES - carry forward is personal to the assessee (except unabsorbed depreciation, which also lapses... properly: losses do not pass to heirs; only the deceased own assessment can use them)"},{"key":"C","text":"Transfers to spouse"},{"key":"D","text":"Carries forward to the legal heir"}],"answer":"B","explanation":"Carry-forward rights are personal to the assessee; a legal heir cannot claim the deceased brought-forward business losses (s.78(2) permits carry forward to the successor only in specified successions to business, not on inheritance).","source":"Original","module":"T6","topic":"Clubbing, Set-off & Carry Forward","reviewStatus":"Source key not independently verified"},{"id":251,"stem":"Deductions under Chapter VI-A (80C to 80U) are allowed from:","options":[{"key":"A","text":"GROSS TOTAL INCOME - but cannot exceed the GTI"},{"key":"B","text":"Capital gains only"},{"key":"C","text":"Salary only"},{"key":"D","text":"Total income"}],"answer":"A","explanation":"VI-A deductions reduce GTI to arrive at total income; the aggregate cannot exceed GTI (no loss creation).","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":252,"stem":"The maximum deduction under Section 80C (LIC premium, PPF, EPF, NSC, ELSS, tuition fees, home-loan principal, 5-year tax-saver FD, Sukanya Samriddhi etc.) is:","options":[{"key":"A","text":"Rs.1,00,000"},{"key":"B","text":"Rs.2,00,000"},{"key":"C","text":"Rs.1,50,000"},{"key":"D","text":"Rs.50,000"}],"answer":"C","explanation":"Section 80C caps at Rs.1.5 lakh; 80CCC (pension funds) and 80CCD(1) (self NPS) share this ceiling via s.80CCE.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":253,"stem":"The COMBINED ceiling under Section 80CCE (80C + 80CCC + 80CCD(1)) is:","options":[{"key":"A","text":"Rs.2,00,000"},{"key":"B","text":"Rs.1,50,000"},{"key":"C","text":"Rs.2,50,000"},{"key":"D","text":"Rs.1,00,000"}],"answer":"B","explanation":"80CCE caps the trio at Rs.1.5 lakh; the extra NPS benefit of Rs.50,000 comes under 80CCD(1B) outside this cap.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":254,"stem":"An additional deduction for self-contribution to NPS under Section 80CCD(1B), over and above the 80CCE limit, is:","options":[{"key":"A","text":"Rs.50,000"},{"key":"B","text":"Rs.25,000"},{"key":"C","text":"Rs.1,50,000"},{"key":"D","text":"Rs.1,00,000"}],"answer":"A","explanation":"80CCD(1B) gives an extra Rs.50,000 for NPS Tier-I contributions - over and above the Rs.1.5 lakh 80CCE basket.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":255,"stem":"Employer NPS contribution deductible to the employee under 80CCD(2) is capped at:","options":[{"key":"A","text":"10% of basic+DA in old regime; 14% of basic+DA in the NEW regime (private sector included, from FY 2024-25)"},{"key":"B","text":"15% of gross salary"},{"key":"C","text":"Nil"},{"key":"D","text":"Rs.50,000 flat"}],"answer":"A","explanation":"80CCD(2) is outside 80CCE; the new-regime limit is 14% of basic+DA for all employees (10% in the old regime for private sector; 14% for Central Government in both).","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":256,"stem":"Section 80D deduction for medical insurance premium for SELF, SPOUSE AND DEPENDENT CHILDREN (none a senior citizen) is up to:","options":[{"key":"A","text":"Rs.50,000"},{"key":"B","text":"Rs.1,00,000"},{"key":"C","text":"Rs.25,000"},{"key":"D","text":"Rs.15,000"}],"answer":"C","explanation":"80D: Rs.25,000 for self+spouse+dependent children; an ADDITIONAL Rs.25,000 for parents (Rs.50,000 if parents are senior citizens).","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":257,"stem":"The 80D deduction for a SENIOR CITIZEN (60+) covering his own family premium is up to:","options":[{"key":"A","text":"Rs.30,000"},{"key":"B","text":"Rs.50,000"},{"key":"C","text":"Rs.25,000"},{"key":"D","text":"Rs.75,000"}],"answer":"B","explanation":"Senior citizens get Rs.50,000; a super-senior (80+) without insurance can claim medical EXPENDITURE up to Rs.50,000.","source":"Source label not detected","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":258,"stem":"Preventive health check-up expenditure is deductible under 80D up to:","options":[{"key":"A","text":"Rs.25,000"},{"key":"B","text":"Nil"},{"key":"C","text":"Rs.5,000, WITHIN the overall 80D ceiling (cash payment permitted)"},{"key":"D","text":"Rs.10,000 separately"}],"answer":"C","explanation":"Preventive check-ups get Rs.5,000 within the overall Rs.25,000/Rs.50,000 cap - and may be paid in cash.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":259,"stem":"Maximum deduction under Section 80D for a person paying premium for self (below 60) AND senior-citizen parents is:","options":[{"key":"A","text":"Rs.1,00,000"},{"key":"B","text":"Rs.75,000"},{"key":"C","text":"Rs.50,000"},{"key":"D","text":"Rs.25,000"}],"answer":"B","explanation":"Rs.25,000 (self family) + Rs.50,000 (senior-citizen parents) = Rs.75,000; if the taxpayer is also a senior citizen, it can reach Rs.1,00,000.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":260,"stem":"80D premiums must be paid by:","options":[{"key":"A","text":"Demand draft only"},{"key":"B","text":"Cash"},{"key":"C","text":"NEFT only"},{"key":"D","text":"Any mode EXCEPT cash (cheque/card/electronic) - only preventive check-ups can be cash"}],"answer":"D","explanation":"Section 80D(2B) requires non-cash payment for premiums; preventive health check-ups may be paid in cash.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":261,"stem":"Section 80DD deduction for maintenance including medical treatment of a DEPENDENT with DISABILITY is:","options":[{"key":"A","text":"Rs.75,000 flat - Rs.1,25,000 for SEVERE disability (80%+), regardless of actual expenditure"},{"key":"B","text":"Actual expenses"},{"key":"C","text":"Rs.40,000"},{"key":"D","text":"Rs.25,000"}],"answer":"A","explanation":"80DD is a flat deduction (not expenditure-linked): Rs.75,000 normal disability, Rs.1,25,000 severe disability, for resident assessees with disabled dependants.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":262,"stem":"Section 80DDB (treatment of specified diseases) deduction is:","options":[{"key":"A","text":"Rs.50,000"},{"key":"B","text":"Rs.75,000 flat"},{"key":"C","text":"Rs.40,000 (Rs.1,00,000 for SENIOR CITIZENS)"},{"key":"D","text":"Actual expenses always"}],"answer":"C","explanation":"80DDB: up to Rs.40,000, raised to Rs.1,00,000 when the patient is a senior citizen; the amount is reduced by any insurance/employer reimbursement.","source":"Source label not detected","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":263,"stem":"Section 80E deduction for interest on an EDUCATION LOAN for higher studies is:","options":[{"key":"A","text":"Rs.50,000"},{"key":"B","text":"Rs.1.5 lakh"},{"key":"C","text":"Up to Rs.40,000"},{"key":"D","text":"The ENTIRE interest, for a maximum of 8 YEARS, with no monetary ceiling"}],"answer":"D","explanation":"80E covers full interest (no cap) on loans for self/spouse/children/ward higher education, for up to 8 years from the first repayment year.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":264,"stem":"Section 80G: donations in CASH qualify for deduction only up to:","options":[{"key":"A","text":"Rs.20,000"},{"key":"B","text":"Rs.5,000"},{"key":"C","text":"Rs.2,000 per donation"},{"key":"D","text":"Rs.10,000"}],"answer":"C","explanation":"Cash donations above Rs.2,000 get no 80G deduction; larger donations must be by cheque/draft/electronic mode.","source":"Source label not detected","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":265,"stem":"Donations to the National Defence Fund / Prime Minister National Relief Fund qualify for deduction of:","options":[{"key":"A","text":"100% of the donation WITHOUT any qualifying limit"},{"key":"B","text":"50% subject to 10% of adjusted GTI"},{"key":"C","text":"50% of the donation"},{"key":"D","text":"Nil"}],"answer":"A","explanation":"The 100%-without-limit category covers PMNRF, National Defence Fund, PM CARES etc.; the 50%-with-limit category covers most trusts (10% of adjusted GTI cap).","source":"Source label not detected","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":266,"stem":"The qualifying limit for the 50%-category donations under 80G is:","options":[{"key":"A","text":"No limit"},{"key":"B","text":"10% of ADJUSTED GROSS TOTAL INCOME (GTI minus VI-A deductions other than 80G, minus exempt/LTCG/special-rate incomes)"},{"key":"C","text":"Rs.1 lakh"},{"key":"D","text":"20% of salary"}],"answer":"B","explanation":"The 50% category (with limit) is capped at 10% of adjusted GTI; 100%-category funds have no such cap.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":267,"stem":"Section 80GG (rent paid by those NOT receiving HRA) deduction is the LEAST of: (i) Rs.5,000 per month, (ii) 25% of adjusted total income, (iii):","options":[{"key":"A","text":"Actual rent paid"},{"key":"B","text":"Rs.60,000"},{"key":"C","text":"Rent paid MINUS 10% of adjusted total income"},{"key":"D","text":"50% of salary"}],"answer":"C","explanation":"80GG aids self-employed/no-HRA renters: least of Rs.5,000 p.m., 25% of adjusted total income, or rent minus 10% of adjusted total income - provided neither the taxpayer, spouse nor minor child owns a residence at the work place.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":268,"stem":"Section 80GGA covers donations for:","options":[{"key":"A","text":"Medical treatment"},{"key":"B","text":"SCIENTIFIC RESEARCH or RURAL DEVELOPMENT - 100% deduction (but NOT for those having business/profession income; CASH donations limited to Rs.2,000)"},{"key":"C","text":"Home loans"},{"key":"D","text":"Political parties"}],"answer":"B","explanation":"80GGA donations are fully deductible for non-business assessees; business assessees claim them under s.35 instead.","source":"Source label not detected","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":269,"stem":"Contributions to registered POLITICAL PARTIES are deductible under:","options":[{"key":"A","text":"80C"},{"key":"B","text":"Section 80GGB (companies) and 80GGC (any other person) - 100%, but NO deduction for CASH contributions"},{"key":"C","text":"80D"},{"key":"D","text":"80G"}],"answer":"B","explanation":"Political donations are 100% deductible under 80GGB/80GGC, but only by non-cash modes.","source":"Source label not detected","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":270,"stem":"Section 80TTA allows deduction of up to Rs.10,000 for:","options":[{"key":"A","text":"All interest"},{"key":"B","text":"FD interest"},{"key":"C","text":"SAVINGS ACCOUNT interest (banks/post offices) - NOT fixed deposit interest; individuals/HUF below 60 years"},{"key":"D","text":"Loan interest"}],"answer":"C","explanation":"80TTA covers savings-account interest up to Rs.10,000; FD/RD interest is excluded (senior citizens use the wider 80TTB).","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":271,"stem":"Section 80TTB gives SENIOR CITIZENS (60+) a deduction of up to Rs.50,000 for:","options":[{"key":"A","text":"Interest on ALL deposits with banks, co-operative banks and post offices (savings AND fixed deposits)"},{"key":"B","text":"Only savings interest"},{"key":"C","text":"Pension"},{"key":"D","text":"Share dividends"}],"answer":"A","explanation":"80TTB is the wider senior-citizen interest deduction; seniors cannot also claim 80TTA.","source":"Source label not detected","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":272,"stem":"Section 80U deduction for a person WITH DISABILITY (resident individual) is:","options":[{"key":"A","text":"Rs.50,000"},{"key":"B","text":"Rs.75,000 flat - Rs.1,25,000 for SEVERE disability (80%+)"},{"key":"C","text":"Rs.1,00,000"},{"key":"D","text":"Rs.40,000"}],"answer":"B","explanation":"80U is for the taxpayer own disability (flat amounts); 80DD is for a dependent. Both are flat deductions.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":273,"stem":"Section 80C includes tuition fees paid for:","options":[{"key":"A","text":"FULL-TIME education of up to TWO CHILDREN in Indian institutions (not donations, development fees or coaching)"},{"key":"B","text":"Spouse education"},{"key":"C","text":"Any course anywhere"},{"key":"D","text":"Abroad studies"}],"answer":"A","explanation":"Only full-time tuition fees of the assessee own children (max two) at Indian educational institutions qualify.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":274,"stem":"Principal repayment of a HOME LOAN qualifies under 80C, and interest under:","options":[{"key":"A","text":"Section 80D"},{"key":"B","text":"Section 24(b) (house-property head - Rs.2 lakh self-occupied, old regime)"},{"key":"C","text":"Section 80G"},{"key":"D","text":"Section 80C itself"}],"answer":"B","explanation":"Principal goes in the 80C basket; interest is claimed under the house-property head s.24(b).","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":275,"stem":"Deduction under Section 80CCD(1) (self NPS contribution) for an employee is capped at:","options":[{"key":"A","text":"Rs.2 lakh"},{"key":"B","text":"Rs.75,000"},{"key":"C","text":"10% of salary within the Rs.1.5 lakh 80CCE limit (20% of GTI for self-employed)"},{"key":"D","text":"No limit"}],"answer":"C","explanation":"Self NPS contributions sit inside the 80CCE basket, capped at 10% of salary (employees) or 20% of GTI (others), plus the 80CCD(1B) extra Rs.50,000.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":276,"stem":"Which VI-A deduction is AVAILABLE under the NEW tax regime (115BAC)?","options":[{"key":"A","text":"80CCD(2) (employer NPS) and 80JJAA (additional employment)"},{"key":"B","text":"80C"},{"key":"C","text":"80G"},{"key":"D","text":"80D"}],"answer":"A","explanation":"The new regime keeps only 80CCD(2), 80JJAA and (for specified new manufacturing) 80LA-type deductions; all personal deductions (80C, 80D, 80G, 80TTA etc.) are barred.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":277,"stem":"Section 80JJAA (additional employee cost) allows a deduction of:","options":[{"key":"A","text":"50% of salaries"},{"key":"B","text":"30% of additional employee cost for 3 consecutive years, for all businesses (except those formed by splitting/reconstruction)"},{"key":"C","text":"100% for one year"},{"key":"D","text":"Rs.1 lakh flat"}],"answer":"B","explanation":"80JJAA incentivises employment: 30% of the additional employee cost for three years; new-regime taxpayers can also claim it.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":278,"stem":"Section 80QQB (royalty on books) allows authors a deduction up to:","options":[{"key":"A","text":"Rs.50,000"},{"key":"B","text":"Rs.1 lakh"},{"key":"C","text":"Rs.5 lakh"},{"key":"D","text":"Rs.3 lakh"}],"answer":"D","explanation":"Resident authors of specified literary/artistic/scientific books deduct royalty income up to Rs.3 lakh (80RRB similarly for patents).","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":279,"stem":"Deduction under Section 80D for parents can be claimed even if the parents are:","options":[{"key":"A","text":"Dependent on the assessee"},{"key":"B","text":"Senior citizens only"},{"key":"C","text":"NOT DEPENDENT on the assessee - dependency is not a condition"},{"key":"D","text":"Living abroad"}],"answer":"C","explanation":"80D has no dependency condition for parents; only the premium payment by the assessee matters.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":280,"stem":"A salaried employee in the OLD regime claims: PPF Rs.1,00,000, LIC premium Rs.30,000, ELSS Rs.40,000, tuition fees Rs.25,000. His 80C deduction is:","options":[{"key":"A","text":"Rs.1,30,000"},{"key":"B","text":"Rs.1,70,000"},{"key":"C","text":"Rs.1,95,000"},{"key":"D","text":"Rs.1,50,000"}],"answer":"D","explanation":"Total investments 1,95,000, but the 80C cap is Rs.1,50,000.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":281,"stem":"An individual (below 60) pays: medical insurance self Rs.18,000, parents (senior citizens) Rs.32,000, preventive check-up (cash) Rs.6,000 (for self). His 80D deduction is:","options":[{"key":"A","text":"Rs.55,000"},{"key":"B","text":"Rs.50,000"},{"key":"C","text":"Rs.56,000"},{"key":"D","text":"Rs.68,000"}],"answer":"A","explanation":"Self: premium 18,000 + check-up capped at 5,000 = 23,000 (within 25,000). Parents: 32,000 (within 50,000). Total = 55,000.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":282,"stem":"Section 80GGB allows a COMPANY to deduct political contributions:","options":[{"key":"A","text":"Up to 10% of profits"},{"key":"B","text":"50%"},{"key":"C","text":"100% of the contribution - but ONLY by non-cash mode"},{"key":"D","text":"Nil - companies cannot donate"}],"answer":"C","explanation":"Companies deduct 100% of non-cash political contributions under 80GGB; other persons use 80GGC.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":283,"stem":"Section 80GG CANNOT be claimed by a taxpayer who:","options":[{"key":"A","text":"Is self-employed"},{"key":"B","text":"Receives HRA at any time during the year, or owns a residential house at the place of work/residence"},{"key":"C","text":"Pays rent for residence"},{"key":"D","text":"Lives in a metro"}],"answer":"B","explanation":"80GG is for those who receive NO HRA and own no house at the place of their employment/residence.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":284,"stem":"Sukanya Samriddhi Account deposits (for a girl child) qualify under:","options":[{"key":"A","text":"80TTA"},{"key":"B","text":"80D"},{"key":"C","text":"80C - deposits deductible, interest and maturity EXEMPT (EEE status)"},{"key":"D","text":"80G"}],"answer":"C","explanation":"SSA is an EEE instrument: deposit under 80C, interest and maturity exempt under s.10(11A).","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":285,"stem":"Deduction for interest on loan taken for RESIDENTIAL house property under s.80EE / 80EEA is:","options":[{"key":"A","text":"Rs.50,000 always"},{"key":"B","text":"Sections 80EE/80EEA have SUNSET (loans sanctioned in specified past windows) - no new deduction under them for loans sanctioned now"},{"key":"C","text":"Available currently for all"},{"key":"D","text":"Rs.2 lakh always"}],"answer":"B","explanation":"80EE applied to loans sanctioned in FY 2016-17 and 80EEA to loans sanctioned during FY 2019-20 to FY 2021-22; neither is available for fresh loans.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":286,"stem":"Under Section 87A, a RESIDENT INDIVIDUAL in the OLD regime gets a rebate of up to Rs.12,500 if total income does not exceed:","options":[{"key":"A","text":"Rs.12,00,000"},{"key":"B","text":"Rs.7,00,000"},{"key":"C","text":"Rs.3,50,000"},{"key":"D","text":"Rs.5,00,000"}],"answer":"D","explanation":"Old regime 87A: rebate up to Rs.12,500 where total income is up to Rs.5 lakh (tax becomes nil); the 2018-era Rs.2,500/Rs.3.5 lakh figures are outdated.","source":"Source label not detected","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":287,"stem":"Under the NEW regime (FY 2025-26), the Section 87A rebate makes tax effectively NIL for total income up to:","options":[{"key":"A","text":"Rs.5 lakh"},{"key":"B","text":"Rs.12 LAKH (maximum rebate Rs.60,000), with marginal relief"},{"key":"C","text":"Rs.10 lakh"},{"key":"D","text":"Rs.7 lakh"}],"answer":"B","explanation":"Finance Act 2025 raised the new-regime rebate to Rs.60,000 for total income up to Rs.12 lakh; marginal relief protects incomes slightly above Rs.12 lakh.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":288,"stem":"The Rs.60,000 new-regime rebate under 87A is available to:","options":[{"key":"A","text":"Companies"},{"key":"B","text":"All assessees"},{"key":"C","text":"All senior citizens only"},{"key":"D","text":"RESIDENT INDIVIDUALS only - not HUF, firms, companies or non-residents"}],"answer":"D","explanation":"Section 87A rebates are personal to resident individuals, in both regimes.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":289,"stem":"Marginal relief under the new-regime 87A rebate means that where total income marginally exceeds Rs.12 lakh, the tax payable cannot exceed:","options":[{"key":"A","text":"Rs.60,000"},{"key":"B","text":"Nil"},{"key":"C","text":"Rs.10,000"},{"key":"D","text":"The amount by which the total income EXCEEDS Rs.12 lakh"}],"answer":"D","explanation":"Marginal relief caps the tax at the excess of income over Rs.12 lakh - so earning Rs.1,000 above the threshold never costs more than Rs.1,000 in tax.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":290,"stem":"Salaried income up to Rs.12,75,000 (new regime, FY 2025-26) can effectively pay NIL tax because of:","options":[{"key":"A","text":"HRA"},{"key":"B","text":"Agricultural income"},{"key":"C","text":"80C investments"},{"key":"D","text":"STANDARD DEDUCTION of Rs.75,000 plus the 87A rebate up to Rs.12 lakh of total income"}],"answer":"D","explanation":"Salary minus Rs.75,000 standard deduction brings total income to Rs.12 lakh, where the 87A rebate wipes out the tax.","source":"Original","module":"T7","topic":"Deductions (Chapter VI-A) & Rebate 87A","reviewStatus":"Source key not independently verified"},{"id":291,"stem":"For FY 2025-26 (AY 2026-27) under the NEW regime (default, Section 115BAC), income above Rs.24 lakh is taxed at:","options":[{"key":"A","text":"25%"},{"key":"B","text":"35%"},{"key":"C","text":"20%"},{"key":"D","text":"30%"}],"answer":"D","explanation":"New-regime slabs: 0-4L nil, 4-8L 5%, 8-12L 10%, 12-16L 15%, 16-20L 20%, 20-24L 25%, above 24L 30%.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":292,"stem":"Under the NEW regime for FY 2025-26, the slab from Rs.4,00,001 to Rs.8,00,000 is taxed at:","options":[{"key":"A","text":"5%"},{"key":"B","text":"10%"},{"key":"C","text":"15%"},{"key":"D","text":"Nil"}],"answer":"A","explanation":"The new-regime ladder from Finance Act 2025: 5% for 4-8L, 10% for 8-12L, 15% for 12-16L.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":293,"stem":"The new tax regime under Section 115BAC is the:","options":[{"key":"A","text":"Optional regime only"},{"key":"B","text":"DEFAULT regime for individuals/HUF etc. - the assessee must OPT OUT to use the old regime (by filing Form 10-IEA for business income)"},{"key":"C","text":"Regime only for senior citizens"},{"key":"D","text":"Compulsory regime with no exit"}],"answer":"B","explanation":"From FY 2023-24, the new regime is the default; taxpayers with business income must file Form 10-IEA to opt out and get only one switch back.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":294,"stem":"Under the OLD regime for FY 2025-26, income from Rs.2,50,001 to Rs.5,00,000 (individual below 60) is taxed at:","options":[{"key":"A","text":"5%"},{"key":"B","text":"20%"},{"key":"C","text":"10%"},{"key":"D","text":"Nil"}],"answer":"A","explanation":"Old regime: 0-2.5L nil, 2.5-5L 5%, 5-10L 20%, above 10L 30%; basic exemption is Rs.2.5L (3L for seniors, 5L for super-seniors).","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":295,"stem":"Under the old regime, a SENIOR CITIZEN (60-79 years) enjoys a basic exemption of:","options":[{"key":"A","text":"Rs.2,00,000"},{"key":"B","text":"Rs.3,00,000"},{"key":"C","text":"Rs.2,50,000"},{"key":"D","text":"Rs.5,00,000"}],"answer":"B","explanation":"Old-regime basic exemption: Rs.2.5L (general), Rs.3L (senior citizens 60-79), Rs.5L (super senior 80+). The new regime has a uniform Rs.4L exemption.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":296,"stem":"Health and Education Cess on income tax (including surcharge) is levied at:","options":[{"key":"A","text":"4%"},{"key":"B","text":"3%"},{"key":"C","text":"1%"},{"key":"D","text":"2%"}],"answer":"A","explanation":"A flat 4% Health and Education Cess applies on tax plus surcharge across all regimes and assessees.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":297,"stem":"Surcharge on income tax for an individual with total income exceeding Rs.50 lakh but up to Rs.1 crore is:","options":[{"key":"A","text":"15%"},{"key":"B","text":"Nil"},{"key":"C","text":"25%"},{"key":"D","text":"10%"}],"answer":"D","explanation":"Surcharge ladder: >50L-1Cr 10%, >1-2Cr 15%, >2-5Cr 25%, >5Cr 37% (old regime); the new regime caps surcharge at 25%.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":298,"stem":"The MAXIMUM surcharge rate for individuals under the NEW tax regime is:","options":[{"key":"A","text":"37%"},{"key":"B","text":"15%"},{"key":"C","text":"10%"},{"key":"D","text":"25%"}],"answer":"D","explanation":"The new regime caps surcharge at 25% even above Rs.5 crore; under the old regime it reaches 37% (but capped at 15% for capital gains and dividends).","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":299,"stem":"Marginal relief in respect of SURCHARGE ensures that:","options":[{"key":"A","text":"Deductions double"},{"key":"B","text":"The TAX INCLUDING SURCHARGE on income slightly above a threshold does not exceed the tax on the threshold plus the EXCESS income"},{"key":"C","text":"No cess applies"},{"key":"D","text":"Tax is nil"}],"answer":"B","explanation":"Marginal relief prevents a small income increase from causing a disproportionate surcharge jump at Rs.50L, Rs.1Cr, Rs.2Cr and Rs.5Cr.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":300,"stem":"Alternative Minimum Tax (Section 115JC) applies to:","options":[{"key":"A","text":"All salaried employees"},{"key":"B","text":"NRIs only"},{"key":"C","text":"NON-COMPANY assessees claiming certain incentives (deductions under Part C of Chapter VI-A other than 80P, s.10AA, and 35AD-linked adjustments), at 18.5% of adjusted total income"},{"key":"D","text":"Companies"}],"answer":"C","explanation":"AMT at 18.5% applies to non-companies claiming specified tax incentives; new-regime taxpayers (no incentives) are out of AMT. Co-operative societies: 15%.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":301,"stem":"Minimum Alternate Tax (MAT) under Section 115JB is levied on:","options":[{"key":"A","text":"Partnership firms"},{"key":"B","text":"HUFs"},{"key":"C","text":"Individuals at 15%"},{"key":"D","text":"COMPANIES - at 15% of BOOK PROFIT where tax on normal total income is lower"}],"answer":"D","explanation":"MAT ensures companies with low taxable income (due to incentives) pay at least 15% of book profit; MAT credit (115JAA) carries forward 15 years.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":302,"stem":"MAT credit under Section 115JAA can be carried forward for:","options":[{"key":"A","text":"10 years"},{"key":"B","text":"8 years"},{"key":"C","text":"15 assessment years"},{"key":"D","text":"Indefinitely"}],"answer":"C","explanation":"MAT credit carries forward 15 assessment years, usable when regular tax exceeds MAT.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":303,"stem":"MAT under Section 115JB does NOT apply to:","options":[{"key":"A","text":"Loss companies"},{"key":"B","text":"All companies"},{"key":"C","text":"Foreign companies"},{"key":"D","text":"Companies opting for Sections 115BAA (22%) or 115BAB (15%) concessional regimes"}],"answer":"D","explanation":"Companies choosing the 115BAA/115BAB concessional rates are exempt from MAT; 115BAB companies also cannot carry forward MAT credit.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":304,"stem":"The concessional rate under Section 115BAA for domestic companies is:","options":[{"key":"A","text":"15%"},{"key":"B","text":"30%"},{"key":"C","text":"22% + 10% surcharge + 4% cess (effective about 25.17%), subject to forgoing specified incentives"},{"key":"D","text":"25%"}],"answer":"C","explanation":"Section 115BAA: 22% flat (25.17% effective) for domestic companies forgoing incentives; 115BAB offers 15% for new manufacturing companies.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":305,"stem":"A FIRM (partnership) is taxed at a flat rate of:","options":[{"key":"A","text":"Slab rates"},{"key":"B","text":"25%"},{"key":"C","text":"20%"},{"key":"D","text":"30% + 4% cess (plus 12% surcharge above Rs.1 crore)"}],"answer":"D","explanation":"Firms and LLPs pay a flat 30%; LLPs have no surcharge; firms get 12% surcharge above Rs.1 crore.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":306,"stem":"A LOCAL AUTHORITY is taxed at:","options":[{"key":"A","text":"Flat 30%"},{"key":"B","text":"25%"},{"key":"C","text":"30%"},{"key":"D","text":"Slab rates"}],"answer":"C","explanation":"Local authorities pay a flat 30% plus 4% cess (12% surcharge above Rs.1 crore).","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":307,"stem":"Co-operative societies are taxed at:","options":[{"key":"A","text":"SLAB rates: 10% up to Rs.10,000, 20% up to Rs.20,000, 30% above (optional 115BAD at 22%)"},{"key":"B","text":"Exempt"},{"key":"C","text":"Flat 30%"},{"key":"D","text":"20% flat"}],"answer":"A","explanation":"Co-operative societies have their own slabs; Section 115BAD offers 22% concession and 115BAE 15% for new manufacturing co-operatives.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":308,"stem":"An individual with total income of Rs.8,00,000 (NEW regime, FY 2025-26) pays tax (before rebate/cess) of:","options":[{"key":"A","text":"Rs.20,000"},{"key":"B","text":"Rs.40,000"},{"key":"C","text":"Rs.25,000"},{"key":"D","text":"Rs.30,000"}],"answer":"A","explanation":"Nil to 4L; 5% of 4L (4-8L) = 20,000. Under 8L total income, new-regime tax is simply 5% of the excess over Rs.4 lakh.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":309,"stem":"A resident individual (age 45) with total income of Rs.10,00,000 in the OLD regime (before cess) pays tax of:","options":[{"key":"A","text":"Rs.1,12,500"},{"key":"B","text":"Rs.1,25,000"},{"key":"C","text":"Rs.85,000"},{"key":"D","text":"Rs.1,17,500"}],"answer":"A","explanation":"Old regime: nil to 2.5L; 5% of 2.5L = 12,500 (2.5-5L); 20% of 5L = 1,00,000 (5-10L). Total = 1,12,500.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":310,"stem":"A resident individual (age 45) with total income of Rs.10,00,000 in the NEW regime (before cess) pays tax of:","options":[{"key":"A","text":"Rs.40,000"},{"key":"B","text":"Rs.60,000"},{"key":"C","text":"Rs.1,12,500"},{"key":"D","text":"Rs.50,000"}],"answer":"A","explanation":"New regime: 5% of Rs.4L (4-8L) = 20,000; 10% of Rs.2L (8-10L within the 8-12L slab) = 20,000. Total Rs.40,000.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":311,"stem":"Health and Education Cess of 4% applies on:","options":[{"key":"A","text":"Total income"},{"key":"B","text":"Income tax AS INCREASED BY SURCHARGE"},{"key":"C","text":"Deductions"},{"key":"D","text":"Gross total income"}],"answer":"B","explanation":"Cess is computed on the tax-plus-surcharge amount, not on the income.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":312,"stem":"In the NEW regime, an individual with total income of exactly Rs.12,00,000 (FY 2025-26) pays income tax of:","options":[{"key":"A","text":"Rs.1,00,000"},{"key":"B","text":"NIL - the 87A rebate (up to Rs.60,000) wipes out the entire tax"},{"key":"C","text":"Rs.36,000"},{"key":"D","text":"Rs.60,000"}],"answer":"B","explanation":"Tax at Rs.12L = 20,000 (4-8L at 5%) + 40,000 (8-12L at 10%) = 60,000, fully rebated under 87A.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":313,"stem":"In the OLD regime, an individual with total income of Rs.5,00,000 pays tax of:","options":[{"key":"A","text":"Rs.25,000"},{"key":"B","text":"NIL - rebate under 87A (up to Rs.12,500) applies for total income up to Rs.5 lakh"},{"key":"C","text":"Rs.12,500"},{"key":"D","text":"Rs.10,000"}],"answer":"B","explanation":"Old regime: 5% of Rs.2.5L = Rs.12,500, fully rebated by 87A at the Rs.5-lakh threshold.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":314,"stem":"For special rates: STCG on equity (111A) is taxed at 20%, LTCG on equity (112A) at 12.5% above Rs.1.25 lakh, and listed-bond/unlisted gains under 112 at:","options":[{"key":"A","text":"10%"},{"key":"B","text":"12.5% WITHOUT indexation (20%-with-indexation option preserved only for resident individuals/HUF on land/building acquired before 23-7- 2024)"},{"key":"C","text":"30%"},{"key":"D","text":"20% with indexation always"}],"answer":"B","explanation":"Finance (No. 2) Act 2024 reworked capital-gains rates: flat 12.5% without indexation for most long-term assets, with a grandfathering choice for pre-July-2024 land/building.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":315,"stem":"The holding period for LONG-TERM capital asset status is now:","options":[{"key":"A","text":"24 months for all"},{"key":"B","text":"48 months"},{"key":"C","text":"36 months for all assets"},{"key":"D","text":"12 months (listed securities/listed units) or 24 months (other assets) - the 36-month tier was removed from FY 2024-25"}],"answer":"D","explanation":"Post-23-7-2024, only two holding tiers survive: 12 months for listed securities and units of equity-oriented funds/business trusts, 24 months for everything else.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":316,"stem":"Short-term capital gains on debt mutual funds and unlisted debentures are taxed:","options":[{"key":"A","text":"At 10%"},{"key":"B","text":"Exempt"},{"key":"C","text":"At 12.5%"},{"key":"D","text":"At SLAB rates - as ordinary income (specified mutual funds acquired after 1-4-2023 lose LTCG/indexation entirely)"}],"answer":"D","explanation":"Specified mutual funds (<=35% domestic equity) and market-linked debentures are deemed short-term regardless of holding period.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":317,"stem":"Lottery winnings, crossword puzzles and race winnings are taxed at:","options":[{"key":"A","text":"20%"},{"key":"B","text":"A FLAT 30% (plus surcharge and cess) under Section 115BB, with no expenditure deduction"},{"key":"C","text":"10%"},{"key":"D","text":"Slab rates"}],"answer":"B","explanation":"Casual income under 115BB carries a flat 30% rate, no deductions, no basic exemption benefit.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":318,"stem":"Income of a political party is exempt under Section 13A provided it:","options":[{"key":"A","text":"Maintains books, accepts no donation above Rs.2,000 other than by account-payee means, and files a return in time"},{"key":"B","text":"Pays 30% tax"},{"key":"C","text":"Registers with RBI"},{"key":"D","text":"Holds elections"}],"answer":"A","explanation":"Section 13A exemption is conditional on books of account, the Rs.2,000 non-cash donation limit, audited accounts and a timely return.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":319,"stem":"For an individual, the ADVANCE TAX liability arises if the estimated tax payable (after TDS) is:","options":[{"key":"A","text":"Rs.10,000 or more - except RESIDENT SENIOR CITIZENS without business/profession income"},{"key":"B","text":"Rs.50,000 or more"},{"key":"C","text":"Rs.5,000 or more"},{"key":"D","text":"Any amount"}],"answer":"A","explanation":"Advance tax is payable in four instalments where net tax liability reaches Rs.10,000; resident seniors (60+) without business income are exempt.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":320,"stem":"Advance tax instalments (non-44AD/44ADA) are: 15% by ________, 45% by ________, 75% by ________, 100% by 15 March:","options":[{"key":"A","text":"15 June, 15 September, 15 December"},{"key":"B","text":"15 July, 15 October, 15 January"},{"key":"C","text":"1 June, 1 September, 1 December"},{"key":"D","text":"30 June, 30 September, 31 December"}],"answer":"A","explanation":"The quarterly ladder is cumulative: 15% (15 Jun), 45% (15 Sep), 75% (15 Dec), 100% (15 Mar). Presumptive taxpayers (44AD/44ADA) pay 100% by 15 March only.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":321,"stem":"Presumptive taxpayers under Sections 44AD/44ADA pay their entire advance tax:","options":[{"key":"A","text":"Not at all"},{"key":"B","text":"In four instalments"},{"key":"C","text":"On 31 March"},{"key":"D","text":"In ONE instalment by 15 MARCH"}],"answer":"D","explanation":"The single 15-March instalment replaces the four-instalment schedule for presumptive-business and presumptive-profession taxpayers.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":322,"stem":"A domestic company opting out of 115BAA/115BAB with turnover up to Rs.400 crore (FY 2023-24) is taxed at:","options":[{"key":"A","text":"22%"},{"key":"B","text":"15%"},{"key":"C","text":"30%"},{"key":"D","text":"25%"}],"answer":"D","explanation":"The 25% rate applies to domestic companies with turnover/gross receipts up to Rs.400 crore in FY 2023-24; others pay 30%.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":323,"stem":"Foreign companies are taxed on royalty/FTS income from approved Indian agreements at:","options":[{"key":"A","text":"15%"},{"key":"B","text":"10%"},{"key":"C","text":"30%"},{"key":"D","text":"40% on other income; specified royalty/FTS at 20% (agreements after 1-4-1976) under the Act, subject to DTAA"}],"answer":"D","explanation":"Foreign companies pay 40% base rate (surcharge 2%/5%) with special 20% rates for specified royalty and fees for technical services, subject to treaties.","source":"Original","module":"T8","topic":"Tax Rates, Regimes, Surcharge, MAT & AMT","reviewStatus":"Source key not independently verified"},{"id":324,"stem":"TDS on SALARY (Section 192) is deducted:","options":[{"key":"A","text":"At a flat 10%"},{"key":"B","text":"Only for government employees"},{"key":"C","text":"At 20%"},{"key":"D","text":"At the AVERAGE RATE of tax on the estimated salary income for the year, after allowing deductions declared by the employee"}],"answer":"D","explanation":"The employer computes the full-year tax on estimated salary (considering regime choice and declared deductions) and deducts evenly across months.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified"},{"id":325,"stem":"Section 192A covers TDS on:","options":[{"key":"A","text":"Salary"},{"key":"B","text":"Rent"},{"key":"C","text":"Interest"},{"key":"D","text":"Premature withdrawal from the RECOGNISED PROVIDENT FUND - 10% if payment is Rs.50,000 or more and service is under 5 years"}],"answer":"D","explanation":"Taxable premature EPF withdrawals of Rs.50,000+ attract 10% TDS (20% if PAN is not furnished).","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified"},{"id":326,"stem":"TDS under Section 193 applies to:","options":[{"key":"A","text":"Rent"},{"key":"B","text":"INTEREST ON SECURITIES - 10%, with a threshold of Rs.10,000 (interest on listed debentures paid by account payee cheque: threshold Rs.5,000)"},{"key":"C","text":"Commission"},{"key":"D","text":"Salary"}],"answer":"B","explanation":"193 covers interest on securities at 10%; the Rs.10,000 threshold was aligned by Finance Act 2025.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified"},{"id":327,"stem":"TDS on DIVIDEND (Section 194) for a resident shareholder is:","options":[{"key":"A","text":"10% where the dividend exceeds Rs.10,000 in the year (Rs.5,000 earlier - raised 1-4-2025)"},{"key":"B","text":"5%"},{"key":"C","text":"20%"},{"key":"D","text":"Nil"}],"answer":"A","explanation":"Dividend TDS is 10% above Rs.10,000; dividend income itself is taxable in the shareholder hands since FY 2020-21.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified"},{"id":328,"stem":"TDS under Section 194A (interest other than on securities) is:","options":[{"key":"A","text":"5%"},{"key":"B","text":"10% with no threshold"},{"key":"C","text":"20% flat"},{"key":"D","text":"10% - threshold Rs.50,000 (Rs.1,00,000 for SENIOR CITIZENS) for banks/post offices/co-operative banks, and Rs.10,000 for others (raised from 1-4-2025)"}],"answer":"D","explanation":"194A: 10% TDS; Finance Act 2025 raised the bank interest threshold to Rs.50,000 (Rs.1 lakh for seniors) and the others threshold to Rs.10,000.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified"},{"id":329,"stem":"Section 194C covers TDS on payments to:","options":[{"key":"A","text":"CONTRACTORS and sub-contractors - 1% for individuals/HUF, 2% for others; single payment threshold Rs.30,000, annual aggregate Rs.1,00,000"},{"key":"B","text":"Doctors"},{"key":"C","text":"Employees"},{"key":"D","text":"Landlords"}],"answer":"A","explanation":"194C: 1%/2% on contract payments; thresholds Rs.30,000 single and Rs.1,00,000 aggregate per financial year.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified"},{"id":330,"stem":"A TRANSPORT contractor holding 10 or fewer goods carriages and furnishing PAN is:","options":[{"key":"A","text":"Taxed at 5%"},{"key":"B","text":"Taxed at 2%"},{"key":"C","text":"EXEMPT from TDS under 194C (declaration with PAN required)"},{"key":"D","text":"Taxed at 10%"}],"answer":"C","explanation":"Small transporters (up to 10 goods carriages) escape 194C TDS on furnishing PAN and a declaration.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified"},{"id":331,"stem":"TDS under Section 194-I on RENT is:","options":[{"key":"A","text":"2% for everything"},{"key":"B","text":"10% for land/building/furniture/fittings; 2% for plant & machinery - threshold Rs.50,000 PER MONTH (monthly basis from 1-4-2025)"},{"key":"C","text":"20%"},{"key":"D","text":"10% for everything"}],"answer":"B","explanation":"194-I: 2% on plant/machinery rent, 10% on land/building/furniture; from April 2025 the threshold is Rs.50,000 per month (replacing the Rs.2.4-lakh annual test).","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified"},{"id":332,"stem":"Section 194-IA covers TDS on purchase of IMMOVABLE PROPERTY (other than agricultural land):","options":[{"key":"A","text":"5%"},{"key":"B","text":"2% above Rs.20 lakh"},{"key":"C","text":"1% where consideration (or SDV) is Rs.50 LAKH or more - buyer deducts, no TAN needed (Form 26QB)"},{"key":"D","text":"10%"}],"answer":"C","explanation":"194-IA: the buyer deducts 1% on transfers of Rs.50 lakh+, deposited via Form 26QB using only PANs.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified"},{"id":333,"stem":"Section 194J (fees for professional or technical services) is deducted at:","options":[{"key":"A","text":"10% - but 2% for technical services, call centres, and royalty for sale/distribution/exhibition of cinematographic films; threshold Rs.50,000 (raised from 1-4-2025)"},{"key":"B","text":"5% flat"},{"key":"C","text":"1%"},{"key":"D","text":"20%"}],"answer":"A","explanation":"194J: 10% general, 2% for technical services/call centres/specified royalty; the Rs.50,000 threshold applies from April 2025.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified"},{"id":334,"stem":"TDS on INSURANCE COMMISSION (Section 194D) is:","options":[{"key":"A","text":"5%"},{"key":"B","text":"1%"},{"key":"C","text":"2% - threshold Rs.20,000 (rate halved from 5% with effect from 1-4-2025; threshold raised from Rs.15,000)"},{"key":"D","text":"10%"}],"answer":"C","explanation":"194D: 2% on insurance commission above Rs.20,000 (Finance (No.2) Act 2024 cut it from 5% w.e.f. 1-4-2025); 194G (lottery tickets commission) is 2% above Rs.20,000; 194H (commission/brokerage) is 2% above Rs.20,000.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified"},{"id":335,"stem":"Section 194H (commission or brokerage other than insurance commission) is deducted at:","options":[{"key":"A","text":"2% above Rs.20,000 (rates recast 1-10-2024; threshold raised 1-4-2025)"},{"key":"B","text":"10%"},{"key":"C","text":"5%"},{"key":"D","text":"1%"}],"answer":"A","explanation":"194H is 2% (reduced from 5% in October 2024) with a Rs.20,000 threshold.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified"},{"id":336,"stem":"Section 194Q (buyer of GOODS) requires TDS of:","options":[{"key":"A","text":"10%"},{"key":"B","text":"0.1% on purchases exceeding Rs.50 LAKH in the year - where the buyer turnover exceeded Rs.10 CRORE in the preceding year"},{"key":"C","text":"1% on everything"},{"key":"D","text":"5%"}],"answer":"B","explanation":"194Q: 0.1% on the excess over Rs.50 lakh of goods purchases, applicable to buyers with prior-year turnover above Rs.10 crore.","source":"Source label not detected","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified"},{"id":337,"stem":"Section 194-T (NEW, from 1-4-2025) requires a FIRM to deduct TDS on payments to its PARTNERS (salary, remuneration, commission, bonus, interest) at:","options":[{"key":"A","text":"12% above Rs.1 lakh"},{"key":"B","text":"5%"},{"key":"C","text":"10% where the aggregate exceeds Rs.20,000 in the year"},{"key":"D","text":"No TDS on partner payments"}],"answer":"C","explanation":"194T plugs the partner-payment gap: 10% TDS by the firm on aggregate partner payments above Rs.20,000 per year.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified"},{"id":338,"stem":"TDS on payment to a person WITHOUT PAN (Section 206AA) is:","options":[{"key":"A","text":"5%"},{"key":"B","text":"The HIGHER of: 20%, the rate in force, or the rate specified in the Act"},{"key":"C","text":"The normal rate"},{"key":"D","text":"Nil"}],"answer":"B","explanation":"206AA penalises non-furnishing of PAN: deduction at 20% or the applicable rate, whichever is higher.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified"},{"id":339,"stem":"Sections 206AB and 206CCA (higher TDS/TCS for non-filers of returns) are:","options":[{"key":"A","text":"OMITTED with effect from 1-4-2025 (Finance Act 2025) - but 206AA/206CC (no PAN) continue"},{"key":"B","text":"Applicable at 10%"},{"key":"C","text":"Applicable at 5%"},{"key":"D","text":"Newly introduced in 2025"}],"answer":"A","explanation":"The Finance Act 2025 removed the 206AB/206CCA higher-rate provisions for non-filers, easing compliance.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified"},{"id":340,"stem":"TDS under Section 194N on CASH WITHDRAWALS is:","options":[{"key":"A","text":"1% above Rs.50 lakh"},{"key":"B","text":"10%"},{"key":"C","text":"5% above Rs.20 lakh"},{"key":"D","text":"2% on withdrawals exceeding Rs.1 crore in the year (bank/post office; co-operative banks: Rs.3 crore threshold)"}],"answer":"D","explanation":"194N: 2% on cash withdrawals above Rs.1 crore per year; 2%/5% (above Rs.20 lakh/Rs.1 crore) for those who have not filed returns for 3 years.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified"},{"id":341,"stem":"Section 195 covers TDS on payments to:","options":[{"key":"A","text":"Banks"},{"key":"B","text":"Government"},{"key":"C","text":"Residents"},{"key":"D","text":"NON-RESIDENTS (other than salary) - at rates in force, on the income portion chargeable to tax"}],"answer":"D","explanation":"195 requires deduction on any sum (other than salary) chargeable to tax paid to a non-resident or foreign company; certificates u/s 197 can lower it.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified"},{"id":342,"stem":"An assessee can apply for LOWER or NIL TDS deduction under:","options":[{"key":"A","text":"Section 206AA"},{"key":"B","text":"Section 194"},{"key":"C","text":"Section 195"},{"key":"D","text":"Section 197 - certificate from the Assessing Officer; also Form 15G/15H declarations for no-deduction by eligible persons"}],"answer":"D","explanation":"Section 197 certificates (online Form 13) authorise lower/nil deduction; 15G (individuals) and 15H (senior citizens) are self-declarations of nil tax liability.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified"},{"id":343,"stem":"Form 15H can be filed by:","options":[{"key":"A","text":"A RESIDENT INDIVIDUAL aged 60 or more whose tax on estimated total income is NIL"},{"key":"B","text":"NRIs"},{"key":"C","text":"Any taxpayer"},{"key":"D","text":"Companies"}],"answer":"A","explanation":"15H is the senior-citizen self-declaration for nil TDS; 15G is for others below the taxable threshold.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified"},{"id":344,"stem":"TCS under Section 206C(1) applies to sellers of:","options":[{"key":"A","text":"Services"},{"key":"B","text":"Shares"},{"key":"C","text":"Specified goods: alcoholic liquor, tendu leaves, timber, other forest produce, scrap, minerals (coal/lignite/iron ore) - 1% to 5%"},{"key":"D","text":"All goods"}],"answer":"C","explanation":"206C(1) lists the traditional TCS goods with rates from 1% (scrap, minerals) to 5% (timber under forest lease 2.5%).","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified"},{"id":345,"stem":"TCS on sale of MOTOR VEHICLES under 206C(1F) is:","options":[{"key":"A","text":"5%"},{"key":"B","text":"Nil"},{"key":"C","text":"1% where the value exceeds Rs.10 lakh"},{"key":"D","text":"2%"}],"answer":"C","explanation":"Motor-vehicle TCS: 1% on sale value above Rs.10 lakh, collected by the seller.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified"},{"id":346,"stem":"TCS under 206C(1G) on overseas tour packages and LRS remittances is:","options":[{"key":"A","text":"Nil"},{"key":"B","text":"10% flat"},{"key":"C","text":"2% flat"},{"key":"D","text":"20% above Rs.10 lakh (LRS); education funded by a SPECIFIED LOAN: NIL (from 1-4-2025); education/medical otherwise 5% above Rs.10 lakh; tour packages 5% up to Rs.10 lakh and 20% above"}],"answer":"D","explanation":"Budget 2025: LRS threshold raised to Rs.10 lakh, and TCS on education remittances funded by a financial-institution loan REMOVED; tour packages 5%/20% around Rs.10 lakh.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified"},{"id":347,"stem":"TCS on sale of GOODS under Section 206C(1H) is:","options":[{"key":"A","text":"1%"},{"key":"B","text":"OMITTED with effect from 1-4-2025 (Finance Act 2025) - the provision no longer operates"},{"key":"C","text":"5%"},{"key":"D","text":"0.1% above Rs.50 lakh"}],"answer":"B","explanation":"206C(1H) (goods-sale TCS, overlapping with 194Q) was omitted from April 2025 to cut compliance burden.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified"},{"id":348,"stem":"TDS on winnings from LOTTERY, crossword puzzles, horse races (Section 194B/194BB) is:","options":[{"key":"A","text":"5%"},{"key":"B","text":"30% - with an annual Rs.10,000 aggregate threshold for 194B/194BB (single-transaction threshold replaced by annual aggregate from 1-4- 2025)"},{"key":"C","text":"10%"},{"key":"D","text":"20%"}],"answer":"B","explanation":"Winnings TDS is 30%; from April 2025 the Rs.10,000 test applies to the annual aggregate rather than per transaction. Online games (194BA) are 30% on net winnings with no threshold.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified"},{"id":349,"stem":"Section 194DA covers TDS on:","options":[{"key":"A","text":"Interest"},{"key":"B","text":"Payment of LIFE INSURANCE policy proceeds not exempt under s.10(10D) - 2% (reduced from 5% on 1-10-2024) on the INCOME component above Rs.1 lakh"},{"key":"C","text":"Salary"},{"key":"D","text":"Rent"}],"answer":"B","explanation":"194DA: 2% on the income part of taxable life-insurance payouts exceeding Rs.1 lakh.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified"},{"id":350,"stem":"Every person deducting TDS (except under 194-IA/194-IB/194M cases using challan-cum-statement) must obtain:","options":[{"key":"A","text":"TAN - Tax Deduction Account Number under Section 203A"},{"key":"B","text":"DIN"},{"key":"C","text":"GSTIN"},{"key":"D","text":"PAN only"}],"answer":"A","explanation":"TAN is mandatory for deductors; the specified property/rent/large-payment sections allow PAN-based challan-cum-statements instead.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified"},{"id":351,"stem":"Quarterly TDS statement for SALARY is filed in:","options":[{"key":"A","text":"Form 26Q"},{"key":"B","text":"Form 27Q"},{"key":"C","text":"Form 24Q (Form 16 issued from it to employees by 15 June)"},{"key":"D","text":"Form 16A"}],"answer":"C","explanation":"24Q covers salary TDS and generates Form 16; 26Q covers resident non-salary payments (Form 16A); 27Q covers non-resident payments.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified"},{"id":352,"stem":"The due date for depositing TDS (other than March deductions) is:","options":[{"key":"A","text":"15th of the same month"},{"key":"B","text":"7th of the FOLLOWING month (30 April for March deductions)"},{"key":"C","text":"10th of next month"},{"key":"D","text":"Last day of the month"}],"answer":"B","explanation":"Government deductors deposit the same day (without challan); others by the 7th of the next month; March TDS can go up to 30 April.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified"},{"id":353,"stem":"Interest for LATE DEDUCTION of TDS is ________, and for late DEPOSIT after deduction is ________ (Section 201(1A)):","options":[{"key":"A","text":"2%; 2%"},{"key":"B","text":"1% per month; 1.5% per month"},{"key":"C","text":"1.5%; 1%"},{"key":"D","text":"1%; 1%"}],"answer":"B","explanation":"201(1A): 1% per month for failure to deduct, 1.5% per month for deduction without deposit - each part-month counts as a full month.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified"},{"id":354,"stem":"Fee for late filing of the TDS STATEMENT under Section 234E is:","options":[{"key":"A","text":"Rs.1,000 flat"},{"key":"B","text":"Rs.500 per day"},{"key":"C","text":"Rs.200 per day, capped at the TDS amount"},{"key":"D","text":"Rs.100 per day"}],"answer":"C","explanation":"234E levies Rs.200 per day of delay in furnishing TDS/TCS statements, capped at the tax amount.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified"},{"id":355,"stem":"Section 194R requires TDS on:","options":[{"key":"A","text":"Dividend"},{"key":"B","text":"Rent"},{"key":"C","text":"Salary"},{"key":"D","text":"Any BENEFIT OR PERQUISITE arising from business or profession - 10% where the aggregate value exceeds Rs.20,000 in the year"}],"answer":"D","explanation":"194R (from FY 2022-23) taxes business/profession benefits and perquisites in kind at 10% above Rs.20,000.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified"},{"id":356,"stem":"Section 194S covers TDS on transfer of:","options":[{"key":"A","text":"Shares"},{"key":"B","text":"Immovable property"},{"key":"C","text":"Goods"},{"key":"D","text":"VIRTUAL DIGITAL ASSETS (cryptocurrency, NFTs) - 1% above Rs.50,000 for specified persons (individuals/HUF within limits) and Rs.10,000 for others"}],"answer":"D","explanation":"194S: 1% TDS on VDA transfers; thresholds Rs.50,000 for specified persons (individuals/HUF within limits) and Rs.10,000 for others. VDA gains are taxed at 30% under 115BBH.","source":"Original","module":"T9","topic":"TDS & TCS (AY 2026-27 rates and thresholds)","reviewStatus":"Source key not independently verified"},{"id":357,"stem":"The due date for filing the return of income under Section 139(1) for an INDIVIDUAL (non-audit) is:","options":[{"key":"A","text":"31 October"},{"key":"B","text":"31 JULY of the assessment year"},{"key":"C","text":"31 March"},{"key":"D","text":"30 September"}],"answer":"B","explanation":"Individuals/HUF (non-audit): 31 July; companies and audit cases: 31 October; transfer-pricing reports: 30 November.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":358,"stem":"A BELATED return under Section 139(4) can be filed:","options":[{"key":"A","text":"Within one year of the due date"},{"key":"B","text":"Any time within 4 years"},{"key":"C","text":"Never"},{"key":"D","text":"Up to 31 DECEMBER of the assessment year (or before completion of assessment, whichever is earlier), with a late fee under 234F"}],"answer":"D","explanation":"Belated and revised returns share the same outer limit: 31 December of the AY (9 months after the end of the relevant FY).","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":359,"stem":"A REVISED return under Section 139(5) can be filed:","options":[{"key":"A","text":"Any number of times up to 31 December of the assessment year (or before assessment completion), to correct omissions or wrong statements"},{"key":"B","text":"Only once"},{"key":"C","text":"Within 30 days of filing"},{"key":"D","text":"Only with permission"}],"answer":"A","explanation":"Revised returns replace the original entirely and can be filed repeatedly before the time limit expires.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":360,"stem":"An UPDATED return under Section 139(8A) can be filed within ________ from the end of the relevant assessment year:","options":[{"key":"A","text":"24 months"},{"key":"B","text":"60 months"},{"key":"C","text":"12 months"},{"key":"D","text":"48 MONTHS (Finance Act 2025 raised it from 24 months, effective 1-4-2025), with ADDITIONAL TAX of 25%/50%/60%/70%"}],"answer":"D","explanation":"Updated returns extend to 48 months from the end of the AY; additional tax is 25% (year 1), 50% (year 2), 60% (year 3) and 70% (year 4) of tax-plus-interest.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":361,"stem":"An updated return under 139(8A) CANNOT be filed:","options":[{"key":"A","text":"Without digital signature"},{"key":"B","text":"By companies"},{"key":"C","text":"After 31 December of the AY"},{"key":"D","text":"If it REDUCES tax liability, claims or increases a REFUND, or results in a loss - nor where assessment/reassessment is pending or completed for that year"}],"answer":"D","explanation":"The updated return is only for paying MORE tax - not for reducing liability, claiming refunds or reporting losses.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":362,"stem":"Late fee under Section 234F for a belated return is:","options":[{"key":"A","text":"Rs.5,000 - REDUCED to Rs.1,000 where total income does not exceed Rs.5 lakh; NIL if return filed on time"},{"key":"B","text":"Rs.10,000 flat"},{"key":"C","text":"Rs.500 per day"},{"key":"D","text":"Rs.1,000 always"}],"answer":"A","explanation":"234F: Rs.5,000 late fee (Rs.1,000 for incomes up to Rs.5 lakh), payable for returns filed after the 139(1) due date.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":363,"stem":"A person whose total income exceeds the basic exemption must file a return; in addition, filing is COMPULSORY (seventh proviso to 139(1)) for those who:","options":[{"key":"A","text":"Own a car"},{"key":"B","text":"Own a house"},{"key":"C","text":"Have a PAN"},{"key":"D","text":"Have deposited Rs.1 CRORE or more in current accounts, spent over Rs.2 LAKH on foreign travel, or paid electricity bills over Rs.1 LAKH in the year"}],"answer":"D","explanation":"Specified high-value transactions trigger mandatory filing even below the exemption limit; also applies to professionals/businesses crossing specified turnover/receipt thresholds.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":364,"stem":"Every return must be VERIFIED. A company return must be signed by:","options":[{"key":"A","text":"The MANAGING DIRECTOR - or any director where there is no MD (or by a designated person in specified cases)"},{"key":"B","text":"Any employee"},{"key":"C","text":"The CA"},{"key":"D","text":"The auditor"}],"answer":"A","explanation":"Section 140: individual - himself; HUF - karta; company - MD/director; firm - managing partner; and e-verification applies to e-returns.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":365,"stem":"A return showing a LOSS (other than house-property loss) filed AFTER the due date:","options":[{"key":"A","text":"Is valid but the ASSESSEE LOSES THE RIGHT TO CARRY FORWARD the loss (Section 80)"},{"key":"B","text":"Is invalid"},{"key":"C","text":"Attracts prosecution"},{"key":"D","text":"Is fully valid for all purposes"}],"answer":"A","explanation":"Section 80: carry forward of business/capital/speculation losses requires a return filed within the 139(1) due date; house-property loss (71B) survives belated filing.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":366,"stem":"Defective return notice under Section 139(9) gives the assessee ________ to remove the defect:","options":[{"key":"A","text":"15 days (extendable by the Assessing Officer)"},{"key":"B","text":"30 days"},{"key":"C","text":"7 days"},{"key":"D","text":"60 days"}],"answer":"A","explanation":"Failure to cure the defect within 15 days (or extended time) renders the return invalid - treated as if no return was filed.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":367,"stem":"Summary processing of returns under Section 143(1) involves:","options":[{"key":"A","text":"Refund without checks"},{"key":"B","text":"Detailed scrutiny"},{"key":"C","text":"Centralised adjustments for arithmetical errors, incorrect claims apparent from the return, and disallowances - with intimation sent within 9 MONTHS of the end of the FY in which the return is filed"},{"key":"D","text":"Physical hearing"}],"answer":"C","explanation":"143(1) is the CPC Bangalore automated processing; adjustments need prior intimation and the assessee gets 30 days to respond.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":368,"stem":"A scrutiny notice under Section 143(2) must be served within ________ from the end of the financial year in which the return is furnished:","options":[{"key":"A","text":"6 months"},{"key":"B","text":"12 months"},{"key":"C","text":"18 months"},{"key":"D","text":"3 MONTHS (reduced from 6 months by the Finance Act 2021, applicable from AY 2021-22)"}],"answer":"D","explanation":"The 143(2) time bar of 3 months from the end of the FY of filing keeps scrutiny selection time-bound.","source":"Source label not detected","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":369,"stem":"Section 143(3) refers to:","options":[{"key":"A","text":"Best judgment assessment"},{"key":"B","text":"Self assessment"},{"key":"C","text":"Summary assessment"},{"key":"D","text":"A REGULAR/scrutiny assessment after hearing the assessee on evidence"}],"answer":"D","explanation":"143(3) is the full scrutiny assessment order passed after examination of accounts and evidence.","source":"Source label not detected","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":370,"stem":"Section 144 (best judgment assessment) is made when the assessee:","options":[{"key":"A","text":"Pays advance tax"},{"key":"B","text":"Fails to file a return, fails to comply with notices under 142(1)/143(2), or fails to get special audit done"},{"key":"C","text":"Claims refund"},{"key":"D","text":"Files a return on time"}],"answer":"B","explanation":"Best-judgment assessments proceed ex parte on available material after the assessee defaults on statutory obligations.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":371,"stem":"Income ESCAPING assessment is reassessed under Section:","options":[{"key":"A","text":"147 - with notices under 148 (and 148A show-cause before notice)"},{"key":"B","text":"144"},{"key":"C","text":"139(9)"},{"key":"D","text":"143(3)"}],"answer":"A","explanation":"The reassessment regime: s.147 power, s.148 notice, s.148A pre-notice show-cause procedure, s.149 time limits.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":372,"stem":"Under Section 149, reassessment notice can generally be issued within ________ from the end of the relevant assessment year; up to ________ where escaped income is Rs.50 lakh or more:","options":[{"key":"A","text":"1 year; 3 years"},{"key":"B","text":"3 years 3 months; 5 years 3 months"},{"key":"C","text":"4 years; 6 years"},{"key":"D","text":"2 years; 4 years"}],"answer":"B","explanation":"Current regime (Finance (No.2) Act 2024, w.e.f. 1-9-2024): notice under s.148 within 3 years 3 months from the end of the AY; beyond that, up to 5 years 3 months only where escaped income is Rs.50 lakh or more.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":373,"stem":"Self-assessment tax under Section 140A is payable:","options":[{"key":"A","text":"Only on demand"},{"key":"B","text":"Within one year"},{"key":"C","text":"BEFORE filing the return - for the tax due on the returned income after TDS, advance tax and reliefs"},{"key":"D","text":"After assessment"}],"answer":"C","explanation":"140A tax (with interest under 234A/234B/234C) must be paid before the return is filed; the return is defective otherwise.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":374,"stem":"Interest under Section 234A (late filing of return) is charged at:","options":[{"key":"A","text":"1% per month or part of a month on the tax due"},{"key":"B","text":"12% per annum flat"},{"key":"C","text":"2% per month"},{"key":"D","text":"0.5% per month"}],"answer":"A","explanation":"All three deferment interests - 234A (late filing), 234B (short advance tax), 234C (instalment deferment) - run at 1% per month or part.","source":"Source label not detected","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":375,"stem":"Section 234B interest applies when advance tax paid is less than ________ of the assessed tax:","options":[{"key":"A","text":"90%"},{"key":"B","text":"50%"},{"key":"C","text":"100%"},{"key":"D","text":"75%"}],"answer":"A","explanation":"234B: 1% per month from 1 April of the AY until payment, where advance tax falls short of 90% of assessed tax.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":376,"stem":"Section 234C charges interest for:","options":[{"key":"A","text":"DEFERMENT of advance-tax instalments (shortfall below 15%/45%/75%/100% schedule) - 1% per month for 3 months (1 month for the last instalment)"},{"key":"B","text":"Wrong PAN"},{"key":"C","text":"Late filing"},{"key":"D","text":"Non-deduction of TDS"}],"answer":"A","explanation":"234C targets instalment-level shortfalls, with relief where shortfalls arise from capital gains, winnings, or new business income paid in later instalments.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":377,"stem":"Fee under Section 234F is distinct from interest under 234A: 234F applies even when:","options":[{"key":"A","text":"Income is below exemption and no return is due"},{"key":"B","text":"Refund is due"},{"key":"C","text":"TDS is deducted"},{"key":"D","text":"Tax is fully paid but the RETURN IS FILED LATE"}],"answer":"D","explanation":"234F is a filing-delay fee independent of tax payment; 234A is interest on unpaid tax.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":378,"stem":"Section 245 permits:","options":[{"key":"A","text":"Reassessment"},{"key":"B","text":"Penalty waiver"},{"key":"C","text":"SET-OFF of REFUNDS against tax remaining payable, after intimation to the assessee"},{"key":"D","text":"Appeal filing"}],"answer":"C","explanation":"245 requires prior intimation before adjusting a refund against outstanding demands.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":379,"stem":"Interest on REFUNDS under Section 244A is paid at:","options":[{"key":"A","text":"1.5% per month"},{"key":"B","text":"0.5% PER MONTH (6% per annum) - for the period of delay attributable to the department"},{"key":"C","text":"1% per month"},{"key":"D","text":"12% per annum"}],"answer":"B","explanation":"244A: 0.5% per month on refunds; no interest for delay caused by the assessee. Refund below Rs.100 is not paid.","source":"Source label not detected","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":380,"stem":"No refund is granted under Section 237 if the amount is less than:","options":[{"key":"A","text":"Rs.10"},{"key":"B","text":"Rs.1,000"},{"key":"C","text":"Rs.100"},{"key":"D","text":"Rs.500"}],"answer":"C","explanation":"Section 237 read with the rules: refunds below Rs.100 are not issued.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":381,"stem":"Section 156 requires that tax, interest, penalty or other sums demanded be served through:","options":[{"key":"A","text":"An intimation under 143(1)"},{"key":"B","text":"A phone call"},{"key":"C","text":"A NOTICE OF DEMAND in the prescribed form - payable within 30 days of service"},{"key":"D","text":"An email only"}],"answer":"C","explanation":"The 156 demand notice is the trigger for collection; default within 30 days makes the assessee an assessee in default (s.220).","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":382,"stem":"The first appeal against an assessment order lies to:","options":[{"key":"A","text":"The JOINT COMMISSIONER (APPEALS) or COMMISSIONER (APPEALS) under Section 246A - filed in Form 35 within 30 days"},{"key":"B","text":"ITAT"},{"key":"C","text":"Supreme Court"},{"key":"D","text":"High Court"}],"answer":"A","explanation":"Appeal ladder: JCIT(A)/CIT(A) → ITAT (s.253) → High Court on substantial questions of law (s.260A) → Supreme Court (s.261).","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":383,"stem":"The second appeal (against the CIT(A)/JCIT(A) order) lies to the ITAT within ________ of receipt of the order:","options":[{"key":"A","text":"90 days"},{"key":"B","text":"120 days"},{"key":"C","text":"60 days"},{"key":"D","text":"30 days"}],"answer":"C","explanation":"Section 253: ITAT appeal within 60 days; the ITAT is the final fact-finding authority. Fee: Rs.500 to Rs.10,000 by assessed income.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":384,"stem":"An appeal to the HIGH COURT under Section 260A lies only on:","options":[{"key":"A","text":"Penalty orders only"},{"key":"B","text":"A SUBSTANTIAL QUESTION OF LAW, within 120 days of the ITAT order"},{"key":"C","text":"Any grievance"},{"key":"D","text":"Questions of fact"}],"answer":"B","explanation":"High Court and Supreme Court jurisdiction under the Act is confined to questions of law; ITAT is final on facts.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":385,"stem":"Section 264 gives the assessee a remedy of:","options":[{"key":"A","text":"Appeal to ITAT"},{"key":"B","text":"Rectification"},{"key":"C","text":"Refund claim"},{"key":"D","text":"REVISION by the Principal Commissioner/Commissioner in favour of the assessee (s.264) - the revisional order must be passed within 1 year from the end of the FY of the order revised"}],"answer":"D","explanation":"264 revision is an alternative (not cumulative) remedy; the Commissioner may make any inquiry and pass any order in the assessee's favour.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":386,"stem":"RECTIFICATION of mistakes apparent from the record is done under Section:","options":[{"key":"A","text":"147"},{"key":"B","text":"263"},{"key":"C","text":"143(1)"},{"key":"D","text":"154 - by the authority concerned, within 4 years from the end of the financial year in which the order was passed"}],"answer":"D","explanation":"154 rectification covers only mistakes apparent from the record; debatable issues need appeal, not rectification.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":387,"stem":"Section 263 empowers the Principal Commissioner/Commissioner to REVISE an order that is:","options":[{"key":"A","text":"ERRONEOUS AND PREJUDICIAL TO THE INTERESTS OF THE REVENUE, within 2 years from the end of the FY of the order"},{"key":"B","text":"Prejudicial to the assessee"},{"key":"C","text":"Passed by ITAT"},{"key":"D","text":"Time-barred"}],"answer":"A","explanation":"263 revision requires BOTH error and prejudice to revenue; a mere difference of opinion is not enough.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":388,"stem":"Penalty under Section 270A for UNDER-REPORTING of income is ________; for MISREPORTING it is ________:","options":[{"key":"A","text":"10%; 50%"},{"key":"B","text":"100%; 300%"},{"key":"C","text":"200%; 50%"},{"key":"D","text":"50% of tax; 200% of tax"}],"answer":"D","explanation":"270A (from AY 2017-18) replaced the old 271(1)(c): 50% of tax on under-reported income, 200% where the under-reporting is by misreporting.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":389,"stem":"Penalty for failure to get ACCOUNTS AUDITED under Section 44AB (Section 271B) is:","options":[{"key":"A","text":"Rs.10,000"},{"key":"B","text":"Rs.5,000 per day"},{"key":"C","text":"0.5% of turnover/gross receipts, capped at Rs.1,50,000"},{"key":"D","text":"Rs.1 lakh flat"}],"answer":"C","explanation":"271B: half a per cent of total sales/turnover/gross receipts, maximum Rs.1,50,000.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":390,"stem":"Penalty under Section 271AAC applies to income determined under Sections 68-69D (cash credits, unexplained investments etc.):","options":[{"key":"A","text":"10% of tax"},{"key":"B","text":"Nil"},{"key":"C","text":"Tax at 60% (115BBE) PLUS 10% of the TAX payable (i.e. 6% of income) as penalty"},{"key":"D","text":"30%"}],"answer":"C","explanation":"Unexplained income under ss.68-69D is taxed at 60% (plus surcharge/cess) under 115BBE with a 10%-of-tax penalty under 271AAC; no basic exemption or set-off.","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":391,"stem":"The time limit for completing a scrutiny assessment under Section 153 for AY 2022-23 onwards is:","options":[{"key":"A","text":"21 months"},{"key":"B","text":"9 months"},{"key":"C","text":"12 months from the end of the ASSESSMENT YEAR in which the income was first assessable"},{"key":"D","text":"18 months"}],"answer":"C","explanation":"Section 153: regular assessment within 12 months of the end of the relevant AY (was 18/21 months in earlier years).","source":"Original","module":"T10","topic":"Returns, Assessment, Interest & Refunds","reviewStatus":"Source key not independently verified"},{"id":392,"stem":"The Income-tax Act, 2025 (replacing the Income-tax Act, 1961) received Presidential assent on:","options":[{"key":"A","text":"15 August 2025"},{"key":"B","text":"21 AUGUST 2025 - as Act No. 30 of 2025"},{"key":"C","text":"1 April 2025"},{"key":"D","text":"31 March 2025"}],"answer":"B","explanation":"The Income-tax Act 2025 was passed by Parliament in August 2025 and assented on 21-8-2025; it is a simplification rewrite, not a change in tax policy.","source":"Original","module":"T11","topic":"Income-tax Act, 2025 - Awareness Block","reviewStatus":"Source key not independently verified"},{"id":393,"stem":"The Income-tax Act, 2025 comes into force from:","options":[{"key":"A","text":"Immediately on assent"},{"key":"B","text":"1 August 2025"},{"key":"C","text":"1 APRIL 2026"},{"key":"D","text":"1 January 2026"}],"answer":"C","explanation":"The new Act applies from 1-4-2026 (i.e. to \"tax year\" 2026-27 onwards); AY 2026-27 still runs under the 1961 Act.","source":"Original","module":"T11","topic":"Income-tax Act, 2025 - Awareness Block","reviewStatus":"Source key not independently verified"},{"id":394,"stem":"The Income-tax Act, 2025 contains approximately:","options":[{"key":"A","text":"64 sections"},{"key":"B","text":"1000 sections"},{"key":"C","text":"298 sections"},{"key":"D","text":"536 SECTIONS and 16 SCHEDULES - nearly half the size of the 1961 Act's 700+ sections, with far simpler language"}],"answer":"D","explanation":"The 2025 Act has 536 sections in 23 chapters plus 16 schedules - nearly half the length of the 1961 Act, with provisos and explanations folded into the text.","source":"Original","module":"T11","topic":"Income-tax Act, 2025 - Awareness Block","reviewStatus":"Source key not independently verified"},{"id":395,"stem":"Under the Income-tax Act, 2025, the terms \"previous year\" and \"assessment year\" are replaced by:","options":[{"key":"A","text":"A single concept: \"TAX YEAR\""},{"key":"B","text":"Assessment period"},{"key":"C","text":"Accounting period"},{"key":"D","text":"Financial year"}],"answer":"A","explanation":"The dual PY/AY structure collapses into one \"tax year\" (1 April to 31 March), removing a long-standing source of confusion.","source":"Original","module":"T11","topic":"Income-tax Act, 2025 - Awareness Block","reviewStatus":"Source key not independently verified"},{"id":396,"stem":"The Income-tax Act, 2025 is best described as:","options":[{"key":"A","text":"A new tax with higher rates"},{"key":"B","text":"A LANGUAGE-SIMPLIFICATION and consolidation exercise - rates, slabs, exemptions and structure remain the SAME as the 1961 Act as amended up to Finance Act 2025"},{"key":"C","text":"A GST amendment"},{"key":"D","text":"A wealth-tax revival"}],"answer":"B","explanation":"The government stated no policy change is intended: the rewrite shortens sentences, removes obsolete provisions, and uses tables/formulas for clarity.","source":"Original","module":"T11","topic":"Income-tax Act, 2025 - Awareness Block","reviewStatus":"Source key not independently verified"},{"id":397,"stem":"For the JVVNL Junior Accountant exam (Part A), the Income-tax Act 2025 matters mainly because:","options":[{"key":"A","text":"It abolishes TDS"},{"key":"B","text":"It removes PAN"},{"key":"C","text":"Examiners may test AWARENESS items: Act number (30 of 2025), assent date, commencement 1-4-2026, \"tax year\" terminology, and section renumbering"},{"key":"D","text":"It changes slab rates"}],"answer":"C","explanation":"Rates and rules are unchanged, so MCQs will focus on structural facts - terminology, section count, and commencement - rather than new computations.","source":"Original","module":"T11","topic":"Income-tax Act, 2025 - Awareness Block","reviewStatus":"Source key not independently verified"},{"id":398,"stem":"Under the 2025 Act, the definition structure and obsolete provisions (like deductions no longer operative) are:","options":[{"key":"A","text":"Retained as-is"},{"key":"B","text":"Left to rules"},{"key":"C","text":"REMOVED or consolidated - obsolete sections repealed, scattered definitions unified, and tables used for rates/TDS provisions"},{"key":"D","text":"Converted to schedules only"}],"answer":"C","explanation":"Simplification features: removal of 300+ obsolete provisions, tables for TDS rates, formulas for computations, and virtual digital assets brought within \"undisclosed income\" search provisions.","source":"Original","module":"T11","topic":"Income-tax Act, 2025 - Awareness Block","reviewStatus":"Source key not independently verified"},{"id":399,"stem":"Which is TRUE about the transition to the Income-tax Act, 2025?","options":[{"key":"A","text":"Old assessments become void"},{"key":"B","text":"1961 Act provisions CONTINUE for periods up to tax year 2025-26 (AY 2026-27); the 2025 Act governs from tax year 2026-27; rules/notifications follow"},{"key":"C","text":"1961 Act repealed with retrospective effect"},{"key":"D","text":"Both apply simultaneously forever"}],"answer":"B","explanation":"Transitional provisions preserve assessments, appeals and proceedings for earlier years under the 1961 Act; the 2025 Act applies prospectively from 1-4-2026.","source":"Original","module":"T11","topic":"Income-tax Act, 2025 - Awareness Block","reviewStatus":"Source key not independently verified"},{"id":400,"stem":"The methods of depreciation prescribed by Section 32 of the Income-tax Act, 1961 are: (i) Units of production method (ii) Written down value method (iii) Sum of years digits method:","options":[{"key":"A","text":"(i), (ii) and (iii)"},{"key":"B","text":"Only (ii)"},{"key":"C","text":"Only (i) and (ii)"},{"key":"D","text":"Only (i)"}],"answer":"B","explanation":"Only the WDV method is prescribed generally; the straight-line option exists only for power-generating undertakings. Units-of-production and SYD are accounting methods, not tax methods.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":401,"stem":"Mr. X is entitled to transport allowance of Rs.1,800 p.m. for commuting between residence and office and spends Rs.1,400 p.m. The exemption allowed (current law) is:","options":[{"key":"A","text":"Rs.1,400 p.m."},{"key":"B","text":"NIL - the transport-allowance exemption was withdrawn from AY 2019-20 (it survives only as Rs.3,200 p.m. for blind/deaf/orthopedically handicapped employees)"},{"key":"C","text":"Rs.1,800 p.m."},{"key":"D","text":"Rs.1,600 p.m."}],"answer":"B","explanation":"The general transport-allowance exemption ended when standard deduction was introduced; the exam-era key (Rs.1,800) is outdated. Handicapped employees still get Rs.3,200 p.m.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":402,"stem":"As per Section 80G, the maximum deduction allowed for any CASH donation is up to:","options":[{"key":"A","text":"Rs.5,000"},{"key":"B","text":"Rs.10,000"},{"key":"C","text":"Rs.2,000"},{"key":"D","text":"Rs.1,000"}],"answer":"C","explanation":"Cash donations above Rs.2,000 earn no 80G deduction; larger donations must be by cheque, draft or electronic mode.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":403,"stem":"Arrange the e-filing procedure for an income-tax return: I. Login II. Register III. Verification IV. Downloading utility and preparing return V. e-filing the return:","options":[{"key":"A","text":"II, I, V, IV, III"},{"key":"B","text":"II, I, IV, V, III"},{"key":"C","text":"I, III, II, V, IV"},{"key":"D","text":"I, II, III, IV, V"}],"answer":"B","explanation":"Register first, then login, download the utility and prepare the return, e-file it, and finally verify (e-verify).","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":404,"stem":"If the assessee is engaged in the business of growing and manufacturing TEA in India, the AGRICULTURAL income in that case is:","options":[{"key":"A","text":"60% of such business income"},{"key":"B","text":"75% of such business income"},{"key":"C","text":"25% of such business income"},{"key":"D","text":"40% of such business income"}],"answer":"A","explanation":"Rule 8: 60% of tea growing-and-manufacturing income is agricultural (exempt), 40% is business income. For coffee: 65%/75% agricultural by stage; rubber 65%.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":405,"stem":"AMT (Alternate Minimum Tax) provisions are applicable on:","options":[{"key":"A","text":"NON-CORPORATE assessees"},{"key":"B","text":"HUF only"},{"key":"C","text":"Corporate assessees"},{"key":"D","text":"An individual only"}],"answer":"A","explanation":"Section 115JC AMT applies to non-corporates claiming specified incentives; companies face MAT under 115JB instead.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":406,"stem":"X, an employee of a PRIVATE company, gets Rs.30,000 p.m. basic salary and Rs.1,500 p.m. entertainment allowance. The deduction u/s 16(ii) for entertainment allowance is:","options":[{"key":"A","text":"Rs.5,000"},{"key":"B","text":"NIL - the 16(ii) deduction is available ONLY to GOVERNMENT employees"},{"key":"C","text":"Rs.72,000"},{"key":"D","text":"Rs.18,000"}],"answer":"B","explanation":"Entertainment-allowance deduction (least of Rs.5,000, 20% of salary, actual) is exclusively for government employees; private employees get no deduction.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":407,"stem":"Which of the following persons CANNOT use ITR-4 (Sugam)? 1. A director of a company 2. One who has held unlisted equity shares 3. One who has assets located outside India 4. A resident firm (other than LLP) 5. One having income from other sources:","options":[{"key":"A","text":"2, 4 and 5 only"},{"key":"B","text":"1, 2 and 4 only"},{"key":"C","text":"3, 4 and 5 only"},{"key":"D","text":"1, 2 and 3 only"}],"answer":"D","explanation":"Directors, unlisted-share holders and foreign-asset holders are barred from ITR-4 (and ITR-1); a resident non-LLP firm CAN use ITR-4 for presumptive income, and other-sources income is permitted.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":408,"stem":"A, a resident aged 60, earned agricultural income of Rs.5,00,000 and non-agricultural income of Rs.3,00,000 (PY 2019-20). His tax liability is:","options":[{"key":"A","text":"Rs.2,000"},{"key":"B","text":"NIL"},{"key":"C","text":"Rs.72,100"},{"key":"D","text":"Rs.72,000"}],"answer":"B","explanation":"Partial integration: tax on (agri + non-agri = 8L) at senior-citizen rates = 70,000; tax on (agri + basic exemption 3L = 8L) = 70,000. Difference = NIL. Agricultural income only raises the rate, never the base.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":409,"stem":"The due date of the FIRST instalment of advance tax (for all assessees) is:","options":[{"key":"A","text":"15 September"},{"key":"B","text":"15 April"},{"key":"C","text":"15 June"},{"key":"D","text":"15 December"}],"answer":"C","explanation":"Instalments: 15% by 15 June, 45% by 15 September, 75% by 15 December, 100% by 15 March.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":410,"stem":"Match: (a) Section 10(1) (b) Section 10(10C) (c) Section 10(13A) (d) Section 10(10AA) with: (i) Voluntary retirement compensation (ii) Agricultural income (iii) Leave encashment (iv) House rent allowance:","options":[{"key":"A","text":"a-ii, b-i, c-iii, d-iv"},{"key":"B","text":"a-ii, b-i, c-iv, d-iii"},{"key":"C","text":"a-iv, b-ii, c-i, d-iii"},{"key":"D","text":"a-iv, b-iii, c-i, d-ii"}],"answer":"B","explanation":"10(1)-agricultural income; 10(10C)-VRS compensation (up to Rs.5 lakh); 10(13A)-HRA; 10(10AA)-leave encashment.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":411,"stem":"Statement I: An assessee is always a person, but a person may or may not be an assessee. Statement II: \"Person\" includes an individual, HUF, company, firm, AOP/BOI, local authority and every artificial juridical person:","options":[{"key":"A","text":"Both statements are correct"},{"key":"B","text":"Only I is correct"},{"key":"C","text":"Only II is correct"},{"key":"D","text":"Both are incorrect"}],"answer":"A","explanation":"Section 2(7) defines assessee as a person by whom tax or any other sum is payable (etc.) - so every assessee is a person; s.2(31) lists the seven person categories.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":412,"stem":"Residential status under the Indian Income-tax Act is determined for which period?","options":[{"key":"A","text":"The assessment year"},{"key":"B","text":"Both previous and assessment years"},{"key":"C","text":"The PREVIOUS YEAR"},{"key":"D","text":"The accounting year"}],"answer":"C","explanation":"Residential status is always determined with reference to each previous year (s.6); it can differ from year to year.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":413,"stem":"Which losses are allowed to be CARRIED FORWARD and set off in subsequent assessment years? (a) House property loss (b) Business loss (c) Speculation loss (d) Capital loss (e) Loss from owning and maintaining race horses:","options":[{"key":"A","text":"b, c, d, e only"},{"key":"B","text":"a, b, c, d AND e - ALL are carry-forwardable"},{"key":"C","text":"a, b, c, d only"},{"key":"D","text":"a, e only"}],"answer":"B","explanation":"All five carry forward (subject to conditions): HP loss 8 years (71B), business loss 8 years (72), speculation loss 4 years (73), capital loss 8 years (74), race-horse loss 4 years (74A). The printed key omitting (a) is wrong.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":414,"stem":"Presumptive taxation involves:","options":[{"key":"A","text":"Use of INDIRECT METHODS to calculate tax liability, differing from accounts-based computation"},{"key":"B","text":"Transfer of tax liability from State to Centre"},{"key":"C","text":"Calculation of rebate u/s 89"},{"key":"D","text":"Calculation of short-term capital gains"}],"answer":"A","explanation":"Presumptive schemes (44AD/44ADA/44AE etc.) deem income as a fixed percentage of turnover/receipts, bypassing regular books.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":415,"stem":"Arm length price computation methods under Section 92C do NOT include which of the following?","options":[{"key":"A","text":"Transaction net margin method"},{"key":"B","text":"Comparable uncontrolled price method"},{"key":"C","text":"Resale price method"},{"key":"D","text":"SLUMP SALE price method"}],"answer":"D","explanation":"92C lists CUP, resale price, cost plus, profit split, transactional net margin, and any other prescribed method - there is no \"slump sale price method\".","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":416,"stem":"\"Tax holiday\" under the Income-tax Act has been used in the context of which section?","options":[{"key":"A","text":"Section 80D"},{"key":"B","text":"Section 80CCC"},{"key":"C","text":"Section 80-IA"},{"key":"D","text":"Section 10(5)"}],"answer":"C","explanation":"Tax holidays are the profit-linked deductions of ss.80-IA/80-IB/80-IC etc. for infrastructure and specified businesses (largely sunset now).","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":417,"stem":"Rates of income tax under the NEW REGIME applicable for FY 2021-22 included: (a) 5% (b) 10% (c) 12% (d) 15% (e) 20%:","options":[{"key":"A","text":"a, b, d only"},{"key":"B","text":"a, b, c only"},{"key":"C","text":"a, b, d, e only"},{"key":"D","text":"b, c, d, e only"}],"answer":"C","explanation":"The 115BAC ladder runs 5/10/15/20/25/30 - there is no 12% slab (and the FY 2025-26 ladder now runs 5/10/15/20/25/30 with a Rs.4L nil band).","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":418,"stem":"Which are included in \"Salary\" under Section 17(1)? A. Wages B. Any pension or annuity C. Any interest from Government securities D. Any gratuity E. Any advance of salary:","options":[{"key":"A","text":"A, B, C and D only"},{"key":"B","text":"A, B, D and E only"},{"key":"C","text":"A, B, C, D and E"},{"key":"D","text":"C and E only"}],"answer":"B","explanation":"Interest on Government securities is taxed under \"Income from other sources\", never as salary; all the others are within s.17(1).","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":419,"stem":"A is entitled to children education allowance of Rs.80 per month per child for THREE children (Rs.240 p.m.). The exemption is:","options":[{"key":"A","text":"Rs.300 per month"},{"key":"B","text":"Rs.160 per month"},{"key":"C","text":"Rs.240 per month"},{"key":"D","text":"Rs.200 per month"}],"answer":"D","explanation":"Exemption is Rs.100 p.m. per child up to a MAXIMUM OF TWO children = Rs.200 p.m.; the third child allowance is fully taxable.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":420,"stem":"The amount UNUTILISED in the Capital Gains Accounts Scheme (exemption claimed u/s 54) is treated as long-term capital gain in the previous year:","options":[{"key":"A","text":"In which 2 years expire from the date of TRANSFER"},{"key":"B","text":"In which 3 years expire from the date of deposit"},{"key":"C","text":"In which 2 years expire from the date of deposit"},{"key":"D","text":"In which 3 YEARS EXPIRE FROM THE DATE OF TRANSFER"}],"answer":"D","explanation":"The unutilised deposit becomes taxable when the 3-year window (2 years for purchase) from the original transfer lapses.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":421,"stem":"Under Section 80TTB, the benefit available to SENIOR CITIZENS on interest from deposits with banks, post offices or co-operative banks is up to:","options":[{"key":"A","text":"Rs.1,50,000"},{"key":"B","text":"Rs.1,00,000"},{"key":"C","text":"Rs.75,000"},{"key":"D","text":"Rs.50,000"}],"answer":"D","explanation":"80TTB: Rs.50,000 for resident senior citizens on all deposit interest (savings + FD); it replaces 80TTA for them.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":422,"stem":"The fee for LATE FILING of the income-tax return by an individual (current law, Section 234F) is up to a maximum of:","options":[{"key":"A","text":"Rs.5,000 - reduced to Rs.1,000 where total income does not exceed Rs.5 lakh"},{"key":"B","text":"10% of gross total income"},{"key":"C","text":"2% of tax liability"},{"key":"D","text":"Rs.10,000"}],"answer":"A","explanation":"Finance Act 2021 cut the 234F fee from Rs.10,000 to Rs.5,000 (Rs.1,000 for incomes up to Rs.5 lakh); the older Rs.10,000 key is outdated.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":423,"stem":"Statement I: Long-term capital loss can be set off ONLY against long-term capital gains. Statement II: Long-term capital gains on listed equity above Rs.1 lakh are taxed at 10% WITH indexation and 20% WITHOUT indexation:","options":[{"key":"A","text":"Statement II correct, I incorrect"},{"key":"B","text":"Statement I CORRECT, Statement II INCORRECT - 112A gains were 10% WITHOUT indexation above Rs.1 lakh (now 12.5% above Rs.1.25 lakh from FY 2024-25)"},{"key":"C","text":"Both incorrect"},{"key":"D","text":"Both correct"}],"answer":"B","explanation":"LTCL is ring-fenced to LTCG; Statement II inverts the indexation position and is additionally outdated on rate and threshold.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":424,"stem":"Which is NOT correct for the Tonnage Tax Scheme?","options":[{"key":"A","text":"It applies to income from shipping activities"},{"key":"B","text":"It applies to BOTH Indian AND foreign companies"},{"key":"C","text":"Tonnage income computation is covered u/s 115VG"},{"key":"D","text":"It is a presumptive taxation scheme"}],"answer":"B","explanation":"Tonnage tax (ss.115V-115VZC) is available to QUALIFYING INDIAN COMPANIES operating qualifying ships - not foreign companies.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":425,"stem":"Which of the following is NOT related to income tax in India?","options":[{"key":"A","text":"Leave Travel Allowance (LTA)"},{"key":"B","text":"Dearness Allowance (DA)"},{"key":"C","text":"Taxpayer Identification Number (TIN)"},{"key":"D","text":"Tax Deduction and Collection Account Number (TAN)"}],"answer":"C","explanation":"TIN belonged to the state VAT system (now subsumed in GSTIN); DA and LTA are salary components, and TAN is the TDS/TCS account number under s.203A.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":426,"stem":"Match: (A) ITR-2 (B) ITR-6 (C) ITR-7 (D) ITR-4 (Sugam) with: (I) Companies other than those claiming exemption u/s 11 (II) Presumptive business income u/s 44AD/44ADA/44AE (III) Persons required to file u/s 139(4A)/(4B)/(4C)/(4D) (IV) Individuals/HUF without business or professional income:","options":[{"key":"A","text":"A-IV, B-I, C-III, D-II"},{"key":"B","text":"A-I, B-IV, C-II, D-III"},{"key":"C","text":"A-III, B-II, C-IV, D-I"},{"key":"D","text":"A-II, B-III, C-I, D-IV"}],"answer":"A","explanation":"ITR-2: individuals/HUF (no PGBP); ITR-4: presumptive; ITR-6: companies (not s.11-exempt); ITR-7: trusts/political parties/institutions under 139(4A)-(4D).","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":427,"stem":"X was appointed on 1 July 2022 as a university lecturer and continued up to 30 April 2023. The PREVIOUS YEAR for AY 2023-24 for his salary income is:","options":[{"key":"A","text":"1 July 2022 to 30 April 2023"},{"key":"B","text":"1 July 2022 to 31 March 2023"},{"key":"C","text":"1 April 2022 to 31 March 2023"},{"key":"D","text":"1 April 2022 to 30 April 2023"}],"answer":"B","explanation":"For a NEW source of income, the first previous year begins when the source comes into existence (1 July 2022) and ends on the immediately following 31 March (s.3).","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":428,"stem":"For AY 2025-26, Health and Education Cess is levied at:","options":[{"key":"A","text":"4% on income tax"},{"key":"B","text":"3% on income tax"},{"key":"C","text":"2% on income tax"},{"key":"D","text":"1% on income tax"}],"answer":"A","explanation":"4% cess on tax (plus surcharge) - unchanged since FY 2018-19.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":429,"stem":"Match TDS provisions: (A) Fees for professional/technical services (B) Payment of life-insurance policy (C) Winnings from lotteries/crossword puzzles (D) Interest other than on securities:","options":[{"key":"A","text":"A-194A, B-194B, C-194DA, D-194J"},{"key":"B","text":"A-194J, B-194DA, C-194B, D-194A"},{"key":"C","text":"A-194B, B-194J, C-194A, D-194DA"},{"key":"D","text":"A-194DA, B-194A, C-194J, D-194B"}],"answer":"B","explanation":"194J professional/technical fees; 194DA life-insurance payouts; 194B lottery/crossword winnings; 194A interest other than on securities.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":430,"stem":"Match: (A) Standard deduction u/s 16(ia) (B) Standard deduction u/s 24 (C) Depreciation u/s 32 (D) Exemption u/s 54 with heads: (I) Capital gains (II) PGBP (III) House property (IV) Salaries:","options":[{"key":"A","text":"A-IV, B-III, C-II, D-I"},{"key":"B","text":"A-I, B-II, C-III, D-IV"},{"key":"C","text":"A-II, B-I, C-IV, D-III"},{"key":"D","text":"A-III, B-IV, C-I, D-II"}],"answer":"A","explanation":"16(ia)-salaries (Rs.75,000 new regime / Rs.50,000 old); 24(a)-30% house property; 32-depreciation under PGBP; 54-residential-house rollover under capital gains.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":431,"stem":"Mr. A, resident aged 60, earned agricultural income Rs.5,00,000 and non-agricultural income Rs.3,80,000 (AY 2025-26), NOT opting for the old regime. His tax liability is:","options":[{"key":"A","text":"NIL"},{"key":"B","text":"Rs.3,640"},{"key":"C","text":"Rs.38,000"},{"key":"D","text":"Rs.8,000"}],"answer":"A","explanation":"Non-agricultural income (Rs.3.8L) is below the new-regime basic exemption (Rs.4L, FY 2024-25), so partial integration is not even triggered; tax is nil.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Answer/key flagged: AY 2025-26 new-regime basic exemption was ₹3 lakh, not ₹4 lakh; answer needs recalculation."},{"id":432,"stem":"Arm length price under Section 92F is the price applied or proposed to be applied when:","options":[{"key":"A","text":"Two RELATED persons transact in uncontrolled conditions"},{"key":"B","text":"Two unrelated persons transact in controlled conditions"},{"key":"C","text":"Two related persons transact in controlled conditions"},{"key":"D","text":"Two UNRELATED persons transact in UNCONTROLLED conditions"}],"answer":"D","explanation":"The ALP benchmarks a controlled (associated-enterprise) transaction against what unrelated parties would agree in uncontrolled conditions.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":433,"stem":"An assessee (other than one under 44AD/44ADA) must pay up to 75% of advance tax payable:","options":[{"key":"A","text":"On or before 15 June"},{"key":"B","text":"On or before 15 DECEMBER"},{"key":"C","text":"On or before 15 September"},{"key":"D","text":"On or before 15 March"}],"answer":"B","explanation":"The cumulative schedule: 15% by 15 June, 45% by 15 September, 75% by 15 December, 100% by 15 March.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":434,"stem":"Which statements are correct? A. If a company is an Indian company, it is automatically a domestic company. B. A foreign company means a company which is not a domestic company. C. An Indian company can be non-resident in India. D. A foreign company can never be resident in India:","options":[{"key":"A","text":"A and B only"},{"key":"B","text":"All four"},{"key":"C","text":"B and D only"},{"key":"D","text":"A, B and C only"}],"answer":"A","explanation":"An Indian company is always domestic and ALWAYS RESIDENT (s.6(3)); a foreign company CAN be resident if its POEM is in India - so C and D are false.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":435,"stem":"Which section deals with deduction for interest on deposits in SAVINGS ACCOUNTS (below-60 individuals/HUF)?","options":[{"key":"A","text":"Section 80TTA"},{"key":"B","text":"Section 80RRB"},{"key":"C","text":"Section 80U"},{"key":"D","text":"Section 80TTB"}],"answer":"A","explanation":"80TTA: up to Rs.10,000 savings interest for individuals/HUF below 60; 80TTB is the wider senior-citizen provision.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":436,"stem":"Exemption under Section 54EC (capital gains invested in specified bonds - NHAI/REC etc.) is capped at:","options":[{"key":"A","text":"Rs.10 lakh"},{"key":"B","text":"Rs.1 crore"},{"key":"C","text":"Rs.25 lakh"},{"key":"D","text":"Rs.50 LAKH in a financial year, with a 5-YEAR lock-in"}],"answer":"D","explanation":"54EC: investment within 6 months in notified bonds, maximum Rs.50 lakh, 5-year lock-in (earlier 3 years).","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"},{"id":437,"stem":"Relief for salary ARREARS or advance salary under Section 89(1) requires filing:","options":[{"key":"A","text":"FORM 10E - before claiming the relief in the return"},{"key":"B","text":"Form 26AS"},{"key":"C","text":"Form 15G"},{"key":"D","text":"Form 16"}],"answer":"A","explanation":"Section 89 relief spreads arrears to the years they relate to; Form 10E must be furnished online, else the relief is denied in processing.","source":"Source label not detected","module":"T12","topic":"PYQ Module - Verified Income-tax Past Questions","reviewStatus":"Source key not independently verified"}];
